{
  "name": "@kubeclaw/pipeline-observability-contract",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "files": [
    "schemas",
    "src",
    "fixtures",
    "go"
  ],
  "exports": {
    ".": "./src/index.ts",
    "./schema": "./schemas/pipeline-observability.v1.schema.json",
    "./canonical-json": "./src/canonical-json.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "dependencies": {
    "ajv": "^8.20.0",
    "ajv-formats": "^3.0.1"
  }
}

export type ObservabilityDefinition = 'producerIdentity' | 'producerRecord' | 'admissionAcknowledgement' | 'replayRange' | 'gapReport' | 'producerClosure' | 'observabilityCompleteness';
export interface ProducerIdentityV1 { producerId:string; bootId:string; producerType:string }
export interface ProducerCorrelationV1 { pipelineRunId:string; moduleId:string|null; gateId:string|null; attemptId:string|null; claimId:string|null; claimGeneration:number|null; traceId:string|null; parentEventId:string|null }
export interface ProducerRecordV1 { schemaVersion:'producer-record.v1'; recordId:string; producer:ProducerIdentityV1; sequence:number; recordType:string; occurredAt:string; correlation:ProducerCorrelationV1; payload:unknown; recordDigest:string }
export interface AdmissionAcknowledgementV1 { schemaVersion:'admission-acknowledgement.v1'; recordId:string; producer:ProducerIdentityV1; pipelineRunId:string; sequence:number; state:'admitted'|'duplicate'; admittedAt:string; canonicalCursor:number; recordDigest:string }
export interface ReplayRangeV1 { schemaVersion:'replay-range.v1'; producer:ProducerIdentityV1; pipelineRunId:string; fromSequence:number; toSequence:number; requestedAt:string }
export interface ProducerGapReportV1 { schemaVersion:'producer-gap-report.v1'; producer:ProducerIdentityV1; pipelineRunId:string; fromSequence:number; toSequence:number; state:'missing'|'unavailable'|'restored'; reportedAt:string; reasonCode:string }
export interface ProducerClosureV1 { schemaVersion:'producer-closure.v1'; closureId:string; producer:ProducerIdentityV1; pipelineRunId:string; firstSequence:number; finalSequence:number; recordCount:number; requiredEvidenceIds:string[]; closedAt:string; closureDigest:string }
export interface UnresolvedObservabilityItemV1 { itemId:string; kind:'missing-closure'|'missing-evidence'|'quarantined-record'; producer:ProducerIdentityV1; subjectId:string; reasonCode:string }
export interface ObservabilityCompletenessV1 { schemaVersion:'observability-completeness.v1'; pipelineRunId:string; state:'complete'|'partial'|'degraded'|'unknown'; requiredClosureIds:string[]; admittedClosureIds:string[]; missingClosureIds:string[]; missingRanges:ProducerGapReportV1[]; unresolvedItems:UnresolvedObservabilityItemV1[]; evaluatedAt:string }
export interface ContractValidationResult { ok:boolean; errors:string[] }

import { canonicalJson } from './canonical-json.ts';
export { canonicalJson } from './canonical-json.ts';
import crypto from 'node:crypto';
import fs from 'node:fs';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';
import type { ContractValidationResult, ObservabilityCompletenessV1, ObservabilityDefinition, ProducerClosureV1, ProducerGapReportV1, ProducerRecordV1, ReplayRangeV1 } from './types.ts';

type Validator=((value:unknown)=>boolean)&{errors?:unknown[]|null};
interface AjvInstance { addSchema(schema:object):void; compile(schema:object):Validator }
const schema=JSON.parse(fs.readFileSync(new URL('../schemas/pipeline-observability.v1.schema.json',import.meta.url),'utf8')) as {$id:string};
const AjvConstructor=Ajv2020 as unknown as new(options:{allErrors:boolean;strict:boolean})=>AjvInstance;
const installFormats=addFormats as unknown as(instance:AjvInstance)=>AjvInstance;
const ajv=new AjvConstructor({allErrors:true,strict:true}); installFormats(ajv); ajv.addSchema(schema);
const validators=new Map<string,Validator>();
export function contentDigest(value:unknown):string { return `sha256:${crypto.createHash('sha256').update(canonicalJson(value)).digest('hex')}`; }
export function producerRecordDigest(record:Omit<ProducerRecordV1,'recordDigest'>|ProducerRecordV1):string { const {recordDigest:_,...unsigned}=record as ProducerRecordV1;return contentDigest(unsigned); }
export function producerClosureDigest(closure:Omit<ProducerClosureV1,'closureDigest'>|ProducerClosureV1):string { const {closureDigest:_,...unsigned}=closure as ProducerClosureV1;return contentDigest(unsigned); }
function errors(value:unknown[]|null|undefined):string[]{return value?.map((item)=>{const error=item as {instancePath?:string;message?:string};return `${error.instancePath||'/'} ${error.message||'is invalid'}`;})??['validation failed'];}
function relations(definition:ObservabilityDefinition,value:unknown):string[]{
  if(definition==='producerRecord'){const record=value as ProducerRecordV1;return producerRecordDigest(record)===record.recordDigest?[]:['/recordDigest does not match the immutable record'];}
  if(definition==='replayRange'){const range=value as ReplayRangeV1;return range.toSequence>=range.fromSequence?[]:['/toSequence must not be before /fromSequence'];}
  if(definition==='gapReport'){const gap=value as ProducerGapReportV1;return gap.toSequence>=gap.fromSequence?[]:['/toSequence must not be before /fromSequence'];}
  if(definition==='producerClosure'){const closure=value as ProducerClosureV1;const rangeOk=closure.recordCount===0?(closure.firstSequence===0&&closure.finalSequence===0):(closure.firstSequence===1&&closure.finalSequence>=closure.firstSequence&&closure.recordCount===closure.finalSequence);const result:string[]=[];if(!rangeOk)result.push('/recordCount must describe a run sequence interval that starts at one');if(producerClosureDigest(closure)!==closure.closureDigest)result.push('/closureDigest does not match the immutable closure');return result;}
  if(definition==='observabilityCompleteness'){const completeness=value as ObservabilityCompletenessV1;const result:string[]=[];const required=new Set(completeness.requiredClosureIds);const admitted=new Set(completeness.admittedClosureIds);const missing=new Set(completeness.missingClosureIds);if(completeness.admittedClosureIds.some((id)=>!required.has(id))||completeness.missingClosureIds.some((id)=>!required.has(id)))result.push('/admittedClosureIds and /missingClosureIds must be subsets of /requiredClosureIds');if(completeness.requiredClosureIds.some((id)=>(admitted.has(id)?1:0)+(missing.has(id)?1:0)!==1))result.push('/requiredClosureIds must be partitioned between admitted and missing closures');const itemIds=new Set(completeness.unresolvedItems.map((item)=>item.itemId));if(itemIds.size!==completeness.unresolvedItems.length)result.push('/unresolvedItems must use unique itemId values');if(completeness.missingClosureIds.some((id)=>!completeness.unresolvedItems.some((item)=>item.kind==='missing-closure'&&item.subjectId===id)))result.push('/missingClosureIds require an attributed missing-closure item');if(completeness.missingRanges.some((gap)=>gap.pipelineRunId!==completeness.pipelineRunId))result.push('/missingRanges must belong to /pipelineRunId');if(completeness.missingRanges.some((gap)=>gap.toSequence<gap.fromSequence))result.push('/missingRanges must use ordered sequence ranges');if(completeness.missingRanges.some((gap)=>gap.state==='restored'))result.push('/missingRanges can contain only unresolved missing or unavailable ranges');const hasCause=completeness.missingClosureIds.length>0||completeness.missingRanges.length>0||completeness.unresolvedItems.length>0;if(completeness.state==='complete'&&hasCause)result.push('/state complete requires all closures and no unresolved observability items');if(completeness.state!=='complete'&&!hasCause)result.push('/state partial, degraded, or unknown requires an attributed observability cause');return result;}
  return [];
}
export function checkPipelineObservabilityContract(definition:ObservabilityDefinition,value:unknown):ContractValidationResult{let validate=validators.get(definition);if(!validate){validate=ajv.compile({$ref:`${schema.$id}#/$defs/${definition}`}) as Validator;validators.set(definition,validate);}if(!validate(value))return{ok:false,errors:errors(validate.errors)};const relationErrors=relations(definition,value);return{ok:relationErrors.length===0,errors:relationErrors};}
export function validatePipelineObservabilityContract(definition:ObservabilityDefinition,value:unknown):void{const result=checkPipelineObservabilityContract(definition,value);if(!result.ok)throw new Error(`OBSERVABILITY_CONTRACT_INVALID:${definition}:${result.errors.join(';')}`);}
export function decodePipelineObservabilityContract(definition:ObservabilityDefinition,raw:Uint8Array|string):unknown{if(raw instanceof Uint8Array&&raw.length>=3&&raw[0]===0xef&&raw[1]===0xbb&&raw[2]===0xbf)throw new Error('OBSERVABILITY_WIRE_BOM_FORBIDDEN');const text=typeof raw==='string'?raw:new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(raw);const value=JSON.parse(text) as unknown;if(canonicalJson(value)!==text)throw new Error('OBSERVABILITY_WIRE_NOT_RFC8785_CANONICAL');validatePipelineObservabilityContract(definition,value);return value;}

{
  "name": "@kubeclaw/pipeline-test-gate-contract",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "files": [
    "schemas",
    "src"
  ],
  "exports": {
    ".": "./src/index.ts",
    "./schema": "./schemas/pipeline-test-gate.v1.schema.json",
    "./e2e-result-schema": "./schemas/e2e-result.v1.schema.json",
    "./gate-decision": "./src/gate-decision.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "node ../../../tests/verification/integration/pipeline-gate-remediation.test.mts && node --test ../../../tests/verification/integration/pipeline-gate-coverage.test.mts"
  },
  "dependencies": {
    "@kubeclaw/pipeline-observability-contract": "*",
    "ajv": "^8.20.0",
    "ajv-formats": "^3.0.1"
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://kubeclaw.dev/contracts/pipeline-test-gate/e2e-result.v1.schema.json",
  "title": "KubeClaw common end-to-end provider result",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "provider", "targetOrigin", "workers", "browserProjects", "testCases", "counts", "reportFormat", "resourceEnforcement"],
  "properties": {
    "schemaVersion": { "const": "e2e-result.v1" },
    "provider": { "type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$" },
    "targetOrigin": { "type": "string", "format": "uri", "maxLength": 2048 },
    "workers": { "type": "integer", "minimum": 1, "maximum": 1024 },
    "browserProjects": {
      "type": "array",
      "maxItems": 256,
      "uniqueItems": true,
      "items": { "type": "string", "minLength": 1, "maxLength": 256 }
    },
    "testCases": {
      "type": "array",
      "minItems": 1,
      "maxItems": 100000,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "title", "project", "status", "attempts", "errors"],
        "properties": {
          "id": { "type": "string", "pattern": "^sha256:[a-f0-9]{64}$" },
          "title": { "type": "string", "minLength": 1, "maxLength": 2048 },
          "project": { "type": ["string", "null"], "maxLength": 256 },
          "browser": { "type": ["string", "null"], "maxLength": 128 },
          "status": { "enum": ["passed", "failed", "skipped", "unexecuted"] },
          "attempts": { "type": "integer", "minimum": 0, "maximum": 1000 },
          "errors": {
            "type": "array",
            "maxItems": 1000,
            "items": { "type": "string", "minLength": 1, "maxLength": 4096 }
          }
        }
      }
    },
    "counts": {
      "type": "object",
      "additionalProperties": false,
      "required": ["total", "passed", "failed", "skipped", "unexecuted"],
      "properties": {
        "total": { "type": "integer", "minimum": 1 },
        "passed": { "type": "integer", "minimum": 0 },
        "failed": { "type": "integer", "minimum": 0 },
        "skipped": { "type": "integer", "minimum": 0 },
        "unexecuted": { "type": "integer", "minimum": 0 }
      }
    },
    "reportFormat": { "type": "string", "minLength": 1, "maxLength": 128 },
    "resourceEnforcement": { "enum": ["cgroup-v2", "sampled"] }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://kubeclaw.dev/contracts/pipeline-test-gate/v1/schema.json",
  "title": "KubeClaw pipeline test-gate contracts v1",
  "$defs": {
    "nonEmptyString": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
    },
    "stableId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:/-]*$",
      "maxLength": 256
    },
    "contractId": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._/-]*@[1-9][0-9]*$",
      "maxLength": 256
    },
    "digest": {
      "type": "string",
      "pattern": "^sha256:[a-f0-9]{64}$"
    },
    "relativePath": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096,
      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
    },
    "jsonValue": {
      "oneOf": [
        { "type": "null" },
        { "type": "boolean" },
        { "type": "number" },
        { "type": "string" },
        {
          "type": "array",
          "items": { "$ref": "#/$defs/jsonValue" }
        },
        {
          "type": "object",
          "additionalProperties": { "$ref": "#/$defs/jsonValue" }
        }
      ]
    },
    "jsonObject": {
      "type": "object",
      "maxProperties": 256,
      "additionalProperties": { "$ref": "#/$defs/jsonValue" }
    },
    "packageRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["packageId", "packageVersion", "contentDigest"],
      "properties": {
        "packageId": { "$ref": "#/$defs/stableId" },
        "packageVersion": { "$ref": "#/$defs/nonEmptyString" },
        "contentDigest": { "$ref": "#/$defs/digest" }
      }
    },
    "providerRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["packageId", "packageVersion", "contentDigest", "registrationId", "contractId"],
      "properties": {
        "packageId": { "$ref": "#/$defs/stableId" },
        "packageVersion": { "$ref": "#/$defs/nonEmptyString" },
        "contentDigest": { "$ref": "#/$defs/digest" },
        "registrationId": { "$ref": "#/$defs/stableId" },
        "contractId": { "$ref": "#/$defs/contractId" }
      }
    },
    "receiptRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["receiptId", "receiptDigest"],
      "properties": {
        "receiptId": { "$ref": "#/$defs/stableId" },
        "receiptDigest": { "$ref": "#/$defs/digest" }
      }
    },
    "portDeclaration": {
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "kind", "required"],
      "properties": {
        "name": { "$ref": "#/$defs/stableId" },
        "kind": { "enum": ["value", "artifact"] },
        "required": { "type": "boolean" },
        "schemaId": { "$ref": "#/$defs/nonEmptyString" },
        "mediaTypes": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/nonEmptyString" },
          "uniqueItems": true
        }
      },
      "allOf": [
        {
          "if": { "properties": { "kind": { "const": "value" } } },
          "then": {
            "required": ["schemaId"],
            "properties": {
              "schemaId": { "$ref": "#/$defs/nonEmptyString" },
              "mediaTypes": false
            }
          },
          "else": {
            "required": ["mediaTypes"],
            "properties": {
              "mediaTypes": {
                "type": "array",
                "minItems": 1,
                "items": { "$ref": "#/$defs/nonEmptyString" },
                "uniqueItems": true
              }
            }
          }
        }
      ]
    },
    "evidencePolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["onPass", "onFail", "onError"],
      "properties": {
        "onPass": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        },
        "onFail": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        },
        "onError": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        }
      }
    },
    "executionLimits": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "cpuMillis",
        "memoryBytes",
        "logBytes",
        "artifactBytes",
        "artifactFiles",
        "processes"
      ],
      "properties": {
        "cpuMillis": { "type": "integer", "minimum": 1 },
        "memoryBytes": { "type": "integer", "minimum": 1 },
        "logBytes": { "type": "integer", "minimum": 0 },
        "artifactBytes": { "type": "integer", "minimum": 0 },
        "artifactFiles": { "type": "integer", "minimum": 0 },
        "processes": { "type": "integer", "minimum": 1 }
      }
    },
    "providerDetails": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schemaId", "schemaDigest", "values"],
      "properties": {
        "schemaId": { "$ref": "#/$defs/nonEmptyString" },
        "schemaDigest": { "$ref": "#/$defs/digest" },
        "values": { "$ref": "#/$defs/jsonObject" }
      }
    },
    "providerRegistration": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schemaVersion",
        "registrationId",
        "contractId",
        "kind",
        "package",
        "entrypoint",
        "configSchema",
        "inputs",
        "outputs",
        "capabilities",
        "retrySafe",
        "matrixFields",
        "reportFormats",
        "evidenceTypes",
        "evidenceDefaults"
      ],
      "properties": {
        "schemaVersion": { "const": "provider-registration.v1" },
        "registrationId": { "$ref": "#/$defs/stableId" },
        "contractId": { "$ref": "#/$defs/contractId" },
        "kind": { "enum": ["test", "fixture"] },
        "package": { "$ref": "#/$defs/packageRef" },
        "entrypoint": {
          "type": "object",
          "additionalProperties": false,
          "required": ["module", "export"],
          "properties": {
            "module": { "$ref": "#/$defs/relativePath" },
            "export": { "$ref": "#/$defs/stableId" }
          }
        },
        "configSchema": { "$ref": "#/$defs/relativePath" },
        "inputs": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/portDeclaration" }
        },
        "outputs": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/portDeclaration" }
        },
        "capabilities": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        },
        "retrySafe": { "type": "boolean" },
        "matrixFields": {
          "type": "array",
          "maxItems": 64,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        },
        "reportFormats": {
          "type": "array",
          "maxItems": 32,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        },
        "evidenceTypes": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        },
        "evidenceDefaults": { "$ref": "#/$defs/evidencePolicy" }
      }
    },
    "providerConfiguration": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schemaVersion", "contractId", "schemaDigest", "values"],
      "properties": {
        "schemaVersion": { "const": "provider-configuration.v1" },
        "contractId": { "$ref": "#/$defs/contractId" },
        "schemaDigest": { "$ref": "#/$defs/digest" },
        "values": { "$ref": "#/$defs/jsonObject" }
      }
    },
    "typedLink": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schemaVersion", "kind", "from", "to"],
      "properties": {
        "schemaVersion": { "const": "typed-link.v1" },
        "kind": { "enum": ["value", "artifact"] },
        "from": {
          "type": "object",
          "additionalProperties": false,
          "required": ["nodeId", "output"],
          "properties": {
            "nodeId": { "$ref": "#/$defs/stableId" },
            "output": { "$ref": "#/$defs/stableId" }
          }
        },
        "to": {
          "type": "object",
          "additionalProperties": false,
          "required": ["nodeId", "input"],
          "properties": {
            "nodeId": { "$ref": "#/$defs/stableId" },
            "input": { "$ref": "#/$defs/stableId" }
          }
        },
        "schemaId": { "$ref": "#/$defs/nonEmptyString" },
        "mediaType": { "$ref": "#/$defs/nonEmptyString" }
      },
      "allOf": [
        {
          "if": { "properties": { "kind": { "const": "value" } } },
          "then": {
            "required": ["schemaId"],
            "properties": {
              "schemaId": { "$ref": "#/$defs/nonEmptyString" },
              "mediaType": false
            }
          },
          "else": {
            "required": ["mediaType"],
            "properties": { "mediaType": { "$ref": "#/$defs/nonEmptyString" } }
          }
        }
      ]
    },
    "dependency": {
      "type": "object",
      "additionalProperties": false,
      "required": ["nodeId", "acceptedResults"],
      "properties": {
        "nodeId": { "$ref": "#/$defs/stableId" },
        "acceptedResults": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "enum": ["passed", "failed", "skipped", "errored", "cancelled", "timed_out"]
          }
        }
      }
    },
    "resolvedPlanNode": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "executionId",
        "testIdentity",
        "suiteInstanceId",
        "kind",
        "provider",
        "reportAdapters",
        "mode",
        "configuration",
        "dependencies",
        "timeoutMs",
        "limits",
        "retryCount",
        "concurrencyGroup",
        "parentNodeId",
        "variation",
        "evidence",
        "skipReason"
      ],
      "properties": {
        "id": { "$ref": "#/$defs/stableId" },
        "executionId": { "$ref": "#/$defs/stableId" },
        "testIdentity": { "type": "string", "pattern": "^test:[a-f0-9]{64}$" },
        "suiteInstanceId": {
          "oneOf": [{ "$ref": "#/$defs/stableId" }, { "type": "null" }]
        },
        "kind": { "enum": ["test", "fixture"] },
        "provider": { "$ref": "#/$defs/providerRef" },
        "reportAdapters": {
          "type": "array",
          "maxItems": 32,
          "items": { "$ref": "#/$defs/reportAdapterRef" }
        },
        "mode": {
          "oneOf": [
            { "enum": ["blocking", "advisory"] },
            { "type": "null" }
          ]
        },
        "reviewAgent": {
          "oneOf": [
            { "$ref": "#/$defs/stableId" },
            { "type": "null" }
          ]
        },
        "configuration": { "$ref": "#/$defs/providerConfiguration" },
        "dependencies": {
          "type": "array",
          "maxItems": 256,
          "items": { "$ref": "#/$defs/dependency" }
        },
        "timeoutMs": { "type": "integer", "minimum": 1 },
        "limits": { "$ref": "#/$defs/executionLimits" },
        "retryCount": { "type": "integer", "minimum": 0 },
        "concurrencyGroup": {
          "oneOf": [
            { "$ref": "#/$defs/stableId" },
            { "type": "null" }
          ]
        },
        "parentNodeId": {
          "oneOf": [
            { "$ref": "#/$defs/stableId" },
            { "type": "null" }
          ]
        },
        "variation": { "$ref": "#/$defs/jsonObject" },
