import crypto from 'node:crypto';
import { execFile } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { promisify } from 'node:util';
import type { TestProviderCapabilityRequest } from '@kubeclaw/plugin-sdk';
import type { TestProviderCapabilityInvoker } from './runner.ts';

const execFileDefault = promisify(execFile);
const NAME = /^[a-z0-9](?:[a-z0-9._-]{0,126}[a-z0-9])?$/u;
const DIGEST = /^sha256:[a-f0-9]{64}$/u;
const PLATFORM = /^linux\/[a-z0-9_+-]+(?:\/[a-z0-9._+-]+)?$/u;
const ARGUMENT = /^[A-Za-z_][A-Za-z0-9_]*$/u;
const MAX_TIMER_MS = 2_147_483_647;
const ACCEPT = [
  'application/vnd.oci.image.manifest.v1+json',
  'application/vnd.oci.image.index.v1+json',
  'application/vnd.docker.distribution.manifest.v2+json',
  'application/vnd.docker.distribution.manifest.list.v2+json',
].join(', ');

type Execute = (command: string, args: readonly string[], options: Readonly<Record<string, unknown>>) => Promise<{ stdout?: string; stderr?: string }>;

export interface ContainerBuildCapabilityInvokerOptions {
  readonly workspaceRoot: string;
  readonly buildctlExecutable: string;
  readonly buildkitHost: string;
  readonly registryBaseUrl: string;
  readonly registryReference: string;
  readonly repositoryPrefix: string;
  readonly allowedPlatforms: readonly string[];
  readonly allowedBuildArguments?: readonly string[];
  readonly maximumLogBytes: number;
  readonly maximumExecutionMs: number;
  readonly maximumManifestBytes: number;
  readonly registryUsername?: string;
  readonly registryPassword?: string;
  readonly execute?: Execute;
  readonly fetch?: typeof globalThis.fetch;
}

function positive(value: unknown, maximum: number): number {
  if (!Number.isSafeInteger(value) || Number(value) < 1) throw new Error('CONTAINER_BUILD_LIMIT_INVALID');
  return Math.min(Number(value), maximum);
}

function contained(root: string, value: unknown, label: string, kind: 'file' | 'directory'): string {
  if (typeof value !== 'string' || !path.isAbsolute(value)) throw new Error(`CONTAINER_BUILD_PATH_INVALID:${label}`);
  const canonical = fs.realpathSync(value);
  if (canonical !== root && !canonical.startsWith(`${root}${path.sep}`)) throw new Error(`CONTAINER_BUILD_PATH_DENIED:${label}`);
  const stat = fs.statSync(canonical);
  if ((kind === 'file' && !stat.isFile()) || (kind === 'directory' && !stat.isDirectory())) throw new Error(`CONTAINER_BUILD_PATH_TYPE_INVALID:${label}`);
  return canonical;
}

function within(root: string, value: string): boolean {
  return value === root || value.startsWith(`${root}${path.sep}`);
}

function stringMap(value: unknown): Record<string, string> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('CONTAINER_BUILD_ARGUMENTS_INVALID');
  const entries = Object.entries(value);
  if (entries.length > 32 || entries.some(([key, item]) => !ARGUMENT.test(key) || typeof item !== 'string'
    || item.length > 4096 || item.includes('\0'))) throw new Error('CONTAINER_BUILD_ARGUMENTS_INVALID');
  return Object.fromEntries(entries as [string, string][]);
}

function digestFromMetadata(file: string): string {
  const parsed = JSON.parse(fs.readFileSync(file, 'utf8')) as Record<string, unknown>;
  const value = parsed['containerimage.digest'];
  if (typeof value !== 'string' || !DIGEST.test(value)) throw new Error('CONTAINER_BUILD_DIGEST_MISSING');
  return value;
}

function message(error: unknown): string {
  if (error instanceof Error) return error.message.slice(0, 4096);
  return String(error).slice(0, 4096);
}

function executionError(code: string, error: unknown): Error {
  // Runner serialization retains error.message, so the cause alone is insufficient.
  const diagnostic = error instanceof Error ? error.message : String(error);
  return new Error(diagnostic === code || diagnostic.startsWith(`${code}:`)
    ? diagnostic : `${code}:${diagnostic}`, { cause: error });
}

export function containerBuildExecutionError(error: unknown, phase: 'build' | 'verify'): Error {
  const diagnostic = error instanceof Error ? error.message : String(error);
  const code = phase === 'verify'
    ? (/^CONTAINER_BUILD_[A-Z0-9_]+/u.exec(diagnostic)?.[0] ?? 'CONTAINER_BUILD_REGISTRY_ERROR')
    : 'CONTAINER_BUILD_EXECUTION_ERROR';
  return executionError(code, error);
}

function commandOutput(error: unknown, field: 'stdout' | 'stderr'): string {
  if (!error || typeof error !== 'object') return '';
  const value = (error as Record<string, unknown>)[field];
  return typeof value === 'string' ? value : Buffer.isBuffer(value) ? value.toString('utf8') : '';
}

export function createContainerBuildDeadline(started: number, maximumExecutionMs: number, caller: AbortSignal) {
  const expiresAt = started + maximumExecutionMs;
  const remainingMs = () => Math.max(0, expiresAt - Date.now());
  const controller = new AbortController();
  const expire = () => controller.abort(new Error('CONTAINER_BUILD_TIMEOUT'));
  const timer = setTimeout(expire, remainingMs());
  if (remainingMs() === 0) expire();
  return { signal: AbortSignal.any([caller, controller.signal]), remainingMs,
    dispose: () => clearTimeout(timer) };
}

export async function verifyContainerManifest(
  options: Pick<ContainerBuildCapabilityInvokerOptions, 'registryUsername' | 'registryPassword' | 'maximumManifestBytes' | 'fetch'>,
  baseUrl: URL, repository: string, digest: string, signal: AbortSignal,
): Promise<void> {
  const url = new URL(`/v2/${repository.split('/').map(encodeURIComponent).join('/')}/manifests/${digest}`, baseUrl);
  const headers: Record<string, string> = { Accept: ACCEPT };
  if (options.registryUsername !== undefined) {
    headers.Authorization = `Basic ${Buffer.from(`${options.registryUsername}:${options.registryPassword}`).toString('base64')}`;
  }
  const response = await (options.fetch ?? globalThis.fetch)(url, { method: 'GET', headers, signal, redirect: 'error' });
  if (!response.ok) {
    await response.body?.cancel();
    throw new Error(`CONTAINER_BUILD_REGISTRY_READ_FAILED:${response.status}`);
  }
  const declaredLength = Number(response.headers.get('content-length'));
  if (Number.isFinite(declaredLength) && declaredLength > options.maximumManifestBytes) {
    await response.body?.cancel();
    throw new Error('CONTAINER_BUILD_REGISTRY_MANIFEST_TOO_LARGE');
  }
  if (!response.body) throw new Error('CONTAINER_BUILD_REGISTRY_MANIFEST_SIZE_INVALID');
  const reader = response.body.getReader();
  const hash = crypto.createHash('sha256');
  let received = 0;
  try {
    for (;;) {
      const part = await reader.read();
      if (part.done) break;
      received += part.value.byteLength;
      if (received > options.maximumManifestBytes) {
        await reader.cancel('CONTAINER_BUILD_REGISTRY_MANIFEST_TOO_LARGE');
        throw new Error('CONTAINER_BUILD_REGISTRY_MANIFEST_TOO_LARGE');
      }
      hash.update(part.value);
    }
  } finally {
    await reader.cancel().catch(() => {});
    reader.releaseLock();
  }
  if (received < 1) throw new Error('CONTAINER_BUILD_REGISTRY_MANIFEST_SIZE_INVALID');
  const actual = `sha256:${hash.digest('hex')}`;
  const header = response.headers.get('docker-content-digest');
  if (actual !== digest || (header !== null && header !== digest)) throw new Error('CONTAINER_BUILD_REGISTRY_DIGEST_MISMATCH');
}

export class ContainerBuildCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #root: string;
  readonly #buildctl: string;
  readonly #host: string;
  readonly #baseUrl: URL;
  readonly #registryReference: string;
  readonly #prefix: string;
  readonly #platforms: ReadonlySet<string>;
  readonly #buildArguments: ReadonlySet<string>;
  readonly #options: ContainerBuildCapabilityInvokerOptions;
  readonly #execute: Execute;

  constructor(options: ContainerBuildCapabilityInvokerOptions) {
    this.#root = fs.realpathSync(options.workspaceRoot);
    this.#buildctl = fs.realpathSync(options.buildctlExecutable);
    fs.accessSync(this.#buildctl, fs.constants.X_OK);
    if (!options.buildkitHost || options.buildkitHost.includes('\0')) throw new Error('CONTAINER_BUILD_BUILDKIT_HOST_INVALID');
    this.#host = options.buildkitHost;
    this.#baseUrl = new URL(options.registryBaseUrl);
    if (!['http:', 'https:'].includes(this.#baseUrl.protocol) || this.#baseUrl.username || this.#baseUrl.password
      || (this.#baseUrl.pathname !== '/' && this.#baseUrl.pathname !== '')) throw new Error('CONTAINER_BUILD_REGISTRY_URL_INVALID');
    if (!/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/u.test(options.registryReference)) throw new Error('CONTAINER_BUILD_REGISTRY_REFERENCE_INVALID');
    if (this.#baseUrl.host !== options.registryReference) throw new Error('CONTAINER_BUILD_REGISTRY_ENDPOINT_MISMATCH');
    this.#registryReference = options.registryReference;
    if (!/^[a-z0-9]+(?:[._/-][a-z0-9]+)*$/u.test(options.repositoryPrefix)) throw new Error('CONTAINER_BUILD_REPOSITORY_PREFIX_INVALID');
    this.#prefix = options.repositoryPrefix.replace(/\/+$/u, '');
    if (options.allowedPlatforms.length < 1 || options.allowedPlatforms.some((item) => !PLATFORM.test(item))) throw new Error('CONTAINER_BUILD_PLATFORMS_INVALID');
    this.#platforms = new Set(options.allowedPlatforms);
    const allowedBuildArguments = options.allowedBuildArguments ?? [];
    if (allowedBuildArguments.length > 32 || allowedBuildArguments.some((item) => !ARGUMENT.test(item))
      || new Set(allowedBuildArguments).size !== allowedBuildArguments.length) throw new Error('CONTAINER_BUILD_ARGUMENT_ALLOWLIST_INVALID');
    this.#buildArguments = new Set(allowedBuildArguments);
    for (const [value, label] of [[options.maximumLogBytes, 'LOG'], [options.maximumExecutionMs, 'TIME'], [options.maximumManifestBytes, 'MANIFEST']] as const) {
      if (!Number.isSafeInteger(value) || value < 1 || value > Number.MAX_SAFE_INTEGER) throw new Error(`CONTAINER_BUILD_${label}_LIMIT_INVALID`);
    }
    if ((options.registryUsername === undefined) !== (options.registryPassword === undefined)) throw new Error('CONTAINER_BUILD_REGISTRY_CREDENTIALS_INCOMPLETE');
    if (options.registryUsername !== undefined && this.#baseUrl.protocol !== 'https:'
      && !['127.0.0.1', 'localhost', '::1'].includes(this.#baseUrl.hostname)) {
      throw new Error('CONTAINER_BUILD_REGISTRY_CREDENTIALS_REQUIRE_TLS');
    }
    this.#options = options;
    this.#execute = options.execute ?? (async (command, args, settings) => execFileDefault(command, [...args], settings) as Promise<{ stdout?: string; stderr?: string }>);
  }

  async invoke(capability: string, request: TestProviderCapabilityRequest, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    const started = Date.now();
    if (capability !== 'container.build' || request.operation !== 'build_push_verify'
      || request.resource.type !== 'container.build-definition' || !/^build:[a-z0-9._-]+:attempt:[a-z0-9._:-]+$/u.test(request.resource.canonicalId)) {
      throw new Error('CONTAINER_BUILD_CAPABILITY_REQUEST_INVALID');
    }
    const payload = request.payload;
    const repository = contained(this.#root, payload.repositoryRoot, 'repositoryRoot', 'directory');
    const scratch = contained(this.#root, payload.scratchRoot, 'scratchRoot', 'directory');
    const context = contained(this.#root, payload.buildContext, 'buildContext', 'directory');
    const dockerfile = contained(this.#root, payload.dockerfile, 'dockerfile', 'file');
    if (!within(repository, context)) throw new Error('CONTAINER_BUILD_CONTEXT_OUTSIDE_REPOSITORY');
    if (!within(repository, dockerfile) && !within(scratch, dockerfile)) throw new Error('CONTAINER_BUILD_DOCKERFILE_OUTSIDE_PROVIDER_ROOTS');
    if (typeof payload.outputName !== 'string' || !NAME.test(payload.outputName)) throw new Error('CONTAINER_BUILD_OUTPUT_NAME_INVALID');
    if (typeof payload.definitionIdentity !== 'string' || payload.definitionIdentity.length < 1 || payload.definitionIdentity.length > 1024) {
      throw new Error('CONTAINER_BUILD_DEFINITION_IDENTITY_INVALID');
    }
    if (typeof payload.platform !== 'string' || !this.#platforms.has(payload.platform)) throw new Error('CONTAINER_BUILD_PLATFORM_DENIED');
    const limits = payload.limits as Record<string, unknown> | null;
    if (!limits || typeof limits !== 'object' || Array.isArray(limits)) throw new Error('CONTAINER_BUILD_LIMIT_INVALID');
    const maximumLogBytes = positive(limits.maximumLogBytes, this.#options.maximumLogBytes);
    const maximumExecutionMs = positive(limits.maximumExecutionMs, Math.min(this.#options.maximumExecutionMs, MAX_TIMER_MS));
    const buildArgs = stringMap(payload.buildArgs);
    if (Object.keys(buildArgs).some((name) => !this.#buildArguments.has(name))) throw new Error('CONTAINER_BUILD_ARGUMENT_DENIED');
    const target = payload.target;
    if (target !== undefined && (typeof target !== 'string' || !NAME.test(target))) throw new Error('CONTAINER_BUILD_TARGET_INVALID');
    const suffix = crypto.createHash('sha256').update(request.resource.canonicalId).digest('hex').slice(0, 24);
    const registryRepository = `${this.#prefix}/${payload.outputName}`;
    const registryImage = `${this.#registryReference}/${registryRepository}:run-${suffix}`;
    const temporary = fs.mkdtempSync(path.join(this.#root, '.container-build-'));
    const metadata = path.join(temporary, 'metadata.json');
    const dockerConfig = path.join(temporary, 'docker-config');
    if (this.#options.registryUsername !== undefined) {
      fs.mkdirSync(dockerConfig, { mode: 0o700 });
      fs.writeFileSync(path.join(dockerConfig, 'config.json'), JSON.stringify({ auths: {
        [this.#registryReference]: { auth: Buffer.from(`${this.#options.registryUsername}:${this.#options.registryPassword}`).toString('base64') },
      } }), { mode: 0o600 });
    }
    const args = ['--addr', this.#host, 'build', '--frontend', 'dockerfile.v0', '--local', `context=${context}`,
      '--local', `dockerfile=${path.dirname(dockerfile)}`, '--opt', `filename=${path.basename(dockerfile)}`,
      '--opt', `platform=${payload.platform}`];
    if (target) args.push('--opt', `target=${target}`);
    for (const [name, value] of Object.entries(buildArgs).sort(([left], [right]) => left.localeCompare(right))) args.push('--opt', `build-arg:${name}=${value}`);
    args.push('--output', `type=image,name=${registryImage},push=true${this.#baseUrl.protocol === 'http:' ? ',registry.insecure=true' : ''}`,
      '--metadata-file', metadata);
    const deadline = createContainerBuildDeadline(started, maximumExecutionMs, signal);
    let phase: 'build' | 'verify' = 'build';
    let stdout = ''; let stderr = '';
    try {
      deadline.signal.throwIfAborted();
      const result = await this.#execute(this.#buildctl, args, { encoding: 'utf8', maxBuffer: maximumLogBytes,
        timeout: deadline.remainingMs(), signal: deadline.signal, env: { PATH: path.dirname(this.#buildctl), BUILDKIT_HOST: this.#host,
          ...(this.#options.registryUsername === undefined ? {} : { DOCKER_CONFIG: dockerConfig }) } });
      stdout = result.stdout ?? ''; stderr = result.stderr ?? '';
      phase = 'verify';
      deadline.signal.throwIfAborted();
      const digest = digestFromMetadata(metadata);
      await verifyContainerManifest(this.#options, this.#baseUrl, registryRepository, digest, deadline.signal);
      deadline.signal.throwIfAborted();
      return Object.freeze({ ok: true, stdout, stderr, registryImage, digest,
        immutableImage: `${this.#registryReference}/${registryRepository}@${digest}`, durationMs: Date.now() - started,
        definitionIdentity: payload.definitionIdentity, platform: payload.platform });
    } catch (error) {
      if (signal.aborted) throw executionError('CONTAINER_BUILD_CANCELLED', error);
      if (deadline.signal.aborted || deadline.remainingMs() <= 0) throw executionError('CONTAINER_BUILD_TIMEOUT', error);
      const commandError = error as { code?: unknown; killed?: boolean; signal?: unknown };
      // A completed nonzero BuildKit command retains its failed build result.
      // Verification, launch, and resource-limit failures remain execution errors.
      if (phase !== 'build' || !Number.isInteger(commandError?.code) || commandError.killed || commandError.signal) {
        throw containerBuildExecutionError(error, phase);
      }
      stdout ||= commandOutput(error, 'stdout'); stderr ||= commandOutput(error, 'stderr');
      const failureMessage = message(error);
      const classified = /^(CONTAINER_BUILD_[A-Z0-9_]+)/u.exec(failureMessage)?.[1] ?? 'CONTAINER_BUILD_FAILED';
      return Object.freeze({ ok: false, stdout, stderr, errorCode: classified, message: failureMessage, durationMs: Date.now() - started });
    } finally {
      deadline.dispose();
      fs.rmSync(temporary, { recursive: true, force: true });
    }
  }
}

import { spawn } from 'node:child_process';
import crypto from 'node:crypto';

export interface DependencyProcessOptions {
  readonly executable: string;
  readonly args: readonly string[];
  readonly maximumExecutionMs: number;
  readonly maximumOutputBytes: number;
  readonly signal?: AbortSignal;
}
export interface DependencyProcessResult {
  readonly ok: boolean;
  readonly code: 'DEPENDENCY_OK' | 'DEPENDENCY_CANCELLED' | 'DEPENDENCY_TIMEOUT' | 'DEPENDENCY_OUTPUT_LIMIT' | 'DEPENDENCY_SPAWN_FAILED' | 'DEPENDENCY_EXIT_FAILED';
  readonly exitCode: number | null;
  readonly signal: string | null;
  readonly errno: string | null;
  readonly outputBytes: number;
  readonly outputDigest: string;
  readonly durationMs: number;
}

export function validateDependencyProcessLimits(options: Pick<DependencyProcessOptions, 'maximumExecutionMs' | 'maximumOutputBytes'>): void {
  for (const [value, maximum] of [[options.maximumExecutionMs, 30_000], [options.maximumOutputBytes, 1024 * 1024]] as const) {
    if (!Number.isSafeInteger(value) || value < 1 || value > maximum) throw new Error('DEPENDENCY_PROCESS_LIMIT_INVALID');
  }
}

/** Wait for actual child closure after termination; never race against detached work. */
export async function runDependencyProcess(options: DependencyProcessOptions): Promise<DependencyProcessResult> {
  validateDependencyProcessLimits(options);
  const started = Date.now();
  if (options.signal?.aborted) return { ok: false, code: 'DEPENDENCY_CANCELLED', exitCode: null, signal: null, errno: null,
    outputBytes: 0, outputDigest: `sha256:${crypto.createHash('sha256').digest('hex')}`, durationMs: 0 };
  return await new Promise<DependencyProcessResult>((resolve) => {
    const child = spawn(options.executable, [...options.args], {
      detached: true, stdio: ['ignore', 'pipe', 'pipe'], env: { PATH: '/usr/local/bin:/usr/bin:/bin', LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' },
    });
    let failure: DependencyProcessResult['code'] | undefined;
    let errno: string | null = null;
    let outputBytes = 0;
    const digest = crypto.createHash('sha256');
    const stop = (code: DependencyProcessResult['code']): void => {
      failure ??= code;
      if (!child.pid) return;
      try { process.kill(-child.pid, 'SIGKILL'); }
      catch (error) {
        const code = (error as NodeJS.ErrnoException).code;
        if (code !== 'ESRCH') { errno = 'TERMINATION_FAILED'; child.kill('SIGKILL'); }
      }
    };
    const cancel = (): void => stop('DEPENDENCY_CANCELLED');
    options.signal?.addEventListener('abort', cancel, { once: true });
    if (options.signal?.aborted) cancel();
    const timer = setTimeout(() => stop('DEPENDENCY_TIMEOUT'), options.maximumExecutionMs);
    const output = (chunk: Buffer): void => {
      if (failure) return;
      outputBytes += chunk.byteLength;
      if (outputBytes > options.maximumOutputBytes) { stop('DEPENDENCY_OUTPUT_LIMIT'); return; }
      digest.update(chunk);
    };
    child.stdout.on('data', output); child.stderr.on('data', output);
    child.once('error', (error: NodeJS.ErrnoException) => {
      failure ??= 'DEPENDENCY_SPAWN_FAILED';
      errno = typeof error.code === 'string' && /^[A-Z0-9_]+$/u.test(error.code) ? error.code : 'UNKNOWN';
    });
    child.once('close', (exitCode, signal) => {
      clearTimeout(timer);
      options.signal?.removeEventListener('abort', cancel);
      const code = failure ?? (exitCode === 0 ? 'DEPENDENCY_OK' : 'DEPENDENCY_EXIT_FAILED');
      resolve({ ok: code === 'DEPENDENCY_OK', code, exitCode, signal, errno, outputBytes,
        outputDigest: `sha256:${digest.digest('hex')}`, durationMs: Date.now() - started });
    });
  });
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CommandRunError, CommandRunner } from '@kubeclaw/plugin-command-runner/runner';
import type { TestProviderCapabilityRequest } from '@kubeclaw/plugin-sdk';
import type { TestProviderCapabilityInvoker } from './runner.ts';

const CATALOG_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/u;
const ENVIRONMENT_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/u;
const PROTECTED_ENVIRONMENT = /^(?:BUSTER_|NOVA_|KUBECLAW_|OPENAI_|AWS_|AZURE_|GOOGLE_|GITHUB_|PATH$|HOME$|TMPDIR$|USER$|SHELL$|NODE_OPTIONS$|NODE_PATH$|LD_|DYLD_|SSL_CERT_|SSH_|GIT_|NPM_TOKEN$|.*(?:TOKEN|SECRET|PASSWORD|PRIVATE_KEY|CREDENTIAL).*)/u;

function canonicalExecutable(value: string): string {
  const result = fs.realpathSync(value);
  if (!path.isAbsolute(result) || !fs.statSync(result).isFile()) throw new Error('DIRECT_COMMAND_CATALOG_EXECUTABLE_INVALID');
  fs.accessSync(result, fs.constants.X_OK);
  return result;
}

function containedDirectory(root: string, value: unknown): string {
  if (typeof value !== 'string') throw new Error('DIRECT_COMMAND_WORKING_DIRECTORY_INVALID');
  const result = fs.realpathSync(value);
  if (!fs.statSync(result).isDirectory() || (result !== root && !result.startsWith(`${root}${path.sep}`))) {
    throw new Error('DIRECT_COMMAND_WORKING_DIRECTORY_DENIED');
  }
  return result;
}

function commandArguments(value: unknown): string[] {
  if (!Array.isArray(value) || value.length > 256 || value.some((item) => typeof item !== 'string'
    || item.length > 4096 || item.includes('\0'))) throw new Error('DIRECT_COMMAND_ARGUMENTS_INVALID');
  return [...value] as string[];
}

function environment(value: unknown): Record<string, string> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('DIRECT_COMMAND_ENVIRONMENT_INVALID');
  const entries = Object.entries(value);
  if (entries.length > 65 || entries.some(([name, item]) => !ENVIRONMENT_NAME.test(name)
    || (name !== 'CI' && PROTECTED_ENVIRONMENT.test(name)) || typeof item !== 'string'
    || item.includes('\0') || Buffer.byteLength(item) > 4096)) {
    throw new Error('DIRECT_COMMAND_ENVIRONMENT_INVALID');
  }
  return Object.fromEntries(entries as [string, string][]);
}

function positiveLimit(value: unknown, maximum: number): number {
  if (!Number.isSafeInteger(value) || Number(value) < 1) throw new Error('DIRECT_COMMAND_LIMIT_INVALID');
  return Math.min(Number(value), maximum);
}

export interface DirectCommandCapabilityInvokerOptions {
  readonly workspaceRoot: string;
  readonly executableCatalog: ReadonlyMap<string, string>;
  readonly executableSearchPath: readonly string[];
  readonly runtimeReadRoots: readonly string[];
  readonly maximumOutputBytes: number;
  readonly maximumExecutionMs: number;
  readonly maximumProcesses: number;
  readonly maximumMemoryBytes: number;
  readonly maximumCpuMillis: number;
  readonly terminationGraceMs: number;
  readonly cgroupRoot?: string;
  readonly allowSampledProcessLimit?: boolean;
}

export class DirectCommandCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #root: string;
  readonly #catalog: ReadonlyMap<string, string>;
  readonly #runner: CommandRunner;
  readonly #limits: DirectCommandCapabilityInvokerOptions;
  readonly #path: string;
  readonly #readRoots: readonly string[];

  constructor(options: DirectCommandCapabilityInvokerOptions) {
    this.#root = fs.realpathSync(options.workspaceRoot);
    this.#catalog = new Map([...options.executableCatalog].map(([name, executable]) => {
      if (!CATALOG_NAME.test(name)) throw new Error(`DIRECT_COMMAND_CATALOG_NAME_INVALID:${name}`);
      return [name, canonicalExecutable(executable)];
    }));
    if (this.#catalog.size === 0) throw new Error('DIRECT_COMMAND_CATALOG_EMPTY');
    if (options.executableSearchPath.length === 0) throw new Error('DIRECT_COMMAND_SEARCH_PATH_EMPTY');
    this.#path = options.executableSearchPath.map((directory) => {
      const canonical = fs.realpathSync(directory);
      if (!path.isAbsolute(canonical) || !fs.statSync(canonical).isDirectory()) {
        throw new Error('DIRECT_COMMAND_SEARCH_PATH_INVALID');
      }
      return canonical;
    }).join(path.delimiter);
    if (options.runtimeReadRoots.length === 0) throw new Error('DIRECT_COMMAND_RUNTIME_READ_ROOTS_EMPTY');
    this.#readRoots = options.runtimeReadRoots.map((root) => {
      const canonical = fs.realpathSync(root);
      if (!path.isAbsolute(canonical)) throw new Error('DIRECT_COMMAND_RUNTIME_READ_ROOT_INVALID');
      return canonical;
    });
    this.#limits = options;
    this.#runner = new CommandRunner({
      maxOutputBytes: options.maximumOutputBytes,
      maxExecutionMs: options.maximumExecutionMs,
      maximumProcesses: options.maximumProcesses,
      sandboxMemoryBytes: options.maximumMemoryBytes,
      sandboxCpuMillis: options.maximumCpuMillis,
      sandboxOpenFiles: 1024,
      terminationGraceMs: options.terminationGraceMs,
      ...(options.cgroupRoot ? { cgroupRoot: options.cgroupRoot } : {}),
      ...(options.allowSampledProcessLimit ? { allowSampledProcessLimit: true } : {}),
      sandboxExecutable: fileURLToPath(import.meta.resolve('@kubeclaw/plugin-foundation/isolation/plugin-sandbox')),
    });
  }

  invoke(capability: string, request: TestProviderCapabilityRequest, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    if (capability !== 'command.execute' || request.operation !== 'run'
      || request.resource.type !== 'command.executable') throw new Error('DIRECT_COMMAND_CAPABILITY_REQUEST_INVALID');
    const match = /^catalog:([A-Za-z0-9][A-Za-z0-9._-]{0,127})$/u.exec(request.resource.canonicalId);
    const executable = match ? this.#catalog.get(match[1]!) : undefined;
    if (!executable) throw new Error(`DIRECT_COMMAND_EXECUTABLE_DENIED:${request.resource.canonicalId}`);
    const rawLimits = request.payload.limits;
    if (!rawLimits || typeof rawLimits !== 'object' || Array.isArray(rawLimits)) throw new Error('DIRECT_COMMAND_LIMIT_INVALID');
    const limits = rawLimits as Record<string, unknown>;
    const writableRoot = containedDirectory(this.#root, request.payload.writableRoot);
    const workingDirectory = containedDirectory(writableRoot, request.payload.workingDirectory);
    const home = path.join(writableRoot, '.kubeclaw-home');
    const temporary = path.join(writableRoot, '.kubeclaw-tmp');
    fs.mkdirSync(home, { recursive: true, mode: 0o700 });
    fs.mkdirSync(temporary, { recursive: true, mode: 0o700 });
    return this.#runner.run({
      executable,
      args: commandArguments(request.payload.args),
      cwd: workingDirectory,
      writableRoot,
      readOnlyRoots: this.#readRoots,
      environment: { ...environment(request.payload.environment), PATH: this.#path, HOME: home, TMPDIR: temporary },
      limits: {
        maxOutputBytes: positiveLimit(limits.maxOutputBytes, this.#limits.maximumOutputBytes),
        maxExecutionMs: positiveLimit(limits.maxExecutionMs, this.#limits.maximumExecutionMs),
        maximumProcesses: positiveLimit(limits.maximumProcesses, this.#limits.maximumProcesses),
        memoryBytes: positiveLimit(limits.memoryBytes, this.#limits.maximumMemoryBytes),
        cpuMillis: positiveLimit(limits.cpuMillis, this.#limits.maximumCpuMillis),
        openFiles: positiveLimit(limits.openFiles, 1024),
      },
    }, signal).catch((error: unknown) => {
      if (error instanceof CommandRunError) return { ...error.output, errorCode: error.message };
      throw error;
    });
  }

  shutdown(): Promise<void> { return this.#runner.shutdown(); }
}

import { canonicalJson, sha256Text } from '@kubeclaw/plugin-sdk';

export const EXPOSURE_OWNER_ANNOTATION = 'kubeclaw.forgestack.ai/exposure-owner';
export const EXPOSURE_REQUEST_ANNOTATION = 'kubeclaw.forgestack.ai/exposure-request';
export const EXPOSURE_PREDECESSORS_ANNOTATION = 'kubeclaw.forgestack.ai/exposure-predecessors';
type JsonObject = Record<string, unknown>;

export function exposureIdentity(resource: string, payload: JsonObject): { owner: string; request: string } {
  const target = { resource, leaseName: payload.leaseName, namespace: payload.namespace };
  return { owner: sha256Text(canonicalJson(target)), request: sha256Text(canonicalJson({ ...target,
    serviceName: payload.serviceName, servicePort: payload.servicePort, expiresAt: payload.expiresAt,
    path: payload.path, hostname: payload.hostname ?? null,
    ...(payload.retentionMode === undefined ? {} : {retentionMode:payload.retentionMode}) })) };
}

export function generationObserved(lease: JsonObject, owner: string, phase: string): boolean {
  const metadata = lease.metadata as JsonObject; const status = lease.status as JsonObject;
  return Number.isSafeInteger(metadata.generation) && Number(metadata.generation) >= 1
    && status.exposureOwner === owner && status.exposureGeneration === metadata.generation && status.exposurePhase === phase;
}

/** Carry unfinished handoffs durably; a matching observed generation ends the old chain. */
export function exposurePredecessors(lease: JsonObject): string {
  const metadata = lease.metadata as JsonObject;
  const annotations = (metadata.annotations ?? {}) as JsonObject;
  const owner = annotations[EXPOSURE_OWNER_ANNOTATION] ?? '';
  const encoded = annotations[EXPOSURE_PREDECESSORS_ANNOTATION];
  const previous: unknown = encoded === undefined ? [] : JSON.parse(String(encoded));
  if (typeof owner !== 'string' || owner.length > 256 || !Array.isArray(previous) || previous.length > 64
    || previous.some(item => typeof item !== 'string' || item.length > 256 || item.includes('\0'))) {
    throw new Error('TAILSCALE_EXPOSURE_PREDECESSORS_INVALID');
  }
  const completed = generationObserved(lease, owner, 'Ready') || generationObserved(lease, owner, 'Off');
  const lineage = [...new Set([...(completed ? [] : previous as string[]), owner])];
  if (lineage.length > 64) throw new Error('TAILSCALE_EXPOSURE_PREDECESSORS_EXHAUSTED');
  return JSON.stringify(lineage);
}

export function assertExposureRequest(lease: JsonObject, identity: { owner: string; request: string }): void {
  const metadata = lease.metadata as JsonObject;
  const annotations = (metadata.annotations ?? {}) as JsonObject;
  if (annotations[EXPOSURE_OWNER_ANNOTATION] === identity.owner
    && annotations[EXPOSURE_REQUEST_ANNOTATION] !== identity.request) throw new Error('TAILSCALE_EXPOSURE_ATTEMPT_REQUEST_CHANGED');
}

export function assertRequestedExposure(lease: JsonObject, payload: JsonObject): void {
  const spec = lease.spec as JsonObject; const exposure = spec.exposure as JsonObject;
  if (!exposure || spec.purpose !== 'final-preview' || exposure.provider !== 'tailscale-ingress'
    || exposure.serviceName !== payload.serviceName || exposure.servicePort !== payload.servicePort
    || exposure.path !== payload.path || (exposure.hostname ?? null) !== (payload.hostname ?? null)) {
    throw new Error('TAILSCALE_EXPOSURE_SPEC_CHANGED');
  }
}

export function ownedReleaseAction(lease: string, namespace: string, owner: string): string {
  const patch = [
    { op: 'test', path: '/metadata/annotations/kubeclaw.forgestack.ai~1exposure-owner', value: owner },
    { op: 'add', path: '/spec/purpose', value: 'gate' },
    { op: 'add', path: '/spec/exposure', value: { provider: 'off' } },
  ];
  return `kubectl patch busternamespacelease ${lease} -n ${namespace} --type=json --patch '${JSON.stringify(patch)}'`;
}

import {canonicalJson,sha256Text} from '@kubeclaw/plugin-sdk';
import {EXPOSURE_OWNER_ANNOTATION,EXPOSURE_REQUEST_ANNOTATION,EXPOSURE_PREDECESSORS_ANNOTATION,exposurePredecessors} from './exposure-generation.ts';

export const READINESS_HANDOFF_ANNOTATION='kubeclaw.forgestack.ai/readiness-handoff';
type JsonObject=Record<string,unknown>;
export function assertHandoffSourceRequest(lease:JsonObject,identity:{owner:string;request:string}) {
 const annotations=((lease.metadata as JsonObject).annotations??{}) as JsonObject;
 if(annotations[READINESS_HANDOFF_ANNOTATION]===undefined)return;
 let recorded;try{recorded=JSON.parse(String(annotations[READINESS_HANDOFF_ANNOTATION]));}catch{throw new Error('EXPOSURE_HANDOFF_RECORD_INVALID');}
 if(!recorded||typeof recorded!=='object'||typeof recorded.owner!=='string'||typeof recorded.sourceOwner!=='string')throw new Error('EXPOSURE_HANDOFF_RECORD_INVALID');
 if(annotations[EXPOSURE_OWNER_ANNOTATION]===recorded.owner && recorded.sourceOwner===identity.owner && recorded.sourceRequest!==identity.request)throw new Error('EXPOSURE_HANDOFF_SOURCE_REQUEST_CHANGED');
}
export function pendingExposureHandoff(lease:JsonObject,identity:{owner:string;request:string}) {
 const metadata=lease.metadata as JsonObject,spec=lease.spec as JsonObject,status=lease.status as JsonObject;
 if(typeof metadata.uid!=='string'||!metadata.uid)throw new Error('EXPOSURE_HANDOFF_LEASE_UID_REQUIRED');
 if(spec.cleanupPolicy!=='retain')throw new Error('EXPOSURE_HANDOFF_NAMESPACE_RETENTION_REQUIRED');
 if(typeof spec.verifiedImage!=='string'||!/@sha256:[a-f0-9]{64}$/u.test(spec.verifiedImage)
  ||typeof spec.manifestDigest!=='string'||!/^sha256:[a-f0-9]{64}$/u.test(spec.manifestDigest))throw new Error('EXPOSURE_HANDOFF_DEPLOYMENT_BINDING_REQUIRED');
 const owner=sha256Text(canonicalJson({leaseUID:metadata.uid,sourceOwner:identity.owner,sourceRequest:identity.request,phase:'awaiting-readiness'}));
 return {schemaVersion:'demo-exposure-handoff.v1',phase:'awaiting-readiness',leaseUID:metadata.uid,
  sourceOwner:identity.owner,sourceRequest:identity.request,owner,expiresAt:status.expiresAt,
  immutableImage:spec.verifiedImage,manifestDigest:spec.manifestDigest};
}
export function existingExposureHandoff(lease:JsonObject,identity:{owner:string;request:string}) {
 const metadata=lease.metadata as JsonObject,annotations=(metadata.annotations??{}) as JsonObject;
 const expected=pendingExposureHandoff(lease,identity);
 if(annotations[EXPOSURE_OWNER_ANNOTATION]!==expected.owner)return undefined;
 let recorded;try{recorded=JSON.parse(String(annotations[READINESS_HANDOFF_ANNOTATION]));}catch{throw new Error('EXPOSURE_HANDOFF_RECORD_INVALID');}
 if(canonicalJson(recorded)!==canonicalJson(expected)||annotations[EXPOSURE_REQUEST_ANNOTATION]!==identity.request)throw new Error('EXPOSURE_HANDOFF_RECORD_CHANGED');
 return expected;
}
export function exposureHandoffPatch(lease:JsonObject,identity:{owner:string;request:string}) {
 const metadata=lease.metadata as JsonObject,annotations=(metadata.annotations??{}) as JsonObject;
 if(annotations[EXPOSURE_OWNER_ANNOTATION]!==identity.owner)throw new Error('EXPOSURE_HANDOFF_OWNER_CHANGED');
 const handoff=pendingExposureHandoff(lease,identity);
 return {handoff,patch:{metadata:{resourceVersion:metadata.resourceVersion,annotations:{
  [EXPOSURE_OWNER_ANNOTATION]:handoff.owner,[EXPOSURE_REQUEST_ANNOTATION]:identity.request,
  [EXPOSURE_PREDECESSORS_ANNOTATION]:exposurePredecessors(lease),[READINESS_HANDOFF_ANNOTATION]:JSON.stringify(handoff),
 }}}};
}

/** Bind the typed output to the controller observation after ownership transfer. */
export function observedExposureHandoff(lease:JsonObject,identity:{owner:string;request:string}) {
 const metadata=lease.metadata as JsonObject,status=lease.status as JsonObject;
 const handoff=existingExposureHandoff(lease,identity);
 if(!handoff||!Number.isSafeInteger(metadata.generation)||Number(metadata.generation)<1
  ||status.exposureGeneration!==metadata.generation||status.exposurePhase!=='Ready'||status.exposureOwner!==handoff.owner)throw new Error('EXPOSURE_HANDOFF_OBSERVED_GENERATION_REQUIRED');
 return {...handoff,exposureGeneration:metadata.generation};
}

import type { ResolvedInputV1 } from '@kubeclaw/pipeline-test-gate-contract';

const FIXTURES = new Map([
  ['kubeclaw.public-endpoint-fixture@1', 'public-endpoint-fixture.v1'],
  ['kubeclaw.kubernetes-deployment-fixture@1', 'kubernetes-deployment-fixture.v1'],
]);

function fixtures(inputs: readonly ResolvedInputV1[]): Record<string, unknown>[] {
  return inputs.filter(input => input.kind === 'value' && FIXTURES.has(input.schemaId)).map(input => {
    if (input.kind !== 'value' || !input.value || typeof input.value !== 'object' || Array.isArray(input.value)) throw new Error('FIXTURE_AUTHORITY_INVALID');
    const value = input.value as Record<string, unknown>;
    if (value.schemaVersion !== FIXTURES.get(input.schemaId) || typeof value.expiresAt !== 'string'
      || !Number.isFinite(Date.parse(value.expiresAt))) throw new Error('FIXTURE_AUTHORITY_INVALID');
    if (Date.parse(value.expiresAt) <= Date.now()) throw new Error('FIXTURE_AUTHORITY_EXPIRED');
    return value;
  });
}

/** Revalidate at each capability invocation; expiry also cancels in-flight use. */
export function fixtureAuthoritySignal(inputs: readonly ResolvedInputV1[], signal: AbortSignal): AbortSignal {
  if (signal.aborted) return signal;
  const values = fixtures(inputs);
  if (!values.length) return signal;
  const remaining = Math.min(...values.map(value => Date.parse(value.expiresAt as string))) - Date.now();
  if (remaining <= 0) throw new Error('FIXTURE_AUTHORITY_EXPIRED');
  return AbortSignal.any([signal, AbortSignal.timeout(Math.min(remaining, 2_147_483_647))]);
}

export function fixtureOrigins(inputs: readonly ResolvedInputV1[]): Set<string> {
  const origins = new Set<string>();
  for (const value of fixtures(inputs)) {
    const urls = value.schemaVersion === 'public-endpoint-fixture.v1' ? [value.url]
      : Array.isArray(value.endpoints) && value.endpoints.length > 0 && value.endpoints.length <= 64
        ? value.endpoints.map(endpoint => endpoint?.url) : [];
    if (!urls.length) throw new Error('FIXTURE_AUTHORITY_INVALID');
    for (const raw of urls) {
      if (typeof raw !== 'string') throw new Error('FIXTURE_AUTHORITY_INVALID');
      const url = new URL(raw);
      if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash || url.search) throw new Error('FIXTURE_AUTHORITY_INVALID');
      origins.add(url.origin);
    }
  }
  return origins;
}

import {canonicalJson, sha256Text} from '@kubeclaw/plugin-sdk';

type JsonObject = Record<string, unknown>;
function object(value: unknown): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('DEMO_CREDENTIAL_PROVENANCE_INVALID');
  return value as JsonObject;
}
function text(value: unknown): string {
  if (typeof value !== 'string' || !value || value.length > 2048 || /[\0\r\n]/u.test(value)) throw new Error('DEMO_CREDENTIAL_PROVENANCE_INVALID');
  return value;
}
function decoded(value: unknown): string {
  const encoded = text(value); const bytes = Buffer.from(encoded, 'base64');
  if (bytes.toString('base64') !== encoded) throw new Error('DEMO_CREDENTIAL_ENCODING_INVALID');
  return text(new TextDecoder('utf-8', {fatal:true}).decode(bytes));
}

function matches(actual:JsonObject,expected:JsonObject):void {
  if(Object.entries(expected).some(([key,value])=>actual[key]!==value))throw new Error('DEMO_CREDENTIAL_PROVENANCE_MISMATCH');
}

export function assertGeneratedCredentialLease(lease:JsonObject,expected:{leaseName:string;namespace:string;secretName:string;immutableImage:string;manifestDigest:string}):void {
  const metadata=object(lease.metadata),spec=object(lease.spec),status=object(lease.status),source=object(status.generatedCredentials);
  matches(metadata,{name:expected.leaseName});
  matches(status,{namespaceName:expected.namespace,credentialsAvailable:true});
  matches(spec,{verifiedImage:expected.immutableImage,manifestDigest:expected.manifestDigest});
  matches(object(spec.testCredentials),{mode:'generate',secretName:expected.secretName});
  matches(source,{schemaVersion:'generated-demo-credential-source.v1',leaseUID:text(metadata.uid),namespace:expected.namespace,secretName:expected.secretName});
  text(source.secretUID);text(source.secretResourceVersion);text(source.credentialDigest);
}

/** Consume fresh Kubernetes responses; a Secret name or user label is not provenance. */
export function generatedDemoCredentials(lease: JsonObject, secret: JsonObject, expected: {
  leaseName: string; namespace: string; secretName: string; immutableImage: string; manifestDigest: string;
}) {
  const metadata = object(lease.metadata), spec = object(lease.spec), status = object(lease.status);
  const source = object(status.generatedCredentials), requested = object(spec.testCredentials);
  const secretMeta = object(secret.metadata), annotations = object(secretMeta.annotations), labels = object(secretMeta.labels);
  const boundSource={schemaVersion:'generated-demo-credential-source.v1',leaseUID:text(metadata.uid),
    secretUID:text(secretMeta.uid),secretResourceVersion:text(secretMeta.resourceVersion),namespace:expected.namespace,
    secretName:expected.secretName,credentialDigest:text(source.credentialDigest)};
  matches(metadata,{name:expected.leaseName});
  matches(status,{namespaceName:expected.namespace,credentialsAvailable:true});
  matches(spec,{verifiedImage:expected.immutableImage,manifestDigest:expected.manifestDigest});
  matches(requested,{mode:'generate',secretName:expected.secretName});
  matches(source,boundSource);
  matches(secretMeta,{namespace:expected.namespace,name:expected.secretName});
  matches(secret,{immutable:true});
  matches(annotations,{'kubeclaw.forgestack.ai/generated-demo-credentials':'v1','kubeclaw.forgestack.ai/credential-lease-uid':metadata.uid});
  matches(labels,{'kubeclaw/buster-lease-uid':metadata.uid,'kubeclaw/managed-by':'buster-namespace-controller'});
  const data = object(secret.data);
  if (canonicalJson(Object.keys(data).sort()) !== canonicalJson(['password','username'])) throw new Error('DEMO_CREDENTIAL_KEYS_INVALID');
  const values = {username:decoded(data.username),password:decoded(data.password)};
  if (sha256Text(canonicalJson(values)) !== source.credentialDigest) throw new Error('DEMO_CREDENTIAL_DIGEST_MISMATCH');
  return {schemaVersion:'generated-demo-credentials.v1',...expected,source:boundSource,values};
}

