type Execute = (command: string, args: readonly string[], options: Readonly<Record<string, unknown>>)
  => Promise<{ stdout?: string; stderr?: string }>;
type JsonObject = Record<string, unknown>;

async function executeProcess(command: string, args: readonly string[], options: Readonly<Record<string, unknown>>): Promise<{ stdout: string; stderr: string }> {
  const result = await runProcessInput(command, args, {
    ...(options.env ? { env: options.env as NodeJS.ProcessEnv } : {}),
    ...(options.signal ? { signal: options.signal as AbortSignal } : {}),
    input: options.input as string | Buffer | null ?? null,
    timeoutMs: Number(options.timeout ?? 30_000), maximumOutputBytes: Number(options.maxBuffer ?? 1024 * 1024),
    prefix: 'KUBERNETES_FIXTURE_KUBECTL',
  });
  const stdout = result.stdout.toString('utf8'); const stderr = result.stderr.toString('utf8');
  if (result.code !== 0) throw Object.assign(new Error(`Command failed with code ${String(result.code)} and signal ${String(result.signal)}`), { stdout, stderr });
  return { stdout, stderr };
}

export interface KubernetesFixtureCapabilityInvokerOptions {
  readonly workspaceRoot: string;
  readonly kubectlExecutable: string;
  readonly controllerNamespace: string;
  readonly leaseApiGroup: string;
  readonly leaseApiVersion: string;
  readonly allowedNamespacePrefixes: readonly string[];
  readonly allowedRegistryPrefixes: readonly string[];
  readonly allowedSecretReferences: readonly string[];
  readonly allowedStorageClasses: readonly string[];
  readonly allowDefaultStorageClass: boolean;
  readonly runnerSubject?: string;
  readonly credentialReaderSubject?: string;
  readonly maximumManifestBytes: number;
  readonly maximumResources: number;
  readonly maximumPersistentVolumeClaimBytes: number;
  readonly maximumPersistentVolumeTotalBytes: number;
  readonly maximumRetentionSeconds: number;
  readonly maximumExecutionMs: number;
  readonly pollIntervalMs?: number;
  readonly execute?: Execute;
  readonly now?: () => Date;
}

function object(value: unknown, label: string): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`KUBERNETES_FIXTURE_REQUEST_INVALID:${label}`);
  }
  return value as JsonObject;
}

function text(value: unknown, label: string, maximum = 1024): string {
  if (typeof value !== 'string' || value.length < 1 || value.length > maximum || value.includes('\0')) {
    throw new Error(`KUBERNETES_FIXTURE_REQUEST_INVALID:${label}`);
  }
  return value;
}

function integer(value: unknown, label: string, minimum: number, maximum: number): number {
  if (!Number.isSafeInteger(value) || Number(value) < minimum || Number(value) > maximum) {
    throw new Error(`KUBERNETES_FIXTURE_REQUEST_INVALID:${label}`);
  }
  return Number(value);
}

function stringArray(value: unknown, label: string, maximum: number, pattern?: RegExp): string[] {
  if (!Array.isArray(value) || value.length > maximum
    || value.some((item) => typeof item !== 'string' || item.length < 1 || item.length > 253
      || item.includes('\0') || (pattern ? !pattern.test(item) : false))) {
    throw new Error(`KUBERNETES_FIXTURE_REQUEST_INVALID:${label}`);
  }
  return [...new Set(value as string[])];
}

function contained(root: string, value: unknown): string {
  const requested = text(value, 'manifestPath', 4096);
  if (!path.isAbsolute(requested)) throw new Error('KUBERNETES_FIXTURE_MANIFEST_PATH_INVALID');
  const canonical = fs.realpathSync(requested);
  if (canonical !== root && !canonical.startsWith(`${root}${path.sep}`)) {
    throw new Error('KUBERNETES_FIXTURE_MANIFEST_PATH_DENIED');
  }
  if (!fs.statSync(canonical).isFile()) throw new Error('KUBERNETES_FIXTURE_MANIFEST_NOT_FILE');
  return canonical;
}

function manifestBytes(file: string, expectedDigest: string, maximumBytes: number): Buffer {
  const handle = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  try {
    const before = fs.fstatSync(handle);
    if (before.size < 1 || before.size > maximumBytes) throw new Error('KUBERNETES_FIXTURE_MANIFEST_SIZE_INVALID');
    const bytes = Buffer.alloc(before.size);
    let offset = 0;
    while (offset < bytes.length) {
      const count = fs.readSync(handle, bytes, offset, bytes.length - offset, offset);
      if (count === 0) throw new Error('KUBERNETES_FIXTURE_MANIFEST_READ_INCOMPLETE');
      offset += count;
    }
    const after = fs.fstatSync(handle);
    if (after.size !== before.size || after.mtimeMs !== before.mtimeMs) {
      throw new Error('KUBERNETES_FIXTURE_MANIFEST_CHANGED');
    }
    const digest = `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`;
    if (digest !== expectedDigest) throw new Error('KUBERNETES_FIXTURE_MANIFEST_DIGEST_MISMATCH');
    return bytes;
  } finally {
    fs.closeSync(handle);
  }
}

function flattenDocuments(values: unknown[], maximumResources: number): JsonObject[] {
  const out: JsonObject[] = [];
  const pending = values.filter(value => value !== null && value !== undefined).reverse();
  let visits = 0;
  while (pending.length) {
    if (++visits > 100_000) throw new Error('KUBERNETES_FIXTURE_MANIFEST_COMPLEXITY_LIMIT');
    const document = object(pending.pop(), 'manifestDocument');
    if (document.kind === 'List') {
      if (!Array.isArray(document.items)) throw new Error('KUBERNETES_FIXTURE_MANIFEST_LIST_INVALID');
      if (pending.length + document.items.length > 100_000) throw new Error('KUBERNETES_FIXTURE_MANIFEST_COMPLEXITY_LIMIT');
      for (let index = document.items.length - 1; index >= 0; index -= 1) pending.push(document.items[index]);
    } else {
      if (out.length >= maximumResources) throw new Error('KUBERNETES_FIXTURE_RESOURCE_COUNT_INVALID');
      out.push(document);
    }
  }
  return out;
}

function podSpecs(document: JsonObject): JsonObject[] {
  const spec = document.spec;
  if (!spec || typeof spec !== 'object' || Array.isArray(spec)) return [];
  const typed = spec as JsonObject;
  if (document.kind === 'Pod') return [typed];
  const template = typed.template;
  if (template && typeof template === 'object' && !Array.isArray(template)) {
    const templateSpec = (template as JsonObject).spec;
    if (templateSpec && typeof templateSpec === 'object' && !Array.isArray(templateSpec)) return [templateSpec as JsonObject];
  }
  const jobTemplate = typed.jobTemplate;
  if (jobTemplate && typeof jobTemplate === 'object' && !Array.isArray(jobTemplate)) {
    const jobSpec = (jobTemplate as JsonObject).spec;
    const jobTemplateValue = jobSpec && typeof jobSpec === 'object' && !Array.isArray(jobSpec)
      ? (jobSpec as JsonObject).template : null;
    const jobPodSpec = jobTemplateValue && typeof jobTemplateValue === 'object' && !Array.isArray(jobTemplateValue)
      ? (jobTemplateValue as JsonObject).spec : null;
    if (jobPodSpec && typeof jobPodSpec === 'object' && !Array.isArray(jobPodSpec)) return [jobPodSpec as JsonObject];
  }
  return [];
}

function storageBytes(value: unknown): bigint {
  const quantity = text(value, 'persistentVolumeClaim.storage', 64);
  const parsed = STORAGE_QUANTITY.exec(quantity);
  if (!parsed) throw new Error(`KUBERNETES_FIXTURE_STORAGE_QUANTITY_INVALID:${quantity}`);
  const mantissa = parsed[1]!;
  const decimalPlaces = mantissa.includes('.') ? mantissa.length - mantissa.indexOf('.') - 1 : 0;
  let numerator = BigInt(mantissa.replace('.', ''));
  let denominator = 10n ** BigInt(decimalPlaces);
  const binaryPowers = new Map([['Ki', 10n], ['Mi', 20n], ['Gi', 30n], ['Ti', 40n], ['Pi', 50n], ['Ei', 60n]]);
  const decimalPowers = new Map([['n', -9], ['u', -6], ['m', -3], ['k', 3], ['K', 3],
    ['M', 6], ['G', 9], ['T', 12], ['P', 15], ['E', 18]]);
  if (parsed[2]) numerator *= 1n << binaryPowers.get(parsed[2])!;
  const exponent = parsed[3] ? decimalPowers.get(parsed[3])!
    : parsed[4] ? Number.parseInt(parsed[4].slice(1), 10) : 0;
  if (!Number.isSafeInteger(exponent) || Math.abs(exponent) > 63) {
    throw new Error(`KUBERNETES_FIXTURE_STORAGE_QUANTITY_INVALID:${quantity}`);
  }
  if (exponent >= 0) numerator *= 10n ** BigInt(exponent);
  else denominator *= 10n ** BigInt(-exponent);
  if (numerator < 1n || numerator % denominator !== 0n) {
    throw new Error(`KUBERNETES_FIXTURE_STORAGE_QUANTITY_INVALID:${quantity}`);
  }
  return numerator / denominator;
}

function persistentVolumeClaims(document: JsonObject): { name: string; spec: JsonObject; copies: bigint }[] {
  if (document.kind === 'PersistentVolumeClaim') {
    const metadata = object(document.metadata, 'persistentVolumeClaim.metadata');
    return [{ name: text(metadata.name, 'persistentVolumeClaim.metadata.name', 253),
      spec: object(document.spec, 'persistentVolumeClaim.spec'), copies: 1n }];
  }
  if (document.kind !== 'StatefulSet') return [];
  const spec = object(document.spec, 'statefulSet.spec');
  const replicas = spec.replicas ?? 1;
  if (!Number.isSafeInteger(replicas) || Number(replicas) < 0) {
    throw new Error('KUBERNETES_FIXTURE_STATEFULSET_REPLICAS_INVALID');
  }
  const templates = spec.volumeClaimTemplates ?? [];
  if (!Array.isArray(templates)) throw new Error('KUBERNETES_FIXTURE_PVC_TEMPLATES_INVALID');
  return templates.map((raw) => {
    const template = object(raw, 'statefulSet.volumeClaimTemplate');
    const metadata = object(template.metadata, 'statefulSet.volumeClaimTemplate.metadata');
    return { name: text(metadata.name, 'statefulSet.volumeClaimTemplate.metadata.name', 253),
      spec: object(template.spec, 'statefulSet.volumeClaimTemplate.spec'), copies: BigInt(Number(replicas)) };
  });
}

interface PersistentVolumePolicy {
  readonly allowedStorageClasses: ReadonlySet<string>;
  readonly allowDefaultStorageClass: boolean;
  readonly maximumClaimBytes: bigint;
  readonly maximumTotalBytes: bigint;
}

function validatePersistentVolumeClaim(name: string, spec: JsonObject, policy: PersistentVolumePolicy): bigint {
  if (spec.volumeName !== undefined || spec.selector !== undefined
    || spec.dataSource !== undefined || spec.dataSourceRef !== undefined) {
    throw new Error(`KUBERNETES_FIXTURE_PVC_SOURCE_DENIED:${name}`);
  }
  if (spec.volumeMode !== undefined && spec.volumeMode !== 'Filesystem') {
    throw new Error(`KUBERNETES_FIXTURE_PVC_VOLUME_MODE_DENIED:${name}`);
  }
  const storageClass = spec.storageClassName;
  if (storageClass === undefined) {
    if (!policy.allowDefaultStorageClass) throw new Error('KUBERNETES_FIXTURE_DEFAULT_STORAGE_CLASS_DENIED');
  } else {
    const selected = text(storageClass, 'persistentVolumeClaim.storageClassName', 253);
    if (!policy.allowedStorageClasses.has(selected)) {
      throw new Error(`KUBERNETES_FIXTURE_STORAGE_CLASS_DENIED:${selected}`);
    }
  }
  const resources = object(spec.resources, 'persistentVolumeClaim.resources');
  const requests = object(resources.requests, 'persistentVolumeClaim.resources.requests');
  const bytes = storageBytes(requests.storage);
  if (bytes > policy.maximumClaimBytes) throw new Error(`KUBERNETES_FIXTURE_PVC_SIZE_DENIED:${name}`);
  return bytes;
}

function validatePodSecurity(spec: JsonObject): void {
  if (spec.hostNetwork === true || spec.hostPID === true || spec.hostIPC === true) {
    throw new Error('KUBERNETES_FIXTURE_HOST_NAMESPACE_DENIED');
  }
  const podSecurity = object(spec.securityContext ?? {}, 'pod.securityContext');
  if (podSecurity.runAsNonRoot !== true) throw new Error('KUBERNETES_FIXTURE_RUN_AS_NON_ROOT_REQUIRED');
  const seccomp = object(podSecurity.seccompProfile ?? {}, 'pod.seccompProfile');
  if (seccomp.type !== 'RuntimeDefault' && seccomp.type !== 'Localhost') {
    throw new Error('KUBERNETES_FIXTURE_SECCOMP_REQUIRED');
  }
  const volumes = Array.isArray(spec.volumes) ? spec.volumes : [];
  if (volumes.some((volume) => object(volume, 'pod.volume').hostPath !== undefined)) {
    throw new Error('KUBERNETES_FIXTURE_HOST_PATH_DENIED');
  }
  if (volumes.some((volume) => object(volume, 'pod.volume').ephemeral !== undefined)) {
    throw new Error('KUBERNETES_FIXTURE_GENERIC_EPHEMERAL_VOLUME_DENIED');
  }
  for (const field of ['initContainers', 'containers']) {
    const containers = spec[field];
    if (containers === undefined) continue;
    if (!Array.isArray(containers) || (field === 'containers' && containers.length < 1)) {
      throw new Error('KUBERNETES_FIXTURE_CONTAINERS_INVALID');
    }
    for (const raw of containers) {
      const container = object(raw, 'container');
      const security = object(container.securityContext ?? {}, 'container.securityContext');
      if (security.privileged === true || security.allowPrivilegeEscalation !== false
        || (security.runAsNonRoot !== true && podSecurity.runAsNonRoot !== true)) {
        throw new Error('KUBERNETES_FIXTURE_CONTAINER_SECURITY_INVALID');
      }
      const capabilities = object(security.capabilities ?? {}, 'container.capabilities');
      if (!Array.isArray(capabilities.drop) || !capabilities.drop.includes('ALL')) {
        throw new Error('KUBERNETES_FIXTURE_CAPABILITY_DROP_REQUIRED');
      }
      const ports = Array.isArray(container.ports) ? container.ports : [];
      if (ports.some((port) => {
        const hostPort = object(port, 'container.port').hostPort;
        return hostPort !== undefined && hostPort !== 0;
      })) {
        throw new Error('KUBERNETES_FIXTURE_HOST_PORT_DENIED');
      }
    }
  }
}

function inspectManifest(bytes: Buffer, immutableImage: string, maximumResources: number,
  allowedRegistryPrefixes: readonly string[], serviceName: string, servicePort: number,
  expectedServiceTargetPort: number | null, persistentVolumePolicy: PersistentVolumePolicy):
  { resources: number; workloads: number; serviceTargetPort: number } {
  const loaded = boundedManifestDocuments(bytes);
  const documents = flattenDocuments(loaded, maximumResources);
  if (documents.length < 1 || documents.length > maximumResources) throw new Error('KUBERNETES_FIXTURE_RESOURCE_COUNT_INVALID');
  let workloads = 0;
  let matchedImage = false;
  let matchedService = false;
  let serviceTargetPortName: string | null = null;
  let resolvedServiceTargetPort: number | null = null;
  const namedContainerPorts = new Map<string, Set<number>>();
  let persistentVolumeTotalBytes = 0n;
  for (const document of documents) {
    const apiVersion = text(document.apiVersion, 'apiVersion', 128);
    const kind = text(document.kind, 'kind', 128);
    const metadata = object(document.metadata, 'metadata');
    text(metadata.name, 'metadata.name', 253);
    if (CLUSTER_SCOPED_KINDS.has(kind)) throw new Error(`KUBERNETES_FIXTURE_CLUSTER_SCOPE_DENIED:${kind}`);
    if (!ALLOWED_NAMESPACED_KINDS.has(kind)) throw new Error(`KUBERNETES_FIXTURE_RESOURCE_KIND_DENIED:${kind}`);
    if (metadata.namespace !== undefined) throw new Error(`KUBERNETES_FIXTURE_NAMESPACE_FIELD_DENIED:${kind}`);
    if (!apiVersion.includes('/') && apiVersion !== 'v1') throw new Error('KUBERNETES_FIXTURE_API_VERSION_INVALID');
    for (const claim of persistentVolumeClaims(document)) {
      persistentVolumeTotalBytes += validatePersistentVolumeClaim(claim.name, claim.spec, persistentVolumePolicy)
        * claim.copies;
      if (persistentVolumeTotalBytes > persistentVolumePolicy.maximumTotalBytes) {
        throw new Error('KUBERNETES_FIXTURE_PVC_TOTAL_SIZE_DENIED');
      }
    }
    if (kind === 'Service') {
      const spec = object(document.spec, 'service.spec');
      const type = spec.type ?? 'ClusterIP';
      const annotations = object(metadata.annotations ?? {}, 'service.metadata.annotations');
      const externalIPs = spec.externalIPs;
      const hasExternalIPs = externalIPs !== undefined && (!Array.isArray(externalIPs) || externalIPs.length > 0);
      const externalName = spec.externalName;
      const hasExternalName = externalName !== undefined
        && (typeof externalName !== 'string' || externalName.trim().length > 0);
      if (type !== 'ClusterIP' || hasExternalIPs || hasExternalName) {
        throw new Error('KUBERNETES_FIXTURE_EXTERNAL_SERVICE_DENIED');
      }
      if (annotations['tailscale.com/expose'] !== undefined) {
        throw new Error('KUBERNETES_FIXTURE_EXTERNAL_SERVICE_DENIED');
      }
      if (metadata.name === serviceName) {
        if (matchedService) throw new Error('KUBERNETES_FIXTURE_SERVICE_DUPLICATE');
        matchedService = true;
        const ports = Array.isArray(spec.ports) ? spec.ports.map((entry) => object(entry, 'service.port')) : [];
        const selected = ports.filter((entry) => entry.port === servicePort);
        if (selected.length !== 1) throw new Error('KUBERNETES_FIXTURE_SERVICE_PORT_MISMATCH');
        const target = selected[0]!.targetPort ?? servicePort;
        if (typeof target === 'number') resolvedServiceTargetPort = target;
        if (typeof target === 'string') serviceTargetPortName = target;
      }
    }
    for (const spec of podSpecs(document)) {
      workloads += 1;
      validatePodSecurity(spec);
      for (const field of ['initContainers', 'containers']) {
        const containers = spec[field];
        if (containers === undefined) continue;
        if (!Array.isArray(containers)) throw new Error('KUBERNETES_FIXTURE_CONTAINERS_INVALID');
        for (const container of containers) {
          const containerObject = object(container, 'container');
          const image = text(containerObject.image, 'container.image', 2048);
          const parsed = IMMUTABLE_IMAGE.exec(image);
          if (!parsed) throw new Error(`KUBERNETES_FIXTURE_MUTABLE_IMAGE_DENIED:${image}`);
          if (!allowedRegistryPrefixes.some((prefix) => parsed[1] === prefix || parsed[1]!.startsWith(`${prefix}/`))) {
            throw new Error(`KUBERNETES_FIXTURE_IMAGE_REGISTRY_DENIED:${image}`);
          }
          if (image === immutableImage) matchedImage = true;
          for (const rawPort of Array.isArray(containerObject.ports) ? containerObject.ports : []) {
            const port = object(rawPort, 'container.port');
            if (typeof port.name === 'string' && Number.isSafeInteger(port.containerPort)) {
              const values = namedContainerPorts.get(port.name) ?? new Set<number>();
              values.add(Number(port.containerPort));
              namedContainerPorts.set(port.name, values);
            }
          }
        }
      }
    }
  }
  if (workloads < 1) throw new Error('KUBERNETES_FIXTURE_WORKLOAD_REQUIRED');
  if (!matchedImage) throw new Error('KUBERNETES_FIXTURE_IMAGE_NOT_USED');
  if (!matchedService) throw new Error('KUBERNETES_FIXTURE_SERVICE_REQUIRED');
  if (serviceTargetPortName !== null) {
    const ports = namedContainerPorts.get(serviceTargetPortName);
    if (ports?.size !== 1) throw new Error('KUBERNETES_FIXTURE_SERVICE_TARGET_PORT_MISMATCH');
    resolvedServiceTargetPort = [...ports][0]!;
  }
  if (resolvedServiceTargetPort === null || resolvedServiceTargetPort < 1 || resolvedServiceTargetPort > 65_535
    || (expectedServiceTargetPort !== null && resolvedServiceTargetPort !== expectedServiceTargetPort)) {
    throw new Error('KUBERNETES_FIXTURE_SERVICE_TARGET_PORT_MISMATCH');
  }
  return { resources: documents.length, workloads, serviceTargetPort: resolvedServiceTargetPort };
}

function detail(error: unknown): string {
  if (error && typeof error === 'object') {
    const stderr = (error as Record<string, unknown>).stderr;
    if (typeof stderr === 'string' && stderr.trim()) return stderr.trim().slice(0, 4096);
  }
  return (error instanceof Error ? error.message : String(error)).slice(0, 4096);
}

function waitForPoll(milliseconds: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const finish = (): void => {
      signal.removeEventListener('abort', abort);
      resolve();
    };
    const timer = setTimeout(finish, milliseconds);
    const abort = (): void => {
      clearTimeout(timer);
      signal.removeEventListener('abort', abort);
      reject(new Error('KUBERNETES_FIXTURE_CANCELLED'));
    };
    if (signal.aborted) abort();
    else signal.addEventListener('abort', abort, { once: true });
  });
}

export class KubernetesFixtureCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #root: string;
  readonly #kubectl: string;
  readonly #controllerNamespace: string;
  readonly #apiGroup: string;
  readonly #apiVersion: string;
  readonly #namespacePrefixes: ReadonlySet<string>;
  readonly #registryPrefixes: readonly string[];
  readonly #secretReferences: ReadonlySet<string>;
  readonly #allowedStorageClasses: ReadonlySet<string>;
  readonly #allowDefaultStorageClass: boolean;
  readonly #runnerSubject: string;
  readonly #credentialReaderSubject: string;
  readonly #maximumManifestBytes: number;
  readonly #maximumResources: number;
  readonly #maximumPersistentVolumeClaimBytes: bigint;
  readonly #maximumPersistentVolumeTotalBytes: bigint;
  readonly #maximumRetentionSeconds: number;
  readonly #maximumExecutionMs: number;
  readonly #pollIntervalMs: number;
  readonly #execute: Execute;
  readonly #now: () => Date;

  constructor(options: KubernetesFixtureCapabilityInvokerOptions) {
    this.#root = fs.realpathSync(options.workspaceRoot);
    this.#kubectl = fs.realpathSync(options.kubectlExecutable);
    fs.accessSync(this.#kubectl, fs.constants.X_OK);
    if (!DNS_LABEL.test(options.controllerNamespace)) throw new Error('KUBERNETES_FIXTURE_CONTROLLER_NAMESPACE_INVALID');
    if (!/^[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?$/u.test(options.leaseApiGroup)) throw new Error('KUBERNETES_FIXTURE_API_GROUP_INVALID');
    if (!/^v[0-9]+(?:alpha|beta)?[0-9]*$/u.test(options.leaseApiVersion)) throw new Error('KUBERNETES_FIXTURE_API_VERSION_INVALID');
    if (options.allowedNamespacePrefixes.length < 1
      || options.allowedNamespacePrefixes.some((item) => item.length > MAX_NAMESPACE_PREFIX_LENGTH || !DNS_LABEL.test(item))) {
      throw new Error('KUBERNETES_FIXTURE_NAMESPACE_PREFIXES_INVALID');
    }
    if (options.allowedRegistryPrefixes.length < 1
      || options.allowedRegistryPrefixes.some((item) => !/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?\/[a-z0-9]+(?:[._/-][a-z0-9]+)*$/u.test(item))) {
      throw new Error('KUBERNETES_FIXTURE_REGISTRY_PREFIXES_INVALID');
    }
    if (options.allowedSecretReferences.some((item) => !SECRET_NAME.test(item))) {
      throw new Error('KUBERNETES_FIXTURE_SECRET_REFERENCES_INVALID');
    }
    if (options.allowedStorageClasses.some((item) => item.length > 253 || !STORAGE_CLASS_NAME.test(item))) {
      throw new Error('KUBERNETES_FIXTURE_STORAGE_CLASSES_INVALID');
    }
    if (typeof options.allowDefaultStorageClass !== 'boolean') {
      throw new Error('KUBERNETES_FIXTURE_DEFAULT_STORAGE_CLASS_POLICY_INVALID');
    }
    const runnerSubject = options.runnerSubject ?? `${options.controllerNamespace}/agent-buster`;
    const credentialReaderSubject = options.credentialReaderSubject ?? `${options.controllerNamespace}/agent-nova`;
    if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\/[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/u.test(runnerSubject)
      || !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\/[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/u.test(credentialReaderSubject)) {
      throw new Error('KUBERNETES_FIXTURE_SUBJECT_INVALID');
    }
    for (const [value, label] of [[options.maximumManifestBytes, 'MANIFEST_SIZE'], [options.maximumResources, 'RESOURCE_COUNT'],
      [options.maximumPersistentVolumeClaimBytes, 'PVC_SIZE'], [options.maximumPersistentVolumeTotalBytes, 'PVC_TOTAL_SIZE'],
      [options.maximumRetentionSeconds, 'RETENTION'], [options.maximumExecutionMs, 'EXECUTION']] as const) {
      if (!Number.isSafeInteger(value) || value < 1) throw new Error(`KUBERNETES_FIXTURE_${label}_LIMIT_INVALID`);
    }
    this.#controllerNamespace = options.controllerNamespace;
    this.#apiGroup = options.leaseApiGroup;
    this.#apiVersion = options.leaseApiVersion;
    this.#namespacePrefixes = new Set(options.allowedNamespacePrefixes);
    this.#registryPrefixes = [...options.allowedRegistryPrefixes];
    this.#secretReferences = new Set(options.allowedSecretReferences);
    this.#allowedStorageClasses = new Set(options.allowedStorageClasses);
    this.#allowDefaultStorageClass = options.allowDefaultStorageClass;
    this.#runnerSubject = runnerSubject;
    this.#credentialReaderSubject = credentialReaderSubject;
    this.#maximumManifestBytes = options.maximumManifestBytes;
    this.#maximumResources = options.maximumResources;
    this.#maximumPersistentVolumeClaimBytes = BigInt(options.maximumPersistentVolumeClaimBytes);
    this.#maximumPersistentVolumeTotalBytes = BigInt(options.maximumPersistentVolumeTotalBytes);
    if (this.#maximumPersistentVolumeTotalBytes < this.#maximumPersistentVolumeClaimBytes) {
      throw new Error('KUBERNETES_FIXTURE_PVC_TOTAL_SIZE_LIMIT_INVALID');
    }
    this.#maximumRetentionSeconds = options.maximumRetentionSeconds;
    this.#maximumExecutionMs = Math.min(options.maximumExecutionMs, MAX_TIMER_MS);
    this.#pollIntervalMs = options.pollIntervalMs ?? 1_000;
    if (!Number.isSafeInteger(this.#pollIntervalMs) || this.#pollIntervalMs < 50 || this.#pollIntervalMs > 10_000) {
      throw new Error('KUBERNETES_FIXTURE_POLL_INTERVAL_INVALID');
    }
    this.#execute = options.execute ?? executeProcess;
    this.#now = options.now ?? (() => new Date());
  }

  async #kubectlRun(args: readonly string[], input: Buffer | string | null, signal: AbortSignal, timeout = this.#maximumExecutionMs): Promise<string> {
    try {
      const result = await this.#execute(this.#kubectl, args, {
        encoding: 'utf8', maxBuffer: this.#maximumManifestBytes * 2, timeout: Math.min(timeout, this.#maximumExecutionMs),
        signal, ...(input === null ? {} : { input }),
        env: { PATH: path.dirname(this.#kubectl), HOME: process.env.HOME, KUBECONFIG: process.env.KUBECONFIG,
          KUBERNETES_SERVICE_HOST: process.env.KUBERNETES_SERVICE_HOST,
          KUBERNETES_SERVICE_PORT: process.env.KUBERNETES_SERVICE_PORT },
      });
      return result.stdout ?? '';
    } catch (error) {
      if (signal.aborted) throw new Error('KUBERNETES_FIXTURE_CANCELLED', { cause: error });
      throw new Error(`KUBERNETES_FIXTURE_KUBECTL_FAILED:${detail(error)}`, { cause: error });
    }
  }

  async #waitLease(leaseName: string, signal: AbortSignal, timeoutMs: number): Promise<JsonObject> {
    const deadline = Date.now() + timeoutMs;
    let last = 'Pending';
    while (Date.now() < deadline) {
      const requestTimeoutMs = Math.max(1, Math.min(15_000, deadline - Date.now()));
      const raw = await this.#kubectlRun(['get', 'busternamespacelease', leaseName, '-n', this.#controllerNamespace, '-o', 'json'], null, signal, requestTimeoutMs);
      const value = object(JSON.parse(raw), 'lease');
      const status = object(value.status ?? {}, 'lease.status');
      const phase = typeof status.phase === 'string' ? status.phase : 'Pending';
      last = typeof status.message === 'string' ? status.message : phase;
      if (phase === 'Ready') return status;
      if (phase === 'Rejected') throw new Error(`KUBERNETES_FIXTURE_LEASE_REJECTED:${last}`);
      if (phase === 'Failed') throw new Error(`KUBERNETES_FIXTURE_LEASE_FAILED:${last}`);
      const pollMs = Math.min(this.#pollIntervalMs, Math.max(0, deadline - Date.now()));
      if (pollMs > 0) await waitForPoll(pollMs, signal);
    }
    throw new Error(`KUBERNETES_FIXTURE_LEASE_TIMEOUT:${last}`);
  }

  async #waitPods(namespace: string, signal: AbortSignal, timeoutMs: number): Promise<number> {
    const deadline = Date.now() + timeoutMs;
    let last = 'No pods found.';
    while (Date.now() < deadline) {
      const requestTimeoutMs = Math.max(1, Math.min(15_000, deadline - Date.now()));
      const raw = await this.#kubectlRun(['get', 'pods', '-n', namespace, '-o', 'json'], null, signal, requestTimeoutMs);
      const value = object(JSON.parse(raw), 'pods');
      const items = Array.isArray(value.items) ? value.items : [];
      if (items.length > 0) {
        const pending: string[] = [];
        for (const rawPod of items) {
          const pod = object(rawPod, 'pod');
          const metadata = object(pod.metadata, 'pod.metadata');
          const status = object(pod.status ?? {}, 'pod.status');
          const conditions = Array.isArray(status.conditions) ? status.conditions : [];
          const ready = conditions.some((condition) => {
            const item = condition && typeof condition === 'object' && !Array.isArray(condition) ? condition as JsonObject : {};
            return item.type === 'Ready' && item.status === 'True';
          });
          if (!ready) pending.push(String(metadata.name ?? 'unknown'));
        }
        if (pending.length === 0) return items.length;
        last = `Pods not ready: ${pending.join(', ')}`;
      }
      const pollMs = Math.min(this.#pollIntervalMs, Math.max(0, deadline - Date.now()));
      if (pollMs > 0) await waitForPoll(pollMs, signal);
    }
    throw new Error(`KUBERNETES_FIXTURE_READINESS_TIMEOUT:${last}`);
  }

  async #waitService(namespace: string, serviceName: string, servicePort: number,
    signal: AbortSignal, timeoutMs: number): Promise<void> {
    const deadline = Date.now() + timeoutMs;
    let last = 'Service endpoints not ready.';
    while (Date.now() < deadline) {
      const serviceTimeoutMs = Math.max(1, Math.min(15_000, deadline - Date.now()));
      const serviceRaw = await this.#kubectlRun(['get', 'service', serviceName, '-n', namespace, '-o', 'json'], null, signal, serviceTimeoutMs);
      const service = object(JSON.parse(serviceRaw), 'service');
      const spec = object(service.spec, 'service.spec');
      const ports = Array.isArray(spec.ports) ? spec.ports : [];
      const servicePortEntry = ports.map((entry) => object(entry, 'service.port'))
        .find((entry) => entry.port === servicePort);
      if (!servicePortEntry) throw new Error('KUBERNETES_FIXTURE_SERVICE_PORT_MISMATCH');
      const servicePortName = typeof servicePortEntry.name === 'string' ? servicePortEntry.name : null;
      const targetPort = servicePortEntry.targetPort ?? servicePortEntry.port;
      if (Date.now() >= deadline) break;
      try {
        const endpointsTimeoutMs = Math.max(1, Math.min(15_000, deadline - Date.now()));
        const endpointsRaw = await this.#kubectlRun(['get', 'endpoints', serviceName, '-n', namespace, '-o', 'json'], null, signal, endpointsTimeoutMs);
        const endpoints = object(JSON.parse(endpointsRaw), 'endpoints');
        const subsets = Array.isArray(endpoints.subsets) ? endpoints.subsets : [];
        const ready = subsets.some((entry) => {
          const subset = object(entry, 'endpoints.subset');
          const endpointPorts = Array.isArray(subset.ports) ? subset.ports.map((port) => object(port, 'endpoints.port')) : [];
          const hasConfiguredPort = endpointPorts.some((port) => servicePortName
            ? port.name === servicePortName
            : (Number.isSafeInteger(targetPort) ? port.port === targetPort : ports.length === 1));
          return Array.isArray(subset.addresses) && subset.addresses.length > 0
            && hasConfiguredPort;
        });
        if (ready && Date.now() < deadline) return;
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        if (!/\bNotFound\b|\bnot found\b/iu.test(message)) throw error;
      }
      last = `Service ${serviceName} has no ready endpoints.`;
      const pollMs = Math.min(this.#pollIntervalMs, Math.max(0, deadline - Date.now()));
      if (pollMs > 0) await waitForPoll(pollMs, signal);
    }
    throw new Error(`KUBERNETES_FIXTURE_SERVICE_READINESS_TIMEOUT:${last}`);
  }

  async #releaseAfterPrepareFailure(leaseName: string): Promise<void> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.#maximumExecutionMs);
    try {
      await this.#release(leaseName, controller.signal);
    } finally {
      clearTimeout(timer);
    }
  }

  async #generatedCredentials(expected:Parameters<typeof generatedDemoCredentials>[2],signal:AbortSignal) {
    const resource=`busternamespaceleases.${this.#apiGroup}`;
    const freshLease=JSON.parse(await this.#kubectlRun(['get',resource,expected.leaseName,'-n',this.#controllerNamespace,'-o','json'],null,signal,15_000));
    assertGeneratedCredentialLease(freshLease,expected);
    let secret;
    // Until UID and bytes are verified, subprocess diagnostics must not expose Secret content.
    try { secret=JSON.parse(await this.#kubectlRun(['get','secret',expected.secretName,'-n',expected.namespace,'-o','json'],null,signal,15_000)); }
    catch { throw new Error('DEMO_CREDENTIAL_SECRET_READ_FAILED'); }
    return generatedDemoCredentials(freshLease,secret,expected);
  }

  async #prepare(request: TestProviderCapabilityRequest, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    const payload = object(request.payload, 'payload');
    const leaseName = text(payload.leaseName, 'leaseName', 63);
    if (!DNS_LABEL.test(leaseName)) throw new Error('KUBERNETES_FIXTURE_LEASE_NAME_INVALID');
    const namespacePrefix = text(payload.namespacePrefix, 'namespacePrefix', MAX_NAMESPACE_PREFIX_LENGTH);
    if (!this.#namespacePrefixes.has(namespacePrefix)) throw new Error('KUBERNETES_FIXTURE_NAMESPACE_PREFIX_DENIED');
    const namespaceName = text(payload.namespaceName, 'namespaceName', 63);
    if (!DNS_LABEL.test(namespaceName) || !namespaceName.startsWith(`${namespacePrefix}-`)) {
      throw new Error('KUBERNETES_FIXTURE_NAMESPACE_NAME_INVALID');
    }
    const immutableImage = text(payload.immutableImage, 'immutableImage', 2048);
    const image = IMMUTABLE_IMAGE.exec(immutableImage);
    if (!image || !this.#registryPrefixes.some((prefix) => image[1] === prefix || image[1]!.startsWith(`${prefix}/`))) {
      throw new Error('KUBERNETES_FIXTURE_IMAGE_DENIED');
    }
    if (payload.imageDigest !== image[2] || !DIGEST.test(String(payload.imageDigest))) {
      throw new Error('KUBERNETES_FIXTURE_IMAGE_DIGEST_INVALID');
    }
    const manifestDigest = text(payload.manifestDigest, 'manifestDigest', 71);
    if (!DIGEST.test(manifestDigest)) throw new Error('KUBERNETES_FIXTURE_MANIFEST_DIGEST_INVALID');
    const manifestPath = contained(this.#root, payload.manifestPath);
    const bytes = manifestBytes(manifestPath, manifestDigest, this.#maximumManifestBytes);
    const serviceName = text(payload.serviceName, 'serviceName', 63);
    if (!DNS_LABEL.test(serviceName)) throw new Error('KUBERNETES_FIXTURE_SERVICE_NAME_INVALID');
    const servicePort = integer(payload.servicePort, 'servicePort', 1, 65_535);
    const expectedServiceTargetPort = payload.serviceTargetPort === undefined
      ? null : integer(payload.serviceTargetPort, 'serviceTargetPort', 1, 65_535);
    const secretReferences = stringArray(payload.secretReferences ?? [], 'secretReferences', 32, SECRET_NAME);
    if (secretReferences.some((name) => !this.#secretReferences.has(name))) {
      throw new Error('KUBERNETES_FIXTURE_SECRET_REFERENCE_DENIED');
    }
    const facts = inspectManifest(bytes, immutableImage, this.#maximumResources, this.#registryPrefixes,
      serviceName, servicePort, expectedServiceTargetPort, {
        allowedStorageClasses: this.#allowedStorageClasses,
        allowDefaultStorageClass: this.#allowDefaultStorageClass,
        maximumClaimBytes: this.#maximumPersistentVolumeClaimBytes,
        maximumTotalBytes: this.#maximumPersistentVolumeTotalBytes,
      });
    const retentionSeconds = integer(payload.retentionSeconds, 'retentionSeconds', 60, this.#maximumRetentionSeconds);
    const retentionMode = text(payload.retentionMode, 'retentionMode', 6);
    if (retentionMode !== 'delete' && retentionMode !== 'retain') {
      throw new Error('KUBERNETES_FIXTURE_RETENTION_MODE_INVALID');
    }
    const readinessTimeoutMs = integer(payload.readinessTimeoutMs, 'readinessTimeoutMs', 1_000, this.#maximumExecutionMs);
    const credentialsValue = payload.testCredentials === undefined ? null : object(payload.testCredentials, 'testCredentials');
    let testCredentials: JsonObject | null = null;
    if (credentialsValue) {
      const mode = text(credentialsValue.mode, 'testCredentials.mode', 16);
      const secretName = text(credentialsValue.secretName, 'testCredentials.secretName', 253);
      if (mode !== 'generate' || !SECRET_NAME.test(secretName)) {
        throw new Error('KUBERNETES_FIXTURE_TEST_CREDENTIALS_INVALID');
      }
      testCredentials = { mode, secretName, keys: ['username', 'password'],
        readers: [...new Set([this.#credentialReaderSubject, this.#runnerSubject])] };
    }
    const lease = {
      apiVersion: `${this.#apiGroup}/${this.#apiVersion}`, kind: 'BusterNamespaceLease',
      metadata: { name: leaseName, namespace: this.#controllerNamespace,
        labels: { 'openclaw.io/buster-scope': request.resource.canonicalId.replace(/[^A-Za-z0-9._-]/gu, '-').slice(0, 63) } },
      spec: { namespaceName, namespacePrefix, runId: leaseName, project: text(payload.project, 'project', 253),
        purpose: 'gate', serviceName, servicePort, serviceTargetPort: facts.serviceTargetPort, cleanupPolicy: retentionMode,
        verifiedImage: immutableImage, manifestDigest,
        ttlSeconds: retentionSeconds, access: [{ subject: this.#runnerSubject, mode: 'deployer' }],
        secretsToCopy: secretReferences, ...(testCredentials ? { testCredentials } : {}), exposure: { provider: 'off' } },
    };
    const leaseBytes = `${JSON.stringify(lease)}\n`;
    const resource = `busternamespaceleases.${this.#apiGroup}`;
    for (const verb of ['create', 'get', 'delete']) {
      const allowed = (await this.#kubectlRun(['auth', 'can-i', verb, resource, '-n', this.#controllerNamespace], null, signal, 15_000)).trim();
      if (allowed !== 'yes') throw new Error(`KUBERNETES_FIXTURE_RBAC_DENIED:${verb}`);
    }
    await this.#kubectlRun(['apply', '--dry-run=server', '-f', '-'], leaseBytes, signal, 15_000);
    await this.#kubectlRun(['apply', '-f', '-'], leaseBytes, signal, 15_000);
    let status: JsonObject;
    try {
      status = await this.#waitLease(leaseName, signal, readinessTimeoutMs);
      const actualNamespace = text(status.namespaceName, 'status.namespaceName', 63);
      if (actualNamespace !== namespaceName) throw new Error('KUBERNETES_FIXTURE_NAMESPACE_MISMATCH');
      await this.#kubectlRun(['apply', '--namespace', namespaceName, '-f', '-'], bytes, signal, readinessTimeoutMs);
      const readinessDeadline = Date.now() + readinessTimeoutMs;
      const podCount = await this.#waitPods(namespaceName, signal, readinessTimeoutMs);
      const serviceReadinessMs = readinessDeadline - Date.now();
      if (serviceReadinessMs <= 0) throw new Error('KUBERNETES_FIXTURE_SERVICE_READINESS_TIMEOUT:Readiness deadline expired.');
      await this.#waitService(namespaceName, serviceName, servicePort, signal, serviceReadinessMs);
      const createdAt = text(status.createdAt, 'status.createdAt', 64);
      if (!Number.isFinite(Date.parse(createdAt))) throw new Error('KUBERNETES_FIXTURE_CREATED_AT_INVALID');
      const expiresAt = typeof status.expiresAt === 'string' ? status.expiresAt : new Date(Date.parse(createdAt) + retentionSeconds * 1_000).toISOString();
      const generatedCredentials = testCredentials ? await this.#generatedCredentials({leaseName, namespace:namespaceName,
        secretName:String(testCredentials.secretName), immutableImage, manifestDigest},signal) : undefined;
      return Object.freeze({ ok: true, leaseName, namespace: namespaceName, createdAt, expiresAt,
        endpoint: `http://${serviceName}.${namespaceName}.svc.cluster.local:${servicePort}`,
        releaseAction: `kubectl delete busternamespacelease ${leaseName} -n ${this.#controllerNamespace}`,
        manifestDigest, immutableImage, secretReferences,
        ...(testCredentials ? { credentialsRef: testCredentials.secretName } : {}),
        ...(generatedCredentials ? { generatedCredentials } : {}),
        resourceCount: facts.resources, workloadCount: facts.workloads, podCount });
    } catch (error) {
      await this.#releaseAfterPrepareFailure(leaseName).catch(() => undefined);
      throw error;
    }
  }

  async #release(leaseName: string, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    if (!DNS_LABEL.test(leaseName)) throw new Error('KUBERNETES_FIXTURE_LEASE_NAME_INVALID');
    await this.#kubectlRun(['delete', 'busternamespacelease', leaseName, '-n', this.#controllerNamespace,
      '--ignore-not-found=true', '--wait=true', `--timeout=${Math.ceil(this.#maximumExecutionMs / 1_000)}s`], null, signal);
    return Object.freeze({ ok: true, leaseName, released: true });
  }

  async invoke(capability: string, request: TestProviderCapabilityRequest, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    if (capability !== 'kubernetes.fixture' || request.resource.type !== 'kubernetes.fixture'
      || !/^kubernetes-fixture:attempt:[A-Za-z0-9._:-]+$/u.test(request.resource.canonicalId)) {
      throw new Error('KUBERNETES_FIXTURE_CAPABILITY_REQUEST_INVALID');
    }
    if (request.operation === 'prepare') return this.#prepare(request, signal);
    if (request.operation === 'release') {
      const payload = object(request.payload, 'payload');
      return this.#release(text(payload.leaseName, 'leaseName', 63), signal);
    }
    throw new Error('KUBERNETES_FIXTURE_OPERATION_INVALID');
  }
}

import { loadAll } from 'js-yaml';

const MAX_NODES = 100_000;
const MAX_DEPTH = 64;
const MAX_ALIASES = 1_000;

/** Bound parser recursion and expanded alias work before inspecting any manifest. */
export function boundedManifestDocuments(bytes: Buffer): unknown[] {
  const values: unknown[] = [];
  let depth = 0; let nodes = 0;
  try {
    loadAll(bytes.toString('utf8'), value => { values.push(value); }, {
      listener(event) {
        if (event === 'open') {
          if (++depth > MAX_DEPTH || ++nodes > MAX_NODES) throw new Error('KUBERNETES_FIXTURE_MANIFEST_COMPLEXITY_LIMIT');
        } else depth -= 1;
      },
    });
  } catch (error) {
    throw new Error(`KUBERNETES_FIXTURE_MANIFEST_PARSE_FAILED: ${error instanceof Error ? error.message : String(error)}`, { cause: error });
  }
  validateAliasGraph(values);
  return values;
}

function validateAliasGraph(values: unknown[]): void {
  const active = new WeakSet<object>(); const seen = new WeakSet<object>();
  const pending: { value: unknown; depth: number; leave?: boolean }[] = values.map(value => ({ value, depth: 0 }));
  let nodes = 0; let aliases = 0;
  while (pending.length) {
    const frame = pending.pop()!;
    if (!frame.value || typeof frame.value !== 'object') continue;
    if (frame.leave) { active.delete(frame.value); continue; }
    if (++nodes > MAX_NODES || frame.depth > MAX_DEPTH) throw new Error('KUBERNETES_FIXTURE_MANIFEST_COMPLEXITY_LIMIT');
    if (active.has(frame.value)) throw new Error('KUBERNETES_FIXTURE_MANIFEST_ALIAS_CYCLE');
    if (seen.has(frame.value) && ++aliases > MAX_ALIASES) throw new Error('KUBERNETES_FIXTURE_MANIFEST_ALIAS_LIMIT');
    seen.add(frame.value); active.add(frame.value);
    const children = Object.values(frame.value);
    if (pending.length + children.length > MAX_NODES) throw new Error('KUBERNETES_FIXTURE_MANIFEST_COMPLEXITY_LIMIT');
    pending.push({ ...frame, leave: true });
    for (const value of children) pending.push({ value, depth: frame.depth + 1 });
  }
}

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import type { TestProviderCapabilityInvoker } from './runner.ts';

type JsonObject = Record<string, unknown>;

export interface KubernetesRuntimeSecurityCapabilityInvokerOptions {
  readonly workspaceRoot: string;
  readonly kubectlExecutable: string;
  readonly controllerNamespace: string;
  readonly leaseApiGroup: string;
  readonly allowedNamespacePrefixes: readonly string[];
  readonly maximumExecutionMs: number;
  readonly maximumOutputBytes: number;
  readonly pollIntervalMs?: number;
  readonly maximumObservationAgeMs: number;
}

function object(value: unknown, code = 'KUBERNETES_RUNTIME_SECURITY_RESPONSE_INVALID'): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(code);
  return value as JsonObject;
}

function text(value: unknown, label: string, maximum = 2048): string {
  if (typeof value !== 'string' || value.length < 1 || value.length > maximum) {
    throw new Error(`KUBERNETES_RUNTIME_SECURITY_REQUEST_INVALID:${label}`);
  }
  return value;
}

function canonicalJson(value: unknown): string {
  const normalized = (entry: unknown): unknown => {
    if (Array.isArray(entry)) return entry.map(normalized);
    if (entry && typeof entry === 'object') return Object.fromEntries(Object.entries(entry as JsonObject)
      .sort(([left], [right]) => left.localeCompare(right)).map(([key, item]) => [key, normalized(item)]));
    return entry;
  };
  return JSON.stringify(normalized(value));
}

export function runtimeSecurityResultDigest(snapshot: JsonObject): string {
  const payload = { findings: snapshot.findings, omittedFindingCount: snapshot.omittedFindingCount,
    podCount: snapshot.podCount, serviceCount: snapshot.serviceCount,
    totalFindingCount: snapshot.totalFindingCount };
  return `sha256:${crypto.createHash('sha256').update(canonicalJson(payload)).digest('hex')}`;
}

export function runtimeSecurityObservationHasValidAccounting(snapshot: JsonObject): boolean {
  if (!Array.isArray(snapshot.findings) || !Number.isSafeInteger(snapshot.totalFindingCount)
    || Number(snapshot.totalFindingCount) < 0 || !Number.isSafeInteger(snapshot.omittedFindingCount)
    || Number(snapshot.omittedFindingCount) < 0) return false;
  const total = Number(snapshot.totalFindingCount); const omitted = Number(snapshot.omittedFindingCount);
  if (omitted === 0) return total === snapshot.findings.length;
  const overflow = snapshot.findings.at(-1);
  return snapshot.findings.length > 0 && total - omitted === snapshot.findings.length - 1
    && Boolean(overflow && typeof overflow === 'object' && !Array.isArray(overflow)
      && (overflow as JsonObject).id === 'runtime:findings:overflow'
      && (overflow as JsonObject).severity === 'critical');
}

export function containedRuntimeSecurityManifest(root: string, value: unknown): string {
  const requested = text(value, 'manifestPath', 4096);
  const resolved = fs.realpathSync(path.isAbsolute(requested) ? requested : path.resolve(root, requested));
  if (!fs.statSync(resolved).isFile() || (resolved !== root && !resolved.startsWith(`${root}${path.sep}`))) {
    throw new Error('KUBERNETES_RUNTIME_SECURITY_PATH_DENIED');
  }
  return resolved;
}

async function kubectl(executable: string, args: readonly string[], timeoutMs: number, maximumBytes: number,
  signal: AbortSignal): Promise<Buffer> {
  return await new Promise<Buffer>((resolve, reject) => {
    const controller = new AbortController();
    const combined = AbortSignal.any([signal, controller.signal]);
    const child = spawn(executable, [...args], { signal: combined, stdio: ['ignore', 'pipe', 'pipe'],
      env: { PATH: '/usr/local/bin:/usr/bin:/bin', HOME: process.env.HOME, KUBECONFIG: process.env.KUBECONFIG,
        KUBERNETES_SERVICE_HOST: process.env.KUBERNETES_SERVICE_HOST,
        KUBERNETES_SERVICE_PORT: process.env.KUBERNETES_SERVICE_PORT, LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' } });
    const stdout: Buffer[] = []; const stderr: Buffer[] = []; let bytes = 0; let settled = false;
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const finish = (error?: Error, output?: Buffer): void => {
      if (settled) return; settled = true; clearTimeout(timer); error ? reject(error) : resolve(output!);
    };
    const collect = (target: Buffer[]) => (chunk: Buffer): void => {
      bytes += chunk.byteLength;
      if (bytes > maximumBytes) { controller.abort(); finish(new Error('KUBERNETES_RUNTIME_SECURITY_OUTPUT_LIMIT_EXCEEDED')); }
      else target.push(Buffer.from(chunk));
    };
    child.stdout.on('data', collect(stdout)); child.stderr.on('data', collect(stderr));
    child.on('error', (error) => finish(signal.aborted ? new Error('KUBERNETES_RUNTIME_SECURITY_CANCELLED')
      : controller.signal.aborted ? new Error('KUBERNETES_RUNTIME_SECURITY_TIMEOUT')
        : new Error('KUBERNETES_RUNTIME_SECURITY_EXECUTION_FAILED', { cause: error })));
    child.on('close', (code, childSignal) => {
      if (settled) return;
      if (signal.aborted) return finish(new Error('KUBERNETES_RUNTIME_SECURITY_CANCELLED'));
      if (controller.signal.aborted) return finish(new Error('KUBERNETES_RUNTIME_SECURITY_TIMEOUT'));
      if (code !== 0 || childSignal) return finish(new Error(`KUBERNETES_RUNTIME_SECURITY_EXECUTION_FAILED:${Buffer.concat(stderr).toString('utf8').slice(0, 1024)}`));
      finish(undefined, Buffer.concat(stdout));
    });
  });
}

export class KubernetesRuntimeSecurityCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #root: string; readonly #kubectl: string; readonly #controllerNamespace: string;
  readonly #leaseApiGroup: string; readonly #prefixes: readonly string[]; readonly #maximumExecutionMs: number;
  readonly #maximumOutputBytes: number;
  readonly #pollIntervalMs: number;
  readonly #maximumObservationAgeMs: number;

  constructor(options: KubernetesRuntimeSecurityCapabilityInvokerOptions) {
    this.#root = fs.realpathSync(options.workspaceRoot); this.#kubectl = fs.realpathSync(options.kubectlExecutable);
    fs.accessSync(this.#kubectl, fs.constants.X_OK); this.#controllerNamespace = options.controllerNamespace;
    this.#leaseApiGroup = options.leaseApiGroup; this.#prefixes = [...options.allowedNamespacePrefixes];
    this.#maximumExecutionMs = options.maximumExecutionMs; this.#maximumOutputBytes = options.maximumOutputBytes;
    this.#pollIntervalMs = options.pollIntervalMs ?? 1_000;
    this.#maximumObservationAgeMs = options.maximumObservationAgeMs;
    if (this.#prefixes.length < 1 || !Number.isSafeInteger(this.#maximumExecutionMs) || this.#maximumExecutionMs < 1
      || !Number.isSafeInteger(this.#maximumOutputBytes) || this.#maximumOutputBytes < 1024
      || !Number.isSafeInteger(this.#pollIntervalMs) || this.#pollIntervalMs < 10 || this.#pollIntervalMs > 10_000
      || !Number.isSafeInteger(this.#maximumObservationAgeMs) || this.#maximumObservationAgeMs < this.#pollIntervalMs
      || this.#maximumObservationAgeMs > 60_000) {
      throw new Error('KUBERNETES_RUNTIME_SECURITY_CONFIG_INVALID');
    }
  }

  async invoke(capability: string, request: unknown, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    if (capability !== 'kubernetes.runtime-security') throw new Error('KUBERNETES_RUNTIME_SECURITY_CAPABILITY_DENIED');
    const value = object(request, 'KUBERNETES_RUNTIME_SECURITY_REQUEST_INVALID');
    if (value.operation !== 'inspect') throw new Error('KUBERNETES_RUNTIME_SECURITY_OPERATION_DENIED');
    const payload = object(value.payload, 'KUBERNETES_RUNTIME_SECURITY_REQUEST_INVALID');
    const leaseName = text(payload.leaseName, 'leaseName', 253); const namespace = text(payload.namespace, 'namespace', 63);
    if (!this.#prefixes.some((prefix) => namespace.startsWith(`${prefix}-`))) throw new Error('KUBERNETES_RUNTIME_SECURITY_NAMESPACE_DENIED');
    const immutableImage = text(payload.immutableImage, 'immutableImage');
    const manifestPath = containedRuntimeSecurityManifest(this.#root, payload.manifestPath);
    const digest = text(payload.manifestDigest, 'manifestDigest', 71);
    const actualDigest = `sha256:${crypto.createHash('sha256').update(fs.readFileSync(manifestPath)).digest('hex')}`;
    if (actualDigest !== digest) throw new Error('KUBERNETES_RUNTIME_SECURITY_MANIFEST_DIGEST_MISMATCH');
    const timeoutMs = Math.min(this.#maximumExecutionMs,
      Number.isSafeInteger(payload.timeoutMs) ? Number(payload.timeoutMs) : this.#maximumExecutionMs);
    const leaseResource = `busternamespaceleases.${this.#leaseApiGroup}`;
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      const lease = object(JSON.parse((await kubectl(this.#kubectl,
        ['get', leaseResource, leaseName, '-n', this.#controllerNamespace, '-o', 'json'],
        Math.max(1, deadline - Date.now()), this.#maximumOutputBytes, signal)).toString('utf8')));
      const status = object(lease.status);
      if (status.namespaceName !== namespace || object(lease.spec).namespaceName !== namespace) {
        throw new Error('KUBERNETES_RUNTIME_SECURITY_LEASE_MISMATCH');
      }
      const snapshot = status.runtimeSecurity && typeof status.runtimeSecurity === 'object'
        && !Array.isArray(status.runtimeSecurity) ? object(status.runtimeSecurity) : null;
      if (snapshot?.phase === 'Observed' && snapshot.manifestDigest === digest
        && snapshot.immutableImage === immutableImage && Array.isArray(snapshot.findings)
        && Number.isSafeInteger(snapshot.podCount) && Number(snapshot.podCount) > 0
        && Number.isSafeInteger(snapshot.serviceCount) && Number(snapshot.serviceCount) > 0
        && runtimeSecurityObservationHasValidAccounting(snapshot)
        && runtimeSecurityObservationIsFresh(snapshot.observedAt, Date.now(), this.#maximumObservationAgeMs)
        && typeof snapshot.resultDigest === 'string' && /^sha256:[a-f0-9]{64}$/u.test(snapshot.resultDigest)) {
        if (runtimeSecurityResultDigest(snapshot) !== snapshot.resultDigest) {
          throw new Error('KUBERNETES_RUNTIME_SECURITY_RESULT_DIGEST_MISMATCH');
        }
        return Object.freeze({ scanner: 'kubernetes-runtime-security', leaseName, namespace, manifestDigest: digest,
          observedAt: snapshot.observedAt, podCount: snapshot.podCount, serviceCount: snapshot.serviceCount,
          totalFindingCount: snapshot.totalFindingCount, omittedFindingCount: snapshot.omittedFindingCount,
          findings: snapshot.findings, resultDigest: snapshot.resultDigest });
      }
      await new Promise<void>((resolve, reject) => {
        const onAbort = () => { clearTimeout(timer); reject(new Error('KUBERNETES_RUNTIME_SECURITY_CANCELLED')); };
        const timer = setTimeout(() => { signal.removeEventListener('abort', onAbort); resolve(); },
          Math.min(this.#pollIntervalMs, Math.max(1, deadline - Date.now())));
        signal.addEventListener('abort', onAbort, { once: true });
      });
    }
    throw new Error('KUBERNETES_RUNTIME_SECURITY_TIMEOUT');
  }
}

export function runtimeSecurityObservationIsFresh(value: unknown, nowMs: number, maximumAgeMs: number): boolean {
  if (typeof value !== 'string') return false;
  const observedMs = Date.parse(value);
  if (!Number.isFinite(observedMs)) return false;
  return observedMs <= nowMs + 5_000 && nowMs - observedMs <= maximumAgeMs;
}

import { RegistryHealthAccess, type RegistryHealthOptions } from './registry-health-access.ts';
import { fixtureOrigins, fixtureAuthoritySignal } from './fixture-authority.ts';
import crypto from 'node:crypto';
import WebSocket from 'ws';
import type { ResolvedInputV1 } from '@kubeclaw/pipeline-test-gate-contract';
import type { TestProviderCapabilityInvoker } from './runner.ts';

const MAX_TIMER_MS = 2_147_483_647;
const METHODS = new Set(['DELETE', 'GET', 'HEAD', 'OPTIONS', 'PATCH', 'POST', 'PUT']);
const DENIED_HEADERS = new Set(['connection', 'content-length', 'host', 'proxy-authorization', 'transfer-encoding', 'upgrade']);

export interface NetworkHttpCapabilityInvokerOptions {
  readonly allowedOrigins: readonly string[];
  readonly allowedHostSuffixes: readonly string[];
  readonly allowedPorts: readonly number[];
  readonly maximumResponseBytes: number;
  readonly maximumRequestBytes?: number;
  readonly maximumExecutionMs: number;
  readonly allowedMethods?: readonly string[];
  readonly allowedRequestHeaders?: readonly string[];
  readonly allowWebSocket?: boolean;
  readonly registryHealth?: RegistryHealthOptions;
}

function positiveInteger(value: unknown, code: string, maximum = Number.MAX_SAFE_INTEGER): number {
  if (!Number.isSafeInteger(value) || Number(value) < 1 || Number(value) > maximum) throw new Error(code);
  return Number(value);
}

function canonicalOrigin(value: string): string {
  const url = new URL(value);
  if (!['http:', 'https:'].includes(url.protocol) || url.origin !== value || url.username || url.password) {
    throw new Error('HTTP_RUNTIME_ORIGIN_INVALID');
  }
  return url.origin;
}

function canonicalSuffix(value: string): string {
  const normalized = value.toLowerCase();
  if (!/^\.[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?$/u.test(normalized) || normalized.includes('..')) {
    throw new Error('HTTP_RUNTIME_HOST_SUFFIX_INVALID');
  }
  return normalized;
}


function requestHeaders(value: unknown, allowed: ReadonlySet<string>, closeConnection = true): Record<string, string> {
  if (value === undefined) return {
    ...(allowed.has('accept') ? { accept: '*/*' } : {}),
    ...(closeConnection ? { connection: 'close' } : {}),
  };
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('HTTP_REQUEST_HEADERS_INVALID');
  const entries = Object.entries(value as Record<string, unknown>);
  if (entries.length > 32 || entries.some(([name, content]) => !/^[a-z0-9!#$%&'*+.^_`|~-]+$/iu.test(name)
    || DENIED_HEADERS.has(name.toLowerCase()) || !allowed.has(name.toLowerCase()) || typeof content !== 'string'
    || content.length < 1 || content.length > 4096 || /[\r\n]/u.test(content))) {
    throw new Error('HTTP_REQUEST_HEADER_DENIED');
  }
  return { ...Object.fromEntries(entries.map(([name, content]) => [name.toLowerCase(), String(content)])),
    ...(closeConnection ? { connection: 'close' } : {}) };
}

function responseHeaderNames(value: unknown): readonly string[] {
  if (value === undefined) return Object.freeze(['content-type']);
  if (!Array.isArray(value) || value.length > 32 || value.some((name) => typeof name !== 'string'
    || !/^[a-z0-9!#$%&'*+.^_`|~-]+$/iu.test(name)
    || (DENIED_HEADERS.has(name.toLowerCase()) && name.toLowerCase() !== 'content-length'))) {
    throw new Error('HTTP_RESPONSE_HEADERS_INVALID');
  }
  return Object.freeze([...new Set(['content-type', ...value.map((name) => name.toLowerCase())])]);
}

function exactPayload(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('HTTP_REQUEST_PAYLOAD_INVALID');
  const payload = value as Record<string, unknown>;
  const allowed = new Set(['method', 'headers', 'body', 'messages', 'minimumMessages', 'timeoutMs', 'maximumResponseBytes', 'responseHeaders']);
  if (Object.keys(payload).some((key) => !allowed.has(key))) throw new Error('HTTP_REQUEST_PAYLOAD_UNKNOWN_FIELD');
  return payload;
}

function requestBody(value: unknown, maximum: number): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'string' || Buffer.byteLength(value) > maximum) throw new Error('HTTP_REQUEST_BODY_INVALID');
  return value;
}

async function websocket(url: URL, payload: Record<string, unknown>, signal: AbortSignal,
  timeoutMs: number, maximumResponseBytes: number, maximumRequestBytes: number,
  allowedHeaders: ReadonlySet<string>): Promise<Readonly<Record<string, unknown>>> {
  const messages = payload.messages ?? [];
  if (!Array.isArray(messages) || messages.length > 64 || messages.some((item) => typeof item !== 'string'
    || Buffer.byteLength(item) > maximumRequestBytes)
    || messages.reduce((total, item) => total + Buffer.byteLength(String(item)), 0) > maximumRequestBytes) {
    throw new Error('HTTP_WEBSOCKET_MESSAGES_INVALID');
  }
  const minimumMessages = positiveInteger(payload.minimumMessages ?? 1, 'HTTP_WEBSOCKET_MINIMUM_INVALID', 64);
  const wsUrl = new URL(url.href); wsUrl.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  const startedAt = Date.now();
  return new Promise((resolve, reject) => {
    const received: string[] = []; let total = 0; let settled = false;
    const socket = new WebSocket(wsUrl, {
      headers: requestHeaders(payload.headers, allowedHeaders, false),
      maxPayload: maximumResponseBytes,
    });
    const finish = (error?: Error): void => {
      if (settled) return; settled = true; clearTimeout(timer); signal.removeEventListener('abort', abort);
      try { socket.terminate(); } catch { /* The peer can close first. */ }
      if (error) reject(error); else resolve(Object.freeze({ messages: Object.freeze(received),
        messageCount: received.length, sizeBytes: total, durationMs: Date.now() - startedAt }));
    };
    const abort = (): void => finish(new Error('HTTP_REQUEST_CANCELLED'));
    const timer = setTimeout(() => finish(new Error('HTTP_REQUEST_TIMEOUT')), timeoutMs);
    signal.addEventListener('abort', abort, { once: true });
    socket.on('open', () => { for (const message of messages) socket.send(message); if (minimumMessages === 0) finish(); });
    socket.on('message', (data) => {
      const value = String(data); total += Buffer.byteLength(value);
      if (total > maximumResponseBytes) { finish(new Error('HTTP_RESPONSE_SIZE_EXCEEDED')); return; }
      received.push(value); if (received.length >= minimumMessages) finish();
    });
    socket.on('error', (error) => finish(new Error(`HTTP_REQUEST_FAILED:${error.name}`)));
    socket.on('close', () => received.length >= minimumMessages
      ? finish() : finish(new Error('HTTP_WEBSOCKET_MESSAGES_MISSING')));
  });
}

async function responseBytes(response: Response, maximum: number, signal: AbortSignal): Promise<Buffer> {
  const declared = response.headers.get('content-length');
  if (declared !== null && (!/^\d+$/u.test(declared) || Number(declared) > maximum)) {
    throw new Error('HTTP_RESPONSE_SIZE_EXCEEDED');
  }
  if (!response.body) return Buffer.alloc(0);
  const reader = response.body.getReader();
  const chunks: Buffer[] = [];
  let total = 0;
  try {
    for (;;) {
      if (signal.aborted) throw new Error('HTTP_REQUEST_CANCELLED');
      const next = await reader.read();
      if (next.done) break;
      total += next.value.byteLength;
      if (total > maximum) throw new Error('HTTP_RESPONSE_SIZE_EXCEEDED');
      chunks.push(Buffer.from(next.value));
    }
  } finally {
    if (total > maximum || signal.aborted) await reader.cancel().catch(() => undefined);
  }
  return Buffer.concat(chunks, total);
}

export class NetworkHttpCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #allowedOrigins: ReadonlySet<string>;
  readonly #allowedHostSuffixes: readonly string[];
  readonly #allowedPorts: ReadonlySet<number>;
  readonly #maximumResponseBytes: number;
  readonly #maximumRequestBytes: number;
  readonly #maximumExecutionMs: number;
  readonly #allowedMethods: ReadonlySet<string>;
  readonly #allowedRequestHeaders: ReadonlySet<string>;
  readonly #allowWebSocket: boolean;
  readonly #registryHealth: RegistryHealthAccess | undefined;

  constructor(options: NetworkHttpCapabilityInvokerOptions) {
    this.#registryHealth = options.registryHealth ? new RegistryHealthAccess(options.registryHealth) : undefined;
    this.#allowedOrigins = new Set(options.allowedOrigins.map(canonicalOrigin));
    this.#allowedHostSuffixes = Object.freeze(options.allowedHostSuffixes.map(canonicalSuffix));
    this.#allowedPorts = new Set(options.allowedPorts.map((port) => positiveInteger(port, 'HTTP_RUNTIME_PORT_INVALID', 65_535)));
    this.#maximumResponseBytes = positiveInteger(options.maximumResponseBytes, 'HTTP_RUNTIME_RESPONSE_LIMIT_INVALID');
    this.#maximumRequestBytes = positiveInteger(options.maximumRequestBytes ?? options.maximumResponseBytes,
      'HTTP_RUNTIME_REQUEST_LIMIT_INVALID');
    this.#maximumExecutionMs = positiveInteger(options.maximumExecutionMs, 'HTTP_RUNTIME_EXECUTION_LIMIT_INVALID', MAX_TIMER_MS);
    const methods = options.allowedMethods ?? ['GET', 'HEAD'];
    if (!methods.length || methods.some((method) => !METHODS.has(method))) throw new Error('HTTP_RUNTIME_METHOD_POLICY_INVALID');
    this.#allowedMethods = new Set(methods);
    const headers = (options.allowedRequestHeaders ?? ['accept']).map((name) => name.toLowerCase());
    if (headers.some((name) => !/^[a-z0-9!#$%&'*+.^_`|~-]+$/u.test(name)
      || DENIED_HEADERS.has(name))) throw new Error('HTTP_RUNTIME_HEADER_POLICY_INVALID');
    this.#allowedRequestHeaders = new Set(headers);
    this.#allowWebSocket = options.allowWebSocket === true;
    if (this.#allowedOrigins.size === 0 && this.#allowedHostSuffixes.length === 0) throw new Error('HTTP_RUNTIME_TARGET_POLICY_REQUIRED');
    if (this.#allowedPorts.size === 0) throw new Error('HTTP_RUNTIME_PORT_POLICY_REQUIRED');
  }

  #isRegistryHealth(url: URL): boolean { return this.#registryHealth?.matches(url) === true; }

  #target(value: string, inputs?: readonly ResolvedInputV1[]): Readonly<{ url: URL; exactOrigin: boolean }> {
    let url: URL;
    try { url = new URL(value); } catch { throw new Error('HTTP_REQUEST_URL_INVALID'); }
    if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash) throw new Error('HTTP_REQUEST_URL_INVALID');
    const port = Number(url.port || (url.protocol === 'https:' ? 443 : 80));
    const registryHealth = this.#isRegistryHealth(url);
    if (!registryHealth && !this.#allowedPorts.has(port)) throw new Error(`HTTP_REQUEST_PORT_DENIED:${port}`);
    const hostname = url.hostname.toLowerCase();
    const suffixAllowed = this.#allowedHostSuffixes.some((suffix) => hostname.endsWith(suffix)
      && hostname.length > suffix.length);
    const configuredExactOrigin = registryHealth || this.#allowedOrigins.has(url.origin);
    if (!configuredExactOrigin && !suffixAllowed) throw new Error(`HTTP_REQUEST_ORIGIN_DENIED:${url.origin}`);
    const exactOrigin = configuredExactOrigin || fixtureOrigins(inputs ?? []).has(url.origin);
    return Object.freeze({ url, exactOrigin });
  }

  async #responseBytes(response: Response, scope: { method: string; maximumBytes: number; signal: AbortSignal; registryHealth: boolean }): Promise<Buffer> {
    const bytes = scope.method === 'HEAD' ? Buffer.alloc(0) : await responseBytes(response, scope.maximumBytes, scope.signal);
    if (scope.registryHealth) this.#registryHealth!.assertResponse(bytes, response.headers.get('content-type'));
    if (scope.method === 'HEAD') await response.body?.cancel().catch(() => undefined);
    return bytes;
  }

  async invoke(capability: string, request: any, signal: AbortSignal,
    inputs?: readonly ResolvedInputV1[]): Promise<Readonly<Record<string, unknown>>> {
    if (capability !== 'network.http' || !['request', 'websocket'].includes(request?.operation)
      || request?.resource?.type !== 'network.url' || typeof request?.resource?.canonicalId !== 'string') {
      throw new Error('HTTP_CAPABILITY_REQUEST_INVALID');
    }
    if (signal.aborted) throw new Error('HTTP_REQUEST_CANCELLED');
    signal = fixtureAuthoritySignal(inputs ?? [], signal);
    const { url, exactOrigin } = this.#target(request.resource.canonicalId, inputs);
    const payload = exactPayload(request.payload); const registryHeaders = this.#registryHealth?.headers(url, request.operation, payload);
    if (request.operation === 'websocket') {
      if (!this.#allowWebSocket) throw new Error('HTTP_WEBSOCKET_DENIED');
      if (!exactOrigin) throw new Error('HTTP_WEBSOCKET_EXACT_ORIGIN_REQUIRED');
      if (!this.#allowedMethods.has('GET')) throw new Error('HTTP_REQUEST_METHOD_DENIED:GET');
      const timeoutMs = positiveInteger(payload.timeoutMs ?? this.#maximumExecutionMs,
        'HTTP_REQUEST_TIMEOUT_INVALID', this.#maximumExecutionMs);
      const maximumResponseBytes = positiveInteger(payload.maximumResponseBytes ?? this.#maximumResponseBytes,
        'HTTP_REQUEST_RESPONSE_LIMIT_INVALID', this.#maximumResponseBytes);
      return websocket(url, payload, signal, timeoutMs, maximumResponseBytes, this.#maximumRequestBytes,
        this.#allowedRequestHeaders);
    }
    const method = typeof payload.method === 'string' ? payload.method.toUpperCase() : 'GET';
    if (!METHODS.has(method) || !this.#allowedMethods.has(method)) throw new Error(`HTTP_REQUEST_METHOD_DENIED:${method}`);
    if (!exactOrigin) throw new Error(`HTTP_REQUEST_EXACT_ORIGIN_REQUIRED:${method}:${url.origin}`);
    const timeoutMs = positiveInteger(payload.timeoutMs ?? this.#maximumExecutionMs,
      'HTTP_REQUEST_TIMEOUT_INVALID', this.#maximumExecutionMs);
    const maximumResponseBytes = positiveInteger(payload.maximumResponseBytes ?? this.#maximumResponseBytes,
      'HTTP_REQUEST_RESPONSE_LIMIT_INVALID', this.#maximumResponseBytes);
    const returnedHeaders = responseHeaderNames(payload.responseHeaders);
    const timeout = AbortSignal.timeout(timeoutMs);
    const combined = AbortSignal.any([signal, timeout]);
    const startedAt = Date.now();
    let response: Response;
    try {
      const body = ['GET', 'HEAD'].includes(method) ? undefined
        : requestBody(payload.body, this.#maximumRequestBytes);
      const permittedHeaders = this.#allowedRequestHeaders;
      response = await fetch(url, { method, headers: { ...requestHeaders(payload.headers, permittedHeaders), ...registryHeaders },
        ...(body === undefined ? {} : { body }), redirect: 'manual', signal: combined });
      if (response.status >= 300 && response.status < 400) throw new Error('HTTP_RESPONSE_REDIRECT_DENIED');
      const bytes = await this.#responseBytes(response, { method, maximumBytes: maximumResponseBytes,
        signal: combined, registryHealth: Boolean(registryHeaders) });
      return Object.freeze({
        status: response.status,
        headers: Object.freeze(Object.fromEntries(returnedHeaders.map((name) => [name,
          name === 'content-type' ? response.headers.get(name)?.split(';', 1)[0]?.trim().toLowerCase() ?? null
            : response.headers.get(name)]))),
        body: bytes.toString('utf8'),
        sizeBytes: bytes.byteLength,
        bodyDigest: `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`,
        durationMs: Date.now() - startedAt,
      });
    } catch (error) {
      if (signal.aborted) throw new Error('HTTP_REQUEST_CANCELLED');
    signal = fixtureAuthoritySignal(inputs ?? [], signal);
      if (timeout.aborted) throw new Error('HTTP_REQUEST_TIMEOUT');
      if (error instanceof Error && error.message.startsWith('HTTP_')) throw error;
      throw new Error(`HTTP_REQUEST_FAILED:${error instanceof Error ? error.name : 'unknown'}`);
    }
  }
}

import type { ChildProcess } from 'node:child_process';
import { captureLinuxProcessGroup, linuxProcessGroupRunning } from '@kubeclaw/plugin-foundation/processes/linux-process-group';

// Own both the native close and the group lifetime. A leader can exit while
// descendants remain runnable or keep its pipes open.
export class ProcessInputLifecycle {
  readonly #child: ChildProcess;
  readonly #closed: Promise<void>;
  readonly #group: number | undefined;
  readonly #identityError: unknown;
  #cleanup: Promise<void> | undefined;

  constructor(child: ChildProcess, closed: Promise<void>) {
    this.#child = child; this.#closed = closed;
    if (process.platform === 'linux' && child.pid) {
      try { this.#group = captureLinuxProcessGroup(child.pid); }
      catch (error) { this.#identityError = error; }
    }
  }

  cleanup(): Promise<void> {
    this.#cleanup ??= this.#finish();
    return this.#cleanup;
  }

  async #finish(): Promise<void> {
    const deadline = Date.now() + 1_500;
    let force: NodeJS.Timeout | undefined;
    let bound: NodeJS.Timeout | undefined;
    try {
      // Give a native supervisor time to terminate and reap adopted descendants,
      // including children that deliberately left the original process group.
      this.#signal('SIGTERM');
      force = setTimeout(() => {
        try { this.#signal('SIGKILL'); } catch { /* The awaited acknowledgement reports failure. */ }
      }, 250);
      await Promise.race([
        Promise.all([this.#closed, this.#acknowledge(deadline)]),
        new Promise<never>((_resolve, reject) => {
          bound = setTimeout(() => reject(new Error('PROCESS_INPUT_CLEANUP_TIMEOUT')), Math.max(1, deadline - Date.now()));
        }),
      ]);
    } catch (error) {
      try { this.#signal('SIGKILL'); } catch { /* Preserve the observed cleanup error. */ }
      // A process outside the owned group can retain a pipe. Bound host disposal
      // and report failure; destroying host pipe ends is not a termination claim.
      this.#child.stdin?.destroy(); this.#child.stdout?.destroy(); this.#child.stderr?.destroy();
      throw error;
    } finally { clearTimeout(force); clearTimeout(bound); }
  }

  async #acknowledge(deadline: number): Promise<void> {
    if (process.platform !== 'linux') return;
    if (!this.#alive()) return;
    if (this.#group === undefined) throw new Error('PROCESS_INPUT_IDENTITY_UNAVAILABLE', { cause: this.#identityError });
    while (await linuxProcessGroupRunning(this.#group, deadline)) {
      if (Date.now() >= deadline) throw new Error('PROCESS_INPUT_CLEANUP_TIMEOUT');
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  }

  #alive(): boolean {
    if (!this.#child.pid || process.platform === 'win32') return false;
    try { process.kill(-this.#child.pid, 0); return true; }
    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ESRCH') return false; throw error; }
  }

  #signal(signal: NodeJS.Signals): void {
    try {
      if (process.platform !== 'win32' && this.#child.pid) process.kill(-this.#child.pid, signal);
      else this.#child.kill(signal);
    } catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ESRCH') throw error; }
  }
}

import { spawn } from 'node:child_process';
import { ProcessInputLifecycle } from './process-input-lifecycle.ts';

export class ProcessInputCleanupError extends AggregateError {
  constructor(prefix: string, failure: Error | undefined, cleanup: unknown) {
    super([...(failure ? [failure] : []), cleanup], `${prefix}_CLEANUP_FAILED`, { cause: failure ?? cleanup });
    this.name = 'ProcessInputCleanupError';
  }
}

export interface ProcessInputOptions {
  readonly cwd?: string;
  readonly env?: NodeJS.ProcessEnv;
  readonly signal?: AbortSignal;
  readonly timeoutMs: number;
  readonly maximumOutputBytes: number;
  readonly prefix: string;
  readonly outputLimitError?: string;
  readonly input?: string | Buffer | null;
}
export interface ProcessInputResult {
  readonly code: number | null;
  readonly signal: NodeJS.Signals | null;
  readonly stdout: Buffer;
  readonly stderr: Buffer;
}

// Attach every stream error handler before sending input. Failures settle only
// after close and process-group acknowledgement, with a bounded failure on incomplete disposal.
export function runProcessInput(command: string, args: readonly string[], options: ProcessInputOptions): Promise<ProcessInputResult> {
  if (options.signal?.aborted) return Promise.reject(new Error(`${options.prefix}_CANCELLED`, { cause: options.signal.reason }));
  return new Promise((resolve, reject) => {
    const child = spawn(command, [...args], { ...(options.cwd ? { cwd: options.cwd } : {}),
      ...(options.env ? { env: options.env } : {}), detached: process.platform !== 'win32', stdio: ['pipe', 'pipe', 'pipe'] });
    const output = { stdout: [] as Buffer[], stderr: [] as Buffer[], stdoutBytes: 0, stderrBytes: 0 };
    let failure: Error | undefined;
    let finishing = false;
    let resolveClosed!: () => void;
    const closed = new Promise<void>((resolveClose) => { resolveClosed = resolveClose; });
    let exitCode: number | null = null;
    let exitSignal: NodeJS.Signals | null = null;
    let lifecycle: ProcessInputLifecycle;
    const settle = (cleanup?: unknown): void => {
      clearTimeout(timer); options.signal?.removeEventListener('abort', abort);
      const stdout = Buffer.concat(output.stdout, output.stdoutBytes);
      const stderr = Buffer.concat(output.stderr, output.stderrBytes);
      const error = cleanup ? new ProcessInputCleanupError(options.prefix, failure, cleanup) : failure;
      if (error) reject(Object.assign(error, { stdout: stdout.toString('utf8'), stderr: stderr.toString('utf8') }));
      else resolve({ code: exitCode, signal: exitSignal, stdout, stderr });
    };
    const finish = (): void => {
      if (finishing) return;
      finishing = true;
      void lifecycle.cleanup().then(() => settle(), (error) => settle(error));
    };
    const fail = (error: Error): void => {
      failure ??= error;
      child.stdin.destroy();
      finish();
    };
    const collect = (stream: 'stdout' | 'stderr', chunk: Buffer): void => {
      if (failure) return;
      const key = stream === 'stdout' ? 'stdoutBytes' : 'stderrBytes';
      if (chunk.byteLength > options.maximumOutputBytes - output[key]) {
        fail(new Error(options.outputLimitError ?? `${options.prefix}_OUTPUT_LIMIT`)); return;
      }
      output[key] += chunk.byteLength; output[stream].push(chunk);
    };
    const abort = (): void => fail(new Error(`${options.prefix}_CANCELLED`, { cause: options.signal?.reason }));
    const timer = setTimeout(() => fail(new Error(`${options.prefix}_TIMEOUT`)), options.timeoutMs);
    options.signal?.addEventListener('abort', abort, { once: true });
    child.stdin.on('error', (error) => fail(new Error(`${options.prefix}_STDIN_FAILED`, { cause: error })));
    child.stdout.on('error', (error) => fail(new Error(`${options.prefix}_STDOUT_FAILED`, { cause: error })));
    child.stderr.on('error', (error) => fail(new Error(`${options.prefix}_STDERR_FAILED`, { cause: error })));
    child.stdout.on('data', (chunk: Buffer) => collect('stdout', chunk));
    child.stderr.on('data', (chunk: Buffer) => collect('stderr', chunk));
    child.once('error', fail);
    child.once('exit', (code, signal) => { exitCode = code; exitSignal = signal; finish(); });
    child.once('close', (code, signal) => {
      exitCode = code; exitSignal = signal; resolveClosed(); finish();
    });
    lifecycle = new ProcessInputLifecycle(child, closed);
    if (options.signal?.aborted) { abort(); return; }
    try { child.stdin.end(options.input ?? undefined); }
    catch (error) { fail(new Error(`${options.prefix}_STDIN_FAILED`, { cause: error })); }
  });
}

import type { TestProviderCapabilityRequest, TestProviderExecutionContext } from '@kubeclaw/plugin-sdk';

export class ProviderCapabilities {
  readonly #controller = new AbortController();
  readonly #pending = new Map<string, { operation: Promise<void>; controller: AbortController }>();
  readonly #maximum: number;
  constructor(maximum = 32) { this.#maximum = maximum; }
  get pending(): number { return this.#pending.size; }

  handle(id: string, capability: string, request: TestProviderCapabilityRequest,
    context: TestProviderExecutionContext, send: (message: unknown) => boolean): Promise<void> {
    if (this.#controller.signal.aborted) return Promise.reject(this.#controller.signal.reason);
    if (this.#pending.has(id)) return Promise.reject(new Error('TEST_PROVIDER_CAPABILITY_DUPLICATE'));
    if (this.#pending.size >= this.#maximum) return Promise.reject(new Error('TEST_PROVIDER_CAPABILITY_LIMIT'));
    const controller = new AbortController();
    const signal = AbortSignal.any([context.signal, this.#controller.signal, controller.signal]);
    const operation = Promise.resolve().then(async () => {
      try {
        if (signal.aborted) throw signal.reason;
        const value = await context.invoke(capability, request, signal);
        if (signal.aborted) throw signal.reason;
        send({ kind: 'capability-result', id, ok: true, value });
      } catch (error) {
        if (!signal.aborted) send({ kind: 'capability-result', id, ok: false, error: error instanceof Error ? error.message : String(error) });
      }
    }).finally(() => this.#pending.delete(id));
    this.#pending.set(id, { operation, controller });
    return operation;
  }

  cancel(id: string, reason: Error): void { this.#pending.get(id)?.controller.abort(reason); }

  abort(reason: Error): void { this.#controller.abort(reason); }

  async drain(timeoutMs = 1_000): Promise<void> {
    let timer: NodeJS.Timeout | undefined;
    try {
      await Promise.race([
        Promise.allSettled([...this.#pending.values()].map(({ operation }) => operation)),
        new Promise<never>((_resolve, reject) => { timer = setTimeout(() => reject(new Error('TEST_PROVIDER_CAPABILITY_DRAIN_TIMEOUT')), timeoutMs); }),
      ]);
    } finally { clearTimeout(timer); }
  }
}

import { ProviderCapabilities } from './provider-capabilities.ts';
import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import readline from 'node:readline';
