export interface CompactionReceipt {
  readonly schemaVersion: 'buster-job-compaction-receipt.v1';
  readonly intent: CompactionIntent;
  readonly intentDigest: string;
  readonly compactedAt: string;
  readonly revision: string;
  readonly tree: string;
  readonly archiveDigest: string;
  readonly archiveBytes: number;
  readonly releasedMetadataBytes: number;
}
export const compactionDigest = (value: unknown): string =>
  `sha256:${crypto.createHash('sha256').update(canonicalJson(value)).digest('hex')}`;

function assertRetainedSourceIntent(source: CompactionIntent['source']): void {
  if (!source || Object.keys(source).sort().join(',') !== 'repositoryId,repositoryRoot,retainedRef,retention'
    || typeof source.repositoryId !== 'string' || !source.repositoryId
    || typeof source.repositoryRoot !== 'string' || !path.isAbsolute(source.repositoryRoot)
    || !/^refs\/tags\/[A-Za-z0-9][A-Za-z0-9._/-]{0,255}$/u.test(source.retainedRef)
    || source.retention !== 'until-project-deletion') throw new Error('BUSTER_COMPACTION_INTENT_INVALID');
}
export function assertCompactionIntent(intent: CompactionIntent): void {
  if (!intent || Object.keys(intent).sort().join(',') !== 'actor,expectedPayloadDigest,jobId,maximumEvidenceBytes,operationId,source'
    || !/^[A-Za-z0-9][A-Za-z0-9._:/-]{0,255}$/u.test(intent.operationId)
    || typeof intent.actor !== 'string' || !intent.actor.trim() || intent.actor.length > 256
    || !Number.isSafeInteger(intent.maximumEvidenceBytes) || intent.maximumEvidenceBytes < 1
    || !/^job:[a-f0-9]{64}$/u.test(intent.jobId)
    || !/^sha256:[a-f0-9]{64}$/u.test(intent.expectedPayloadDigest)) throw new Error('BUSTER_COMPACTION_INTENT_INVALID');
  assertRetainedSourceIntent(intent.source);
}
function assertCompactedSource(payload: CompactedPlanJobRecord): void {
  const { compaction, job } = payload;
  if (job.repositoryArchive.schemaVersion !== 'repository-archive-summary.v1' || 'data' in job.repositoryArchive
    || compaction.archiveDigest !== job.repositoryArchive.contentDigest
    || compaction.archiveBytes !== job.repositoryArchive.sizeBytes
    || compaction.revision !== job.sourceSnapshot.revision
    || compaction.tree !== job.sourceSnapshot.tree
    || compaction.archiveDigest !== job.sourceSnapshot.archiveContentDigest
    || compaction.archiveBytes !== job.sourceSnapshot.archiveSizeBytes
    || compaction.intent.source.repositoryId !== job.sourceSnapshot.repositoryId) throw new Error('BUSTER_COMPACTED_JOB_INVALID');
}
export function assertCompactedPlanJobRecord(payload: CompactedPlanJobRecord): void {
  assertCompactionIntent(payload.compaction.intent);
  validatePipelineTestGateContract('remotePlanStatus', payload.status);
  assertCompactedSource(payload);
  if (payload.job.schemaVersion !== 'buster-plan-job-header.v1' || payload.status.state !== 'completed' || !payload.status.result
    || payload.compaction.schemaVersion !== 'buster-job-compaction-receipt.v1'
    || payload.compaction.intentDigest !== compactionDigest(payload.compaction.intent)
    || payload.compaction.intent.jobId !== payload.job.jobId
    || payload.status.jobId !== payload.job.jobId
    || payload.status.requestDigest !== payload.job.requestDigest
    || !Number.isSafeInteger(payload.compaction.releasedMetadataBytes) || payload.compaction.releasedMetadataBytes < 1
    || remotePlanJobId(payload.job.idempotencyKey) !== payload.job.jobId
    || resolvedTestPlanDigest(payload.job.plan) !== payload.job.plan.planDigest) throw new Error('BUSTER_COMPACTED_JOB_INVALID');
}

async function git(root: string, args: readonly string[], maximumBytes: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    execFile('git', ['-C', root, ...args], { encoding: 'buffer', maxBuffer: maximumBytes, timeout: 120000 }, (error, stdout) => {
      if (error) reject(new Error('BUSTER_COMPACTION_SOURCE_GIT_FAILED', { cause: error }));
      else resolve(stdout);
    });
  });
}
/** Read an existing, explicitly retained ref. Never creates an archive or a ref on disk. */
export async function verifyRetainedSource(job: StoredPlanJob['job'], intent: CompactionIntent): Promise<void> {
  const { sourceSnapshot: snapshot, repositoryArchive: archive } = job;
  const source = intent.source;
  if (source.repositoryId !== snapshot.repositoryId) throw new Error('BUSTER_COMPACTION_REPOSITORY_IDENTITY_MISMATCH');
  const root = await fs.realpath(source.repositoryRoot);
  if (root !== source.repositoryRoot || (await git(root, ['rev-parse', '--show-toplevel'], 4096)).toString().trim() !== root) {
    throw new Error('BUSTER_COMPACTION_REPOSITORY_ROOT_MISMATCH');
  }
  await git(root, ['check-ref-format', source.retainedRef], 4096);
  const revision = (await git(root, ['rev-parse', '--verify', '--end-of-options', `${source.retainedRef}^{commit}`], 4096)).toString().trim();
  const tree = (await git(root, ['rev-parse', '--verify', '--end-of-options', `${revision}^{tree}`], 4096)).toString().trim();
  if (`git:${revision}` !== snapshot.revision || `git:${tree}` !== snapshot.tree) throw new Error('BUSTER_COMPACTION_SOURCE_REVISION_MISMATCH');
  const bytes = await git(root, ['archive', '--format=tar.gz', revision], archive.sizeBytes + 1);
  const digest = `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`;
  if (bytes.byteLength !== archive.sizeBytes || digest !== archive.contentDigest
    || digest !== snapshot.archiveContentDigest || bytes.byteLength !== snapshot.archiveSizeBytes) {
    throw new Error('BUSTER_COMPACTION_SOURCE_BYTES_MISMATCH');
  }
  const still = (await git(root, ['rev-parse', '--verify', '--end-of-options', `${source.retainedRef}^{commit}`], 4096)).toString().trim();
  if (still !== revision) throw new Error('BUSTER_COMPACTION_SOURCE_REF_CHANGED');
}

export function resultArtifacts(result: RemotePlanResultV1) {
  return result.attempts.flatMap(attempt => [
    ...attempt.evidence.map(item => item.artifact),
    ...attempt.outputs.filter(item => item.kind === 'artifact').map(item => item.artifact),
    ...attempt.reports.map(item => item.sourceArtifact),
  ]);
}
export async function readJobArtifact(runtimeRoot: string, jobId: string,
  artifact: ReturnType<typeof resultArtifacts>[number], maximumBytes: number): Promise<Buffer> {
  if (artifact.sizeBytes > maximumBytes) throw new Error('BUSTER_REMOTE_EVIDENCE_SIZE_EXCEEDED');
  const source = new URL(artifact.storageUrl);
  if (source.protocol !== 'file:') throw new Error('BUSTER_REMOTE_EVIDENCE_STORAGE_UNSUPPORTED');
  const candidate = await fs.realpath(fileURLToPath(source));
  const root = await fs.realpath(path.join(path.resolve(runtimeRoot), crypto.createHash('sha256').update(jobId).digest('hex')));
  if (!candidate.startsWith(`${root}${path.sep}`)) throw new Error('BUSTER_REMOTE_EVIDENCE_PATH_FORBIDDEN');
  const handle = await fs.open(candidate, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
  try {
    const stat = await handle.stat();
    if (!stat.isFile() || stat.size !== artifact.sizeBytes) throw new Error('BUSTER_REMOTE_EVIDENCE_SIZE_MISMATCH');
    const bounded = Buffer.alloc(artifact.sizeBytes + 1);
    let total = 0;
    while (total < bounded.byteLength) {
      const read = await handle.read(bounded, total, bounded.byteLength - total, total);
      if (!read.bytesRead) break;
      total += read.bytesRead;
    }
    if (total !== artifact.sizeBytes) throw new Error('BUSTER_REMOTE_EVIDENCE_SIZE_MISMATCH');
    const bytes = bounded.subarray(0, total);
    if (`sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}` !== artifact.contentDigest) {
      throw new Error('BUSTER_REMOTE_EVIDENCE_DIGEST_MISMATCH');
    }
    return bytes;
  } finally { await handle.close(); }
}

import crypto from 'node:crypto';
import http from 'node:http';
import https from 'node:https';
import { validatePipelineTestGateContract, type RemotePlanJobV1 } from '@kubeclaw/pipeline-test-gate-contract';
import type { BusterRemotePlanService } from './remote-plan-service.ts';
import { authorizeProxiedSpiffePeer } from '@kubeclaw/worker-core';

function authorized(request: http.IncomingMessage, token: string): boolean {
  const value = request.headers.authorization;
  if (!value?.startsWith('Bearer ')) return false;
  const supplied = Buffer.from(value.slice('Bearer '.length));
  const expected = Buffer.from(token);
  return supplied.byteLength === expected.byteLength && crypto.timingSafeEqual(supplied, expected);
}

function authorize(request: http.IncomingMessage, options: {
  readonly token?: string;
  readonly trustedPeerSpiffeIds?: readonly string[];
}): boolean {
  if (options.trustedPeerSpiffeIds) {
    try {
      authorizeProxiedSpiffePeer(request.headers, request.socket.remoteAddress,
        new Set(options.trustedPeerSpiffeIds));
      return true;
    } catch {
      return false;
    }
  }
  return options.token !== undefined && authorized(request, options.token);
}

async function requestBody(request: http.IncomingMessage, maximumBytes: number): Promise<unknown> {
  const declared = Number(request.headers['content-length']);
  if (Number.isFinite(declared) && declared > maximumBytes) throw new Error('BUSTER_REMOTE_REQUEST_SIZE_EXCEEDED');
  const chunks: Buffer[] = [];
  let total = 0;
  for await (const chunk of request) {
    const bytes = Buffer.from(chunk);
    total += bytes.byteLength;
    if (total > maximumBytes) throw new Error('BUSTER_REMOTE_REQUEST_SIZE_EXCEEDED');
    chunks.push(bytes);
  }
  try { return JSON.parse(Buffer.concat(chunks).toString('utf8')); }
  catch (error) { throw new Error('BUSTER_REMOTE_REQUEST_INVALID', { cause: error }); }
}

function send(response: http.ServerResponse, status: number, body: unknown, maximumBytes: number): void {
  const bytes = Buffer.from(JSON.stringify(body));
  if (bytes.byteLength > maximumBytes) {
    const fallback = Buffer.from(JSON.stringify({ error: 'BUSTER_REMOTE_RESPONSE_SIZE_EXCEEDED' }));
    response.writeHead(500, { 'content-type': 'application/json', 'content-length': fallback.byteLength });
    response.end(fallback);
    return;
  }
  response.writeHead(status, {
    'content-type': 'application/json',
    'content-length': bytes.byteLength,
    'cache-control': 'no-store',
  });
  response.end(bytes);
}

function jobId(url: string | undefined): string | null {
  const match = url?.match(/^\/v1\/plan-jobs\/([^/?#]+)$/u);
  if (!match?.[1]) return null;
  try { return decodeURIComponent(match[1]); }
  catch { throw new Error('BUSTER_REMOTE_JOB_ID_INVALID'); }
}

function evidenceRoute(url: string | undefined): { jobId: string; digest: string } | null {
  const match = url?.match(/^\/v1\/plan-jobs\/([^/?#]+)\/evidence\/(sha256%3A|sha256:)([a-f0-9]{64})$/u);
  if (!match?.[1] || !match[2] || !match[3]) return null;
  try { return { jobId: decodeURIComponent(match[1]), digest: `sha256:${match[3]}` }; }
  catch { throw new Error('BUSTER_REMOTE_JOB_ID_INVALID'); }
}

function resultRoute(url: string | undefined): { jobId: string; digest: string } | null {
  const match = url?.match(/^\/v1\/plan-jobs\/([^/?#]+)\/results\/(sha256%3A|sha256:)([a-f0-9]{64})$/u);
  if (!match?.[1] || !match[2] || !match[3]) return null;
  try { return { jobId: decodeURIComponent(match[1]), digest: `sha256:${match[3]}` }; }
  catch { throw new Error('BUSTER_REMOTE_JOB_ID_INVALID'); }
}

async function healthResponse(request: http.IncomingMessage, response: http.ServerResponse, options: {
  readonly service: BusterRemotePlanService;
  readonly maximumResponseBytes: number;
}): Promise<boolean> {
  if (request.method === 'GET' && request.url === '/healthz') {
    send(response, 200, { schemaVersion: 'buster-plan-health.v2', live: true }, options.maximumResponseBytes);
    return true;
  }
  if (request.method === 'GET' && request.url === '/bootstrapz') {
    const ready = options.service.bootstrapReady();
    send(response, ready ? 200 : 503, { schemaVersion: 'buster-plan-bootstrap.v1', initialized: ready }, options.maximumResponseBytes);
    return true;
  }
  if (request.method === 'GET' && request.url === '/readyz') {
    const status = await options.service.readiness();
    send(response, status.ready ? 200 : 503, status, options.maximumResponseBytes);
    return true;
  }
  return false;
}

export function createBusterRemotePlanHttpServer(options: {
  readonly service: BusterRemotePlanService;
  readonly token?: string;
  readonly trustedPeerSpiffeIds?: readonly string[];
  readonly maximumRequestBytes: number;
  readonly maximumResponseBytes: number;
  readonly maximumResultBytes: number;
  readonly tls?: Readonly<{ key: string | Buffer; cert: string | Buffer }>;
}): http.Server {
  if ((options.token === undefined) === (options.trustedPeerSpiffeIds === undefined)) {
    throw new Error('BUSTER_REMOTE_AUTHENTICATION_INVALID');
  }
  if (options.token !== undefined && options.token.length < 32) throw new Error('BUSTER_REMOTE_TOKEN_INVALID');
  if (options.trustedPeerSpiffeIds?.length === 0) throw new Error('BUSTER_REMOTE_SPIFFE_POLICY_INVALID');
  for (const limit of [options.maximumRequestBytes, options.maximumResponseBytes, options.maximumResultBytes]) {
    if (!Number.isSafeInteger(limit) || limit < 1) throw new Error('BUSTER_REMOTE_HTTP_LIMIT_INVALID');
  }
  const handler: http.RequestListener = (request, response) => {
    void (async () => {
      if (await healthResponse(request, response, options)) return;
      if (!authorize(request, options)) {
        send(response, 401, { error: 'unauthorized' }, options.maximumResponseBytes);
        return;
      }
      if (request.method === 'POST' && request.url === '/v1/plan-jobs') {
        const value = await requestBody(request, options.maximumRequestBytes);
        validatePipelineTestGateContract('remotePlanJob', value);
        const status = await options.service.submit(value as RemotePlanJobV1);
        send(response, status.state === 'accepted' ? 202 : 200, status, options.maximumResponseBytes);
        return;
      }
      const evidence = evidenceRoute(request.url);
      if (evidence && request.method === 'GET') {
        const bytes = await options.service.evidence(evidence.jobId, evidence.digest, options.maximumResponseBytes);
        response.writeHead(200, {
          'content-type': 'application/octet-stream', 'content-length': bytes.byteLength,
          'content-digest': evidence.digest, 'cache-control': 'private, immutable',
        });
        response.end(bytes);
        return;
      }
      const result = resultRoute(request.url);
      if (result && request.method === 'GET') {
        const bytes = await options.service.result(result.jobId, result.digest, options.maximumResultBytes);
        response.writeHead(200, {
          'content-type': 'application/json', 'content-length': bytes.byteLength,
          'content-digest': result.digest, 'cache-control': 'private, immutable',
        });
        response.end(bytes);
        return;
      }
      const id = jobId(request.url);
      if (id && request.method === 'GET') {
        send(response, 200, await options.service.status(id), options.maximumResponseBytes);
        return;
      }
      if (id && request.method === 'DELETE') {
        send(response, 200, await options.service.cancel(id), options.maximumResponseBytes);
        return;
      }
      send(response, 404, { error: 'not found' }, options.maximumResponseBytes);
    })().catch((error) => {
      const message = error instanceof Error ? error.message : String(error);
      const status = ['BUSTER_REMOTE_ADMISSION_FULL', 'BUSTER_REMOTE_RESULT_CAPACITY_EXCEEDED'].includes(message) ? 429
        : ['BUSTER_REMOTE_SHUTTING_DOWN', 'BUSTER_DEPENDENCY_UNAVAILABLE'].includes(message) ? 503
        : message.includes('NOT_FOUND') ? 404
        : message.includes('CONFLICT') ? 409
          : message.includes('SIZE_EXCEEDED') ? 413 : 400;
      if (!response.headersSent) send(response, status, { error: message }, options.maximumResponseBytes);
      else response.destroy();
    });
  };
  return options.tls ? https.createServer(options.tls, handler) : http.createServer(handler);
}

import type { AddressInfo } from 'node:net';
import type { Server } from 'node:http';
import { createBusterRemotePlanHttpServer } from './remote-plan-http.ts';
import type { BusterRemotePlanService } from './remote-plan-service.ts';

export interface BusterRemotePlanRuntimeOptions {
  readonly service: BusterRemotePlanService;
  readonly host: string;
  readonly port: number;
  readonly token?: string;
  readonly trustedPeerSpiffeIds?: readonly string[];
  readonly maximumRequestBytes: number;
  readonly maximumResponseBytes: number;
  readonly maximumResultBytes: number;
  readonly shutdownTimeoutMs: number;
  readonly tls?: Readonly<{ key: string | Buffer; cert: string | Buffer }>;
}

export class BusterRemotePlanRuntime {
  readonly #options: BusterRemotePlanRuntimeOptions;
  readonly #server: Server;
  #started = false;

  constructor(options: BusterRemotePlanRuntimeOptions) {
    if (options.host.length === 0) throw new Error('BUSTER_REMOTE_HOST_INVALID');
    if (!Number.isSafeInteger(options.port) || options.port < 0 || options.port > 65_535) {
      throw new Error('BUSTER_REMOTE_PORT_INVALID');
    }
    if (!Number.isSafeInteger(options.shutdownTimeoutMs) || options.shutdownTimeoutMs < 1) {
      throw new Error('BUSTER_REMOTE_SHUTDOWN_TIMEOUT_INVALID');
    }
    this.#options = options;
    this.#server = createBusterRemotePlanHttpServer(options);
  }

  async start(): Promise<AddressInfo> {
    if (this.#started) throw new Error('BUSTER_REMOTE_RUNTIME_ALREADY_STARTED');
    await this.#options.service.recover();
    await new Promise<void>((resolve, reject) => {
      const onError = (error: Error): void => reject(error);
      this.#server.once('error', onError);
      this.#server.listen(this.#options.port, this.#options.host, () => {
        this.#server.off('error', onError);
        resolve();
      });
    });
    this.#started = true;
    const address = this.#server.address();
    if (!address || typeof address === 'string') throw new Error('BUSTER_REMOTE_ADDRESS_INVALID');
    return address;
  }

  async stop(): Promise<void> {
    if (!this.#started) return;
    this.#started = false;
    const close = new Promise<void>((resolve, reject) => {
      this.#server.close((error) => error ? reject(error) : resolve());
    });
    let timer: NodeJS.Timeout | undefined;
    try {
      await Promise.race([
        close,
        new Promise<void>((resolve) => {
          timer = setTimeout(() => {
            this.#server.closeAllConnections();
            resolve();
          }, this.#options.shutdownTimeoutMs);
        }),
      ]);
    } finally {
      if (timer) clearTimeout(timer);
      await this.#options.service.shutdown(this.#options.shutdownTimeoutMs);
    }
  }
}

