}

function receipt(
  authorityId: string,
  nonce: string,
  resultDigest: string,
): ReceiptRefV1 {
  const receiptId = `receipt:${crypto.createHash("sha256").update(`${authorityId}:${nonce}:${resultDigest}`).digest("hex")}`;
  return Object.freeze({
    receiptId,
    receiptDigest: digest({ authorityId, receiptId, resultDigest }),
  });
}

