function finalNodeResult(
  plan: ResolvedTestPlanV1,
  node: ResolvedPlanNodeV1,
  attempts: readonly AttemptResultV1[],
  state: TerminalNodeState,
  outcome: TestOutcome,
  skipReason: string | null,
  authorityId: string,
  nonce: string,
): NodeResultV1 {
  const finalAttempt = attempts.at(-1) ?? null;
  const unstable =
    outcome === "passed" &&
    attempts
      .slice(0, -1)
      .some(
        (attempt) =>
          attempt.executionState !== "completed" ||
          attempt.outcome === "failed",
      );
  const unsigned = {
    schemaVersion: "node-result.v1" as const,
    ...resultIdentity(plan, node),
    mode: node.mode,
    state,
    outcome,
    attemptIds: attempts.map((attempt) => attempt.attemptId),
    finalAttemptId: finalAttempt?.attemptId ?? null,
    unstable,
    skipReason,
  };
  const resultDigest = digest(unsigned);
  const result: NodeResultV1 = {
    ...unsigned,
    resultDigest,
    receipt: receipt(authorityId, nonce, resultDigest),
  };
  validatePipelineTestGateContract("nodeResult", result);
  return freeze(result);
}

function invocationInputs(
  plan: ResolvedTestPlanV1,
  node: ResolvedPlanNodeV1,
  outputs: ReadonlyMap<string, readonly ProducedOutputV1[]>,
): ResolvedInputV1[] {
  return plan.links
    .filter((link) => link.to.nodeId === node.id)
    .sort((a, b) => compareText(a.to.input, b.to.input))
    .map((link) => {
      const output = outputs
        .get(link.from.nodeId)
        ?.find((item) => item.name === link.from.output);
      if (!output)
        throw new Error(
          `TEST_PLAN_LINK_OUTPUT_MISSING:${link.from.nodeId}:${link.from.output}`,
        );
      if (link.kind === "value" && output.kind === "value")
        return {
          name: link.to.input,
          kind: "value",
          schemaId: link.schemaId,
          value: structuredClone(output.value),
        };
      if (link.kind === "artifact" && output.kind === "artifact")
        return {
          name: link.to.input,
          kind: "artifact",
          artifact: output.artifact,
        };
      throw new Error(
        `TEST_PLAN_LINK_OUTPUT_MISMATCH:${link.from.nodeId}:${link.from.output}`,
      );
    });
}

export function validateAndMapOutputs(
  entry: TestProviderRegistryEntry,
  result: ProviderResultV1,
  artifacts: ReadonlyMap<string, EvidenceRefV1>,
): ProducedOutputV1[] {
  const outputs: ProducedOutputV1[] = [];
  const seen = new Set<string>();
  for (const output of result.outputs) {
    if (seen.has(output.name))
      throw new Error(`TEST_PROVIDER_OUTPUT_DUPLICATE:${output.name}`);
    seen.add(output.name);
    const declaration = entry.registration.outputs.find(
      (item) => item.name === output.name,
    );
    if (!declaration || declaration.kind !== output.kind)
      throw new Error(`TEST_PROVIDER_OUTPUT_INVALID:${output.name}`);
    if (output.kind === "value" && declaration.kind === "value") {
      if (output.schemaId !== declaration.schemaId)
        throw new Error(`TEST_PROVIDER_OUTPUT_SCHEMA_INVALID:${output.name}`);
      outputs.push({
        name: output.name,
        kind: "value",
        schemaId: output.schemaId,
        value: structuredClone(output.value),
      });
    } else if (output.kind === "artifact" && declaration.kind === "artifact") {
      const evidence = artifacts.get(output.evidenceId);
      if (
        !evidence ||
        !declaration.mediaTypes.includes(evidence.artifact.mediaType)
      )
        throw new Error(`TEST_PROVIDER_OUTPUT_ARTIFACT_INVALID:${output.name}`);
      outputs.push({
        name: output.name,
        kind: "artifact",
        artifact: evidence.artifact,
      });
    }
  }
  for (const declaration of entry.registration.outputs) {
    if (result.outcome === "passed" && declaration.required && !seen.has(declaration.name))
      throw new Error(`TEST_PROVIDER_OUTPUT_REQUIRED:${declaration.name}`);
  }
  return outputs;
}

function busterWorkerSummary(value: string): string {
  const mapped: Record<string, string> = {
    WORKER_ATTEMPT_CANCELLED: "TEST_PROVIDER_CANCELLED",
    WORKER_ATTEMPT_TIMEOUT: "TEST_PROVIDER_TIMEOUT",
    WORKER_CPU_LIMIT: "TEST_PROVIDER_CPU_LIMIT",
    WORKER_LOG_LIMIT: "TEST_PROVIDER_LOG_LIMIT",
    WORKER_MEMORY_LIMIT: "TEST_PROVIDER_MEMORY_LIMIT",
    WORKER_PROCESS_LIMIT: "TEST_PROVIDER_PROCESS_LIMIT",
  };
  return mapped[value] ?? value;
}

function grantedCapabilities(
  options: {
    readonly registry: RegistrySnapshot;
    readonly grants: ReadonlyMap<string, readonly string[]> | undefined;
  },
  node: ResolvedPlanNodeV1,
): string[] {
  const entry = providerEntry(options.registry, node);
  const registrationId = `${entry.registration.package.packageId}:${entry.registration.registrationId}`;
  const configured = new Set(options.grants?.get(node.id) ?? options.grants?.get(registrationId) ?? []);
  return entry.registration.capabilities
    .filter((capability) => configured.has(capability))
    .sort();
}

function createBusterWorkerProfile(
  registry: RegistrySnapshot,
  granted: readonly string[],
): WorkerProfileV1 {
  const capabilities = [...new Set(["provider.execute", ...granted])].sort();
  const capabilityKey = crypto.createHash('sha256').update(capabilities.join('\0')).digest('hex').slice(0, 16);
  const base = {
    schemaVersion: "worker-profile.v1" as const,
    profileId: `buster.local.${capabilityKey}`,
    workerType: "buster",
    coreContractId: "kubeclaw.worker-core@1",
    engine: {
      engineId: "buster-test-engine",
      contractId: "kubeclaw.buster-engine@1",
      engineVersion: "1.0.0",
      contentDigest: registry.snapshotDigest,
    },
    capabilities,
  };
  return { ...base, profileDigest: workerProfileDigest(base) };
}

export function createBusterWorkerProfiles(
  plan: ResolvedTestPlanV1,
  registry: RegistrySnapshot,
  grants?: ReadonlyMap<string, readonly string[]>,
): WorkerProfileV1[] {
  const profiles = new Map<string, WorkerProfileV1>();
  for (const node of plan.nodes) {
    const granted = grantedCapabilities({ registry, grants }, node);
    const profile = createBusterWorkerProfile(registry, granted);
    profiles.set(profile.profileDigest, profile);
  }
  return [...profiles.values()].sort((left, right) =>
    compareText(left.profileDigest, right.profileDigest),
  );
}

export class TestPlanRunner {
  readonly #options: TestPlanRunnerOptions;
  readonly #loader: TestProviderLoader;
  readonly #store: EvidenceStore;
  readonly #now: () => Date;
  readonly #id: () => string;
  readonly #workspaceRoot: string;
  readonly #repositoryRelative: string;
  readonly #authorityId: string;
  readonly #workerRuntime: WorkerAttemptRuntime;
  readonly #durableAttemptStore: FileDurableAttemptStore;
  readonly #observabilityAdmissionStore: FileObservabilityAdmissionStore;
  readonly #reportAdapterRuntime: ReportAdapterExecutor;
  readonly #customDurableAttemptStore: boolean;
  readonly #cleanupErrors: { nodeId: string; message: string }[] = [];
  readonly #retainedFixtures: Array<{
    node: ResolvedPlanNodeV1;
    execution: AttemptExecution;
  }> = [];

  constructor(options: TestPlanRunnerOptions) {
    assertPlanIdentity(options.plan, options.registry);
    if (
      !Number.isSafeInteger(options.maximumConcurrency) ||
      options.maximumConcurrency < 1
    )
      throw new Error("TEST_RUNNER_CONCURRENCY_INVALID");
    if (
      options.cleanupTimeoutMs !== undefined &&
      (!Number.isSafeInteger(options.cleanupTimeoutMs) ||
        options.cleanupTimeoutMs < 1 ||
        options.cleanupTimeoutMs > MAX_TIMER_MS)
    ) {
      throw new Error("TEST_RUNNER_CLEANUP_TIMEOUT_INVALID");
    }
    if (
      options.maximumProviderResultBytes !== undefined &&
      (!Number.isSafeInteger(options.maximumProviderResultBytes) ||
        options.maximumProviderResultBytes < 1 ||
        options.maximumProviderResultBytes >
          Number.MAX_SAFE_INTEGER - WORKER_RESULT_WRAPPER_BYTES)
    ) {
      throw new Error("TEST_RUNNER_RESULT_LIMIT_INVALID");
    }
    if (
      !path.isAbsolute(options.workspaceRoot) ||
      !path.isAbsolute(options.repositoryRoot) ||
      !path.isAbsolute(options.artifactRoot) ||
      !path.isAbsolute(options.observabilityRoot)
    ) {
      throw new Error("TEST_RUNNER_PATH_NOT_ABSOLUTE");
    }
    fs.mkdirSync(options.workspaceRoot, { recursive: true });
    this.#workspaceRoot = fs.realpathSync(options.workspaceRoot);
    fs.mkdirSync(options.artifactRoot, { recursive: true });
    const artifactRoot = fs.realpathSync(options.artifactRoot);
    if (
      artifactRoot === this.#workspaceRoot ||
      artifactRoot.startsWith(`${this.#workspaceRoot}${path.sep}`) ||
      this.#workspaceRoot.startsWith(`${artifactRoot}${path.sep}`)
    ) {
      throw new Error("TEST_RUNNER_ARTIFACT_ROOT_OVERLAPS_WORKSPACE");
    }
    const observabilityRoot = secureDirectory(
      options.observabilityRoot,
      "TEST_RUNNER_OBSERVABILITY_ROOT",
    );
    if (
      observabilityRoot === this.#workspaceRoot ||
      observabilityRoot.startsWith(`${this.#workspaceRoot}${path.sep}`) ||
      this.#workspaceRoot.startsWith(`${observabilityRoot}${path.sep}`)
    )
      throw new Error("TEST_RUNNER_OBSERVABILITY_ROOT_OVERLAPS_WORKSPACE");
    if (options.durableAttemptStore)
      secureDirectory(
        options.durableAttemptStore.storageDirectory(),
        "TEST_RUNNER_ATTEMPT_STORE_ROOT",
      );
    if (options.observabilityAdmissionStore)
      secureDirectory(
        options.observabilityAdmissionStore.storageDirectory(),
        "TEST_RUNNER_ADMISSION_STORE_ROOT",
      );
    if (
      options.durableAttemptStore &&
      fs.realpathSync(options.durableAttemptStore.storageDirectory()) !==
        path.join(observabilityRoot, "attempts")
    )
      throw new Error("TEST_RUNNER_ATTEMPT_STORE_ROOT_MISMATCH");
    if (
      options.observabilityAdmissionStore &&
      fs.realpathSync(
        options.observabilityAdmissionStore.storageDirectory(),
      ) !== path.join(observabilityRoot, "admission")
    )
      throw new Error("TEST_RUNNER_ADMISSION_STORE_ROOT_MISMATCH");
    this.#repositoryRelative = containedRelative(
      this.#workspaceRoot,
      options.repositoryRoot,
      "TEST_RUNNER_REPOSITORY",
    );
    this.#options = { ...options, artifactRoot, observabilityRoot };
    this.#loader = options.loader ?? new RegisteredTestProviderLoader();
    this.#store = options.evidenceStore ?? new FileEvidenceStore(artifactRoot);
    this.#reportAdapterRuntime = options.reportAdapterRuntime ?? new RegisteredReportAdapterRuntime(
      new FileReportArtifactReader([artifactRoot]), path.join(observabilityRoot, 'report-adapters'));
    this.#customDurableAttemptStore = options.durableAttemptStore !== undefined;
    this.#durableAttemptStore =
      options.durableAttemptStore ??
      new FileDurableAttemptStore(path.join(observabilityRoot, "attempts"), {
        maximumEvidenceObjects: 10000,
        maximumEvidenceBytes: 10 * 1024 * 1024 * 1024,
        maximumEvidenceObjectBytes: 1024 * 1024 * 1024,
        maximumResults: 10000,
        maximumClosures: 10000,
        maximumMetadataBytes: 256 * 1024 * 1024,
        maximumPendingEvidenceAgeMs: 60 * 60 * 1000,
      });
    this.#observabilityAdmissionStore =
      options.observabilityAdmissionStore ??
      new FileObservabilityAdmissionStore(
        path.join(observabilityRoot, "admission"),
        {
          maximumIngressBytes: 16 * 1024 * 1024,
          maximumRecords: 10000,
          maximumBytes: 256 * 1024 * 1024,
          maximumQuarantineRecords: 1000,
          maximumQuarantineBytes: 64 * 1024 * 1024,
        },
      );
    this.#now = options.now ?? (() => new Date());
    this.#id = options.id ?? (() => crypto.randomUUID());
    this.#authorityId = `test-runner:${options.plan.planDigest}`;
    if (options.workerRuntime) {
      this.#workerRuntime = options.workerRuntime;
    } else {
      const runtime = new LocalWorkerRuntime({
        workerId: "worker:buster:local",
        workerType: "buster",
        coreVersion: "1.0.0",
        protocolVersions: ["worker-protocol.v1"],
        profiles: createBusterWorkerProfiles(
          options.plan,
          options.registry,
          options.grants,
        ),
        capacity: options.maximumConcurrency,
        now: this.#now,
      });
      runtime.markReady();
      this.#workerRuntime = runtime;
    }
  }

  async run(): Promise<TestPlanRunResult> {
    let recoveredCompletions = 0;
    if (
      this.#customDurableAttemptStore ||
      fs.existsSync(
        path.join(
          this.#options.observabilityRoot,
          "attempts",
          "attempt-store.json",
        ),
      )
    )
      recoveredCompletions = await this.#resumePendingCompletions();
    if (recoveredCompletions > 0)
      throw new Error(
        `TEST_RUNNER_RECOVERY_OWNED_BY_NOVA:${recoveredCompletions}`,
      );
    const attempts: AttemptResultV1[] = [];
    const results = new Map<string, NodeResultV1>();
    const outputs = new Map<string, readonly ProducedOutputV1[]>();
    const running = new Map<string, Promise<NodeExecution>>();
    const groupUse = new Map<string, number>();
    const pending = new Map(
      this.#options.plan.nodes.map((node) => [node.id, node]),
    );
    try {
      while (pending.size > 0 || running.size > 0) {
        let progressed = false;
        for (const node of [...pending.values()].sort((a, b) =>
          compareText(a.id, b.id),
        )) {
          if (node.skipReason !== null) {
            const result = finalNodeResult(
              this.#options.plan,
              node,
              [],
              "skipped",
              "skipped",
              node.skipReason,
              this.#authorityId,
              this.#id(),
            );
            results.set(node.id, result);
            pending.delete(node.id);
            progressed = true;
            continue;
          }
          if (this.#options.signal?.aborted) {
            const result = finalNodeResult(
              this.#options.plan,
              node,
              [],
              "cancelled",
              null,
              null,
              this.#authorityId,
              this.#id(),
            );
            results.set(node.id, result);
            pending.delete(node.id);
            progressed = true;
            continue;
          }
          if (
            !node.dependencies.every((dependency) =>
              results.has(dependency.nodeId),
            )
          )
            continue;
          const rejected = node.dependencies.find(
            (dependency) =>
              !dependency.acceptedResults.includes(
                terminalResult(results.get(dependency.nodeId)!) as never,
              ),
          );
          if (rejected) {
            const reason = `dependency ${rejected.nodeId} returned ${terminalResult(results.get(rejected.nodeId)!)}`;
            const result = finalNodeResult(
              this.#options.plan,
              node,
              [],
              "skipped",
              "skipped",
              reason,
              this.#authorityId,
              this.#id(),
            );
            results.set(node.id, result);
            pending.delete(node.id);
            progressed = true;
            continue;
          }
          if (running.size >= this.#options.maximumConcurrency) continue;
          if (node.concurrencyGroup !== null) {
            const limit =
              this.#options.plan.concurrencyLimits[node.concurrencyGroup];
            if (limit === undefined)
              throw new Error(
                `TEST_RUNNER_CONCURRENCY_GROUP_MISSING:${node.concurrencyGroup}`,
              );
            if ((groupUse.get(node.concurrencyGroup) ?? 0) >= limit) continue;
            groupUse.set(
              node.concurrencyGroup,
              (groupUse.get(node.concurrencyGroup) ?? 0) + 1,
            );
          }
          pending.delete(node.id);
          const task = this.#executeNode(node, outputs).finally(() => {
            if (node.concurrencyGroup !== null)
              groupUse.set(
                node.concurrencyGroup,
                (groupUse.get(node.concurrencyGroup) ?? 1) - 1,
              );
          });
          running.set(node.id, task);
          progressed = true;
        }
        if (running.size > 0) {
          const completed = await Promise.race(
            [...running.entries()].map(async ([id, task]) => ({
              id,
              execution: await task,
            })),
          );
          running.delete(completed.id);
          results.set(completed.id, completed.execution.result);
          attempts.push(...completed.execution.attempts);
          outputs.set(completed.id, completed.execution.outputs);
          if (completed.execution.retainedFixture)
            this.#retainedFixtures.push({
              node: this.#options.plan.nodes.find(
                (item) => item.id === completed.id,
              )!,
              execution: completed.execution.retainedFixture,
            });
          progressed = true;
        }
        if (!progressed) throw new Error("TEST_RUNNER_DEADLOCK");
      }
    } finally {
      await this.#cleanupFixtures();
    }
    for (const failure of this.#cleanupErrors) {
      const node = this.#options.plan.nodes.find(
        (item) => item.id === failure.nodeId,
      );
      if (!node) continue;
      const current = results.get(node.id);
      if (
        !current ||
        current.state === "skipped" ||
        current.state === "cancelled"
      )
        continue;
      results.set(
        node.id,
        finalNodeResult(
          this.#options.plan,
          node,
          attempts.filter((attempt) => attempt.nodeId === node.id),
          "errored",
          null,
          null,
          this.#authorityId,
          this.#id(),
        ),
      );
    }
    return freeze({
      planId: this.#options.plan.planId,
      runId: this.#options.plan.runId,
      attempts: attempts.sort((a, b) => compareText(a.attemptId, b.attemptId)),
      nodes: [...results.values()].sort((a, b) =>
        compareText(a.nodeId, b.nodeId),
      ),
      cleanupErrors: [...this.#cleanupErrors],
    });
  }

  async #resumePendingCompletions(): Promise<number> {
    const snapshot = await this.#durableAttemptStore.snapshot();
    const closed = new Set(
      snapshot.closures.map(
        (item) => `${item.pipelineRunId}\0${item.closureId}`,
      ),
    );
    const current = snapshot.results.filter(
      (stored) =>
        stored.pipelineRunId === this.#options.plan.runId &&
        stored.planId === this.#options.plan.planId,
    );
    const newestGeneration = new Map<string, number>();
    for (const stored of current)
      newestGeneration.set(
        stored.attemptId,
        Math.max(
          newestGeneration.get(stored.attemptId) ?? 0,
          stored.claimGeneration,
        ),
      );
    let recovered = 0;
    for (const stored of current) {
      if (
        stored.claimGeneration <
        (newestGeneration.get(stored.attemptId) ?? 0)
      )
        continue;
      recovered += 1;
      if (
        !stored.completionIntent ||
        closed.has(
          `${stored.pipelineRunId}\0${stored.completionIntent.closure.closureId}`,
        )
      )
        continue;
      if (typeof stored.storedAt !== "string") continue;
      await this.#durableAttemptStore.resumeCompletion(
        stored.pipelineRunId,
        stored.attemptId,
        stored.claimGeneration,
        this.#observabilityAdmissionStore,
      );
    }
    return recovered;
  }

  async #readManagedEvidence(
    storageUrl: string,
    maximumBytes: number,
  ): Promise<Buffer> {
    const source = new URL(storageUrl);
    if (source.protocol !== "file:")
      throw new Error(
        `OBSERVABILITY_EVIDENCE_STORAGE_UNSUPPORTED:${source.protocol}`,
      );
    const candidate = fs.realpathSync(source);
    const root = this.#options.artifactRoot;
    if (candidate !== root && !candidate.startsWith(`${root}${path.sep}`))
      throw new Error("OBSERVABILITY_EVIDENCE_PATH_FORBIDDEN");
    const handle = await fs.promises.open(
      candidate,
      fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK,
    );
    try {
      const opened = await handle.stat();
      const currentPath = fs.realpathSync(candidate);
      if (currentPath !== root && !currentPath.startsWith(`${root}${path.sep}`))
        throw new Error("OBSERVABILITY_EVIDENCE_PATH_FORBIDDEN");
      const current = fs.statSync(currentPath);
      if (
        !opened.isFile() ||
        opened.dev !== current.dev ||
        opened.ino !== current.ino
      )
        throw new Error("OBSERVABILITY_EVIDENCE_PATH_FORBIDDEN");
      if (opened.size > maximumBytes)
        throw new Error("OBSERVABILITY_EVIDENCE_OBJECT_TOO_LARGE");
      const content = await handle.readFile();
      if (content.byteLength > maximumBytes)
        throw new Error("OBSERVABILITY_EVIDENCE_OBJECT_TOO_LARGE");
      return content;
    } finally {
      await handle.close();
    }
  }

  async #executeNode(
    node: ResolvedPlanNodeV1,
    outputs: ReadonlyMap<string, readonly ProducedOutputV1[]>,
  ): Promise<NodeExecution> {
    const attempts: AttemptResultV1[] = [];
    let finalExecution: AttemptExecution | null = null;
    let cleanupFailed = false;
    const maximumAttempts = node.retryCount + 1;
    for (
      let attemptNumber = 1;
      attemptNumber <= maximumAttempts;
      attemptNumber += 1
    ) {
      const execution = await this.#executeAttempt(
        node,
        attemptNumber,
        outputs,
      );
      attempts.push(execution.result);
      finalExecution = execution;
      const retry =
        execution.result.executionState !== "cancelled" &&
        !this.#options.signal?.aborted &&
        (execution.result.executionState !== "completed" ||
          execution.result.outcome === "failed") &&
        attemptNumber < maximumAttempts;
      cleanupFailed = execution.cleanupFailed;
      if (cleanupFailed || !retry) break;
    }
    if (!finalExecution)
      throw new Error(`TEST_RUNNER_ATTEMPT_MISSING:${node.id}`);
    const final = finalExecution.result;
    const state = cleanupFailed ? "errored" : final.executionState;
    const result = finalNodeResult(
      this.#options.plan,
      node,
      attempts,
      state,
      cleanupFailed ? null : final.outcome,
      null,
      this.#authorityId,
      this.#id(),
    );
    return {
      result,
      attempts,
      outputs: final.outputs,
      retainedFixture:
        !cleanupFailed &&
        node.kind === "fixture" &&
        state === "completed" &&
        final.outcome === "passed"
          ? finalExecution
          : null,
    };
  }

  async #executeAttempt(
    node: ResolvedPlanNodeV1,
    attemptNumber: number,
    outputs: ReadonlyMap<string, readonly ProducedOutputV1[]>,
  ): Promise<AttemptExecution> {
    const attemptId = `attempt:${crypto.createHash("sha256").update(`${node.executionId}:${attemptNumber}:${this.#id()}`).digest("hex")}`;
    const attemptDirectory = path.join(
      this.#workspaceRoot,
      "test-attempts",
      attemptId.slice("attempt:".length),
    );
    const scratchDirectory = path.join(attemptDirectory, "scratch");
    const attemptRepository = path.join(attemptDirectory, "repository");
    const evidenceDirectory = path.join(attemptDirectory, "evidence");
    const stagingRoot = path.join(this.#options.artifactRoot, ".staging");
    fs.mkdirSync(stagingRoot, { recursive: true });
    const stagingBase = fs.mkdtempSync(
      path.join(stagingRoot, `${attemptId.slice("attempt:".length)}-`),
    );
    const stagedEvidenceDirectory = path.join(stagingBase, "selected");
    const stagedErrorEvidenceDirectory = path.join(stagingBase, "error");
    const runnerEvidenceDirectory = path.join(
      attemptDirectory,
      "runner-evidence",
    );
    fs.mkdirSync(scratchDirectory, { recursive: true });
    fs.mkdirSync(evidenceDirectory, { recursive: true });
    fs.mkdirSync(runnerEvidenceDirectory, { recursive: true });
    fs.cpSync(this.#options.repositoryRoot, attemptRepository, {
      recursive: true,
      errorOnExist: true,
      force: false,
      verbatimSymlinks: true,
    });
    const attemptRepositoryRelative = containedRelative(
      this.#workspaceRoot,
      attemptRepository,
      "TEST_RUNNER_ATTEMPT_REPOSITORY",
    );
    const entry = providerEntry(this.#options.registry, node);
    const granted = grantedCapabilities(
      { registry: this.#options.registry, grants: this.#options.grants },
      node,
    );
    const missingCapability = entry.registration.capabilities.find(
      (capability) => !granted.includes(capability),
    );
    let resolvedInputs: ResolvedInputV1[] = [];
    let preparationFault: RunnerFault | null = null;
    try {
      resolvedInputs = invocationInputs(this.#options.plan, node, outputs);
    } catch (error) {
      preparationFault = new RunnerFault("errored", detail(error));
    }
    const invocation: ProviderInvocationV1 = {
      schemaVersion: "provider-invocation.v1",
      ...resultIdentity(this.#options.plan, node),
      attemptId,
      attemptNumber,
      provider: node.provider,
      configuration: node.configuration,
      inputs: resolvedInputs,
      evidence: node.evidence,
      grantedCapabilities: granted,
      timeoutMs: node.timeoutMs,
      limits: node.limits,
      workspace: {
        repository: attemptRepositoryRelative,
        scratch: path
          .relative(this.#workspaceRoot, scratchDirectory)
          .split(path.sep)
          .join("/"),
        evidence: path
          .relative(this.#workspaceRoot, evidenceDirectory)
          .split(path.sep)
          .join("/"),
      },
    };
    validatePipelineTestGateContract("providerInvocation", invocation);
    let instance: LoadedTestProvider | null = null;
    let providerResult: ProviderResultV1 | null = null;
    let producedOutputs: ProducedOutputV1[] = [];
    let retainFixture = false;
    let stagedFiles: DeclaredEvidenceV1[] = [];
    let stagedErrorFiles: DeclaredEvidenceV1[] = [];
    let stagingWork: Promise<void> | null = null;
    let loadWork: Promise<LoadedTestProvider> | null = null;
    let executionStarted = false;
    let fixtureInitializationStarted = false;
    let evidenceFault: string | null = null;
    const providerResultLimit =
      this.#options.maximumProviderResultBytes ?? MAX_PROVIDER_RESULT_BYTES;
    const busterLog = createLogCapture(node.limits.logBytes);
    const retainAnyLog =
      entry.registration.evidenceTypes.includes("log") &&
      [
        ...node.evidence.onPass,
        ...node.evidence.onFail,
        ...node.evidence.onError,
      ].includes("log");
    const cleanupTimeoutMs = this.#options.cleanupTimeoutMs ?? 30_000;
    const operation: WorkerAttemptOperation = {
      prepare: () => {
        if (preparationFault) throw preparationFault;
        if (missingCapability)
          throw new Error(
            `TEST_PROVIDER_CAPABILITY_DENIED:${missingCapability}`,
          );
        return undefined;
      },
      execute: async (workerContext): Promise<WorkerAttemptOperationResult> => {
        const context = this.#context(
          workerContext.signal,
          (stream, value) => {
            busterLog.contextLog(stream, value);
            workerContext.log(stream, value);
          },
          new Set(granted),
          invocation.inputs,
        );
        loadWork = this.#loader.load(
          entry,
          invocation,
          this.#workspaceRoot,
          workerContext.signal,
        );
        instance = await loadWork;
        if (workerContext.signal.aborted)
          throw (
            workerContext.signal.reason ?? new Error("TEST_PROVIDER_CANCELLED")
          );
        if (node.kind === "fixture") {
          fixtureInitializationStarted = true;
          const supportsCleanup = await instance.supportsCleanup(context);
          if (workerContext.signal.aborted)
            throw (
              workerContext.signal.reason ??
              new Error("TEST_PROVIDER_CANCELLED")
            );
          if (!supportsCleanup)
            throw new Error("TEST_PROVIDER_FIXTURE_CLEANUP_REQUIRED");
        }
        if (workerContext.signal.aborted)
          throw (
            workerContext.signal.reason ?? new Error("TEST_PROVIDER_CANCELLED")
          );
        executionStarted = true;
        providerResult = await instance.execute(invocation, context);
        const encoded = JSON.stringify(providerResult);
        if (Buffer.byteLength(encoded) > providerResultLimit)
          throw new Error("TEST_PROVIDER_RESULT_LIMIT");
        validatePipelineTestGateContract("providerResult", providerResult);
        validateCounts(providerResult);
        validateProviderDetails(entry, providerResult);
        validateEvidenceDeclarations(entry, providerResult.evidenceFiles);
        validateProviderReports(entry, providerResult);
        providerResult = freeze(structuredClone(providerResult));
        const stagedTypes = selectedEvidenceTypes(
          node,
          "completed",
          providerResult.outcome,
        );
        for (const output of providerResult.outputs)
          if (output.kind === "artifact") {
            const declaration = providerResult.evidenceFiles.find(
              (item) => item.evidenceId === output.evidenceId,
            );
            if (!declaration)
              throw new Error(
                `TEST_PROVIDER_OUTPUT_EVIDENCE_MISSING:${output.evidenceId}`,
              );
            stagedTypes.add(declaration.type);
          }
        for (const report of providerResult.reports) stagedTypes.add(
          providerResult.evidenceFiles.find((item) => item.evidenceId === report.evidenceId)!.type,
        );
        stagingWork = (async () => {
          const errorCandidates = providerResult!.evidenceFiles.filter((item) =>
            node.evidence.onError.includes(item.type),
          );
          try {
            await stageEvidenceFiles(
              evidenceDirectory,
              stagedErrorEvidenceDirectory,
              errorCandidates,
              node.limits.artifactFiles,
              node.limits.artifactBytes,
              workerContext.signal,
            );
            stagedErrorFiles = errorCandidates;
          } catch (error) {
            await fs.promises.rm(stagedErrorEvidenceDirectory, {
              recursive: true,
              force: true,
            });
            stagedErrorFiles = [];
            if (workerContext.signal.aborted) throw error;
          }
          stagedFiles = providerResult!.evidenceFiles.filter((item) =>
            stagedTypes.has(item.type),
          );
          await stageEvidenceFiles(
            evidenceDirectory,
            stagedEvidenceDirectory,
            stagedFiles,
            node.limits.artifactFiles,
            node.limits.artifactBytes,
            workerContext.signal,
          );
        })();
        await stagingWork;
        retainFixture =
          node.kind === "fixture" && providerResult.outcome === "passed";
        return {
          summary: providerResult.summary,
          specialistResult: {
            schemaId: "kubeclaw.buster-provider-result.v1",
            schemaDigest: sha256Digest({
              schemaId: "kubeclaw.buster-provider-result.v1",
            }),
            values: {
              providerResult: structuredClone(providerResult),
            } as never,
          },
          evidence: [],
          exitCode: providerResult.exitCode,
          signal: providerResult.signal,
        };
      },
      terminate: async () => {
        const loaded = instance ?? (await loadWork?.catch(() => null));
        await loaded?.terminate();
        await stagingWork?.catch(() => undefined);
      },
      measure: async () => {
        const measured = instance?.resources() ?? {
          cpuTimeMs: 0,
          maximumMemoryBytes: 0,
          maximumProcesses: 0,
        };
        return {
          cpuTimeMs: Math.ceil(measured.cpuTimeMs ?? 0),
          maximumMemoryBytes: Math.ceil(measured.maximumMemoryBytes ?? 0),
          maximumProcesses: Math.ceil(measured.maximumProcesses ?? 0),
        };
      },
      cleanup: async (workerContext) => {
        if (!executionStarted && !fixtureInitializationStarted) {
          await instance?.discard?.();
          return;
        }
        if (!instance?.cleanup || retainFixture)
          return;
        await instance.cleanup(
          invocation,
          this.#context(
            workerContext.signal,
            (stream, value) => {
              busterLog.contextLog(stream, value);
              workerContext.log(stream, value);
            },
            new Set(granted),
            invocation.inputs,
          ),
        );
      },
      collectEvidence: async ({ state, signal }) => {
        signal.throwIfAborted();
        const workerExecutionState: ExecutionState =
          state === "interrupted" ? "errored" : state;
        const workerOutcome: TestOutcome =
          workerExecutionState === "completed" && providerResult
            ? providerResult.outcome
            : null;
        const selected = selectedEvidenceTypes(
          node,
          workerExecutionState,
          workerOutcome,
        );
        let evidence: EvidenceRefV1[] = [];
        try {
          if (workerExecutionState === "completed" && providerResult) {
            for (const output of providerResult.outputs)
              if (output.kind === "artifact") {
                const declaration = providerResult.evidenceFiles.find(
                  (item) => item.evidenceId === output.evidenceId,
                );
                if (!declaration)
                  throw new Error(
                    `TEST_PROVIDER_OUTPUT_EVIDENCE_MISSING:${output.evidenceId}`,
                  );
                selected.add(declaration.type);
              }
            for (const report of providerResult.reports) selected.add(
              providerResult.evidenceFiles.find((item) => item.evidenceId === report.evidenceId)!.type,
            );
          }
          const useErrorStaging = workerExecutionState !== "completed";
          const selectedFiles = (
            useErrorStaging ? stagedErrorFiles : stagedFiles
          ).filter((item) => selected.has(item.type));
          evidence = await this.#collectEvidence(
            entry,
            attemptId,
            useErrorStaging
              ? stagedErrorEvidenceDirectory
              : stagedEvidenceDirectory,
            selectedFiles,
            node.limits.artifactFiles,
            node.limits.artifactBytes,
            signal,
          );
          if (workerExecutionState === "completed" && providerResult) {
            producedOutputs = validateAndMapOutputs(
              entry,
              providerResult,
              new Map(evidence.map((item) => [item.evidenceId, item])),
            );
          }
          const logEvidence =
            retainAnyLog && selected.has("log")
              ? busterLog.write(runnerEvidenceDirectory)
              : null;
          if (logEvidence) {
            const logRefs = await this.#collectEvidence(
              entry,
              attemptId,
              runnerEvidenceDirectory,
              [logEvidence],
              node.limits.artifactFiles - evidence.length,
              node.limits.artifactBytes -
                evidence.reduce(
                  (sum, item) => sum + item.artifact.sizeBytes,
                  0,
                ),
              signal,
            );
            evidence.push(...logRefs);
          }
        } catch (error) {
          signal.throwIfAborted();
          evidenceFault = detail(error);
          producedOutputs = [];
          evidence = [];
          if (stagedErrorFiles.length > 0) {
            try {
              evidence = await this.#collectEvidence(
                entry,
                attemptId,
                stagedErrorEvidenceDirectory,
                stagedErrorFiles,
                node.limits.artifactFiles,
                node.limits.artifactBytes,
                signal,
              );
            } catch {
              signal.throwIfAborted();
              evidence = [];
            }
          }
          if (retainAnyLog && node.evidence.onError.includes("log")) {
            try {
              const logEvidence = busterLog.write(runnerEvidenceDirectory);
              if (logEvidence) {
                const logRefs = await this.#collectEvidence(
                  entry,
                  attemptId,
                  runnerEvidenceDirectory,
                  [logEvidence],
                  node.limits.artifactFiles - evidence.length,
                  node.limits.artifactBytes -
                    evidence.reduce(
                      (sum, item) => sum + item.artifact.sizeBytes,
                      0,
                    ),
                  signal,
                );
                evidence.push(...logRefs);
              }
            } catch {
              signal.throwIfAborted();
              evidence = [];
            }
          }
        }
        return { evidence, ...(evidenceFault ? { error: evidenceFault } : {}) };
      },
      finalizeResult: async ({ evidence, specialistResult, signal }) => {
        if (node.provider.contractId === 'kubeclaw.direct-command@1'
          && node.configuration.values.resultMode === 'exit-code') return specialistResult;
        if (!providerResult || providerResult.reports.length === 0) return specialistResult;
        const evidenceById = new Map(evidence.map((item) => [item.evidenceId, item]));
        const reports: ReportAdapterResultV1[] = [];
        for (const declared of providerResult.reports) {
          const usedReportBytes = Buffer.byteLength(JSON.stringify(reports));
          const remainingReportBytes = MAX_REPORT_RESULTS_BYTES - usedReportBytes;
          if (remainingReportBytes < 1) throw new Error('TEST_REPORT_RESULT_LIMIT');
          const source = evidenceById.get(declared.evidenceId);
          if (!source) throw new Error(`TEST_PROVIDER_REPORT_NOT_RETAINED:${declared.evidenceId}`);
          const reference = node.reportAdapters.find((item) => item.format === declared.format);
          if (!reference) throw new Error(`TEST_REPORT_ADAPTER_NOT_RESOLVED:${declared.format}`);
          const adapter = reportAdapterEntry(this.#options.registry, reference);
          const maximumSourceBytes = Math.max(1, Math.min(64 * 1024 * 1024, source.artifact.sizeBytes));
          const adapterTimeoutMs = Math.min(5 * 60 * 1_000, cleanupTimeoutMs);
          reports.push(await this.#reportAdapterRuntime.adapt(adapter, source.artifact, {
            maximumCases: 5_000,
            maximumFindings: 5_000,
            maximumCaseFindings: 100,
            maximumSourceBytes,
            maximumResultBytes: remainingReportBytes,
            timeoutMs: adapterTimeoutMs,
            memoryBytes: 512 * 1024 * 1024,
            cpuMillis: Math.max(1_000, Math.floor(adapterTimeoutMs / 1_000) * 1_000),
            openFiles: 64,
          }, signal));
          if (Buffer.byteLength(JSON.stringify(reports)) > MAX_REPORT_RESULTS_BYTES) {
            throw new Error('TEST_REPORT_RESULT_LIMIT');
          }
        }
        const providerValue = specialistResult.values.providerResult as unknown as ProviderResultV1;
        if (node.provider.contractId !== 'kubeclaw.direct-command@1') {
          return {
            ...specialistResult,
            values: { ...specialistResult.values, reports: structuredClone(reports) } as never,
          };
        }
        const finalizedProvider = finalizeDirectCommandReports(providerValue, reports,
          node.mode === 'blocking' && node.configuration.values.resultMode === 'junit-required');
        validateCounts(finalizedProvider);
        return {
          ...specialistResult,
          values: { ...specialistResult.values, providerResult: finalizedProvider,
            reports: structuredClone(reports) } as never,
        };
      },
    };
    const issuedAt = this.#now();
    const profile = createBusterWorkerProfile(this.#options.registry, granted);
    const completionPhases = 3 + Number(Boolean(operation.cleanup)) + Number(Boolean(operation.collectEvidence)) + Number(Boolean(operation.finalizeResult));
    const claimWindowMs = node.timeoutMs + completionPhases * cleanupTimeoutMs + 60_000;
    const envelopeBase = {
      schemaVersion: "worker-attempt-envelope.v1" as const,
      protocolVersion: "worker-protocol.v1" as const,
      pipelineRunId: this.#options.plan.runId,
      moduleId: this.#options.plan.scope.moduleId,
      gateId: this.#options.plan.scope.gateId,
      planId: this.#options.plan.planId,
      nodeId: node.id,
      executionId: node.executionId,
      attemptId,
      attemptNumber,
      claim: {
        schemaVersion: "attempt-claim.v1" as const,
        claimId: `claim:${attemptId}`,
        attemptId,
        generation: 1,
        workerId: "worker:buster:local",
        claimedAt: issuedAt.toISOString(),
        expiresAt: new Date(issuedAt.getTime() + claimWindowMs).toISOString(),
      },
      profile,
      packages: [
        {
          packageId: node.provider.packageId,
          packageVersion: node.provider.packageVersion,
          contentDigest: node.provider.contentDigest,
        },
      ],
      grantedCapabilities: granted,
      limits: {
        timeoutMs: node.timeoutMs,
        cleanupTimeoutMs,
        cpuMillis: node.limits.cpuMillis,
        memoryBytes: node.limits.memoryBytes,
        processes: node.limits.processes,
        logBytes: node.limits.logBytes,
        resultBytes: providerResultLimit + MAX_REPORT_RESULTS_BYTES + WORKER_RESULT_WRAPPER_BYTES,
        evidenceBytes: node.limits.artifactBytes,
        evidenceFiles: node.limits.artifactFiles,
      },
      inputs: [],
      operation: {
        contractId: "kubeclaw.buster-provider-attempt@1",
        inputSchemaId: "kubeclaw.buster-provider-attempt.v1",
        inputSchemaDigest: sha256Digest({
          schemaId: "kubeclaw.buster-provider-attempt.v1",
        }),
        values: { invocation: structuredClone(invocation) } as never,
      },
      cancellationId: `cancel:${attemptId}`,
      issuedAt: issuedAt.toISOString(),
      queueDeadline: new Date(issuedAt.getTime() + 60_000).toISOString(),
    };
    const workerEnvelope: WorkerAttemptEnvelopeV1 = {
      ...envelopeBase,
      attemptSpecDigest: workerAttemptSpecDigest({
        ...envelopeBase,
        attemptSpecDigest: "",
      }),
    };
    let workerResult: WorkerAttemptResultV1 | null = null;
    let completedWorkerResult: WorkerAttemptResultV1 | null = null;
    let workerRuntimeFault: string | null = null;
    try {
      workerResult = await this.#workerRuntime.runAttempt(
        workerEnvelope,
        async (workerSignal) => {
          const signals = [
            workerSignal,
            ...(this.#options.signal ? [this.#options.signal] : []),
          ];
          const signal =
            signals.length === 1 ? workerSignal : AbortSignal.any(signals);
          completedWorkerResult = await new WorkerAttemptExecutor({
            envelope: workerEnvelope,
            operation,
            signal,
            retainLogs: false,
            now: this.#now,
            id: this.#id,
            receiptNamespace: this.#authorityId,
          }).execute();
          return completedWorkerResult;
        },
      );
      if (
        !workerResult ||
        !completedWorkerResult ||
        canonical(workerResult) !== canonical(completedWorkerResult)
      )
        throw new Error("WORKER_RUNTIME_RESULT_MISMATCH");
      workerResult = await this.#persistWorkerCompletion(
        workerEnvelope,
        workerResult,
      );
      completedWorkerResult = workerResult;
    } catch (error) {
      workerRuntimeFault = detail(error);
      workerResult = completedWorkerResult;
    } finally {
      await fs.promises.rm(stagingBase, { recursive: true, force: true });
    }
    const completedProviderResult = (workerResult?.specialistResult?.values?.providerResult
      ?? providerResult) as ProviderResultV1 | null;
    let retainedFaultCleanupFailed = false;
    if (
      retainFixture &&
      (workerRuntimeFault || workerResult?.state !== "completed") &&
      instance
    ) {
      retainedFaultCleanupFailed = !(await this.#cleanupProvider(
        node,
        instance,
        invocation,
        busterLog.contextLog,
      ));
      retainFixture = false;
    }
    const workerExecutionState: ExecutionState = workerRuntimeFault
      ? this.#options.signal?.aborted
        ? "cancelled"
        : "errored"
      : workerResult?.state === "interrupted"
        ? "errored"
        : (workerResult?.state ?? "errored");
    const workerOutcome: TestOutcome =
      workerExecutionState === "completed"
        ? completedProviderResult!.outcome
        : null;
    const evidence = (workerResult?.evidence ?? []) as EvidenceRefV1[];
    if (workerExecutionState === "completed" && completedProviderResult) {
      try {
        producedOutputs = validateAndMapOutputs(
          entry,
          completedProviderResult,
          new Map(evidence.map((item) => [item.evidenceId, item])),
        );
      } catch (error) {
        evidenceFault = detail(error);
        producedOutputs = [];
      }
    }
    const executionState: ExecutionState = evidenceFault
      ? "errored"
      : workerExecutionState;
    const outcome: TestOutcome =
      executionState === "completed" ? workerOutcome : null;
    const fallbackCompletedAt = this.#now();
    const resources: ResourceUseV1 = {
      ...(workerResult?.resources.cpuTimeMs !== undefined
        ? { cpuTimeMs: workerResult.resources.cpuTimeMs }
        : {}),
      ...(workerResult?.resources.maximumMemoryBytes !== undefined
        ? { maximumMemoryBytes: workerResult.resources.maximumMemoryBytes }
        : {}),
      logBytes: workerResult?.resources.logBytes ?? busterLog.bytes(),
      artifactBytes: evidence.reduce(
        (sum, item) => sum + item.artifact.sizeBytes,
        0,
      ),
    };
    const faulted = executionState !== "completed";
    const normalizedReports = !faulted && workerResult?.specialistResult?.values
      && Array.isArray(workerResult.specialistResult.values.reports)
      ? workerResult.specialistResult.values.reports as unknown as ReportAdapterResultV1[]
      : [];
    const unsigned = {
      schemaVersion: "attempt-result.v1" as const,
      ...resultIdentity(this.#options.plan, node),
      attemptId,
      attemptNumber,
      provider: node.provider,
      mode: node.mode,
      executionState,
      outcome,
      startedAt: workerResult?.startedAt ?? issuedAt.toISOString(),
      completedAt:
        workerResult?.completedAt ?? fallbackCompletedAt.toISOString(),
      durationMs:
        workerResult?.durationMs ??
        Math.max(0, fallbackCompletedAt.getTime() - issuedAt.getTime()),
      summary:
        evidenceFault ??
        workerRuntimeFault ??
        busterWorkerSummary(workerResult?.summary ?? "WORKER_RUNTIME_FAILED"),
      counts: faulted ? EMPTY_COUNTS : completedProviderResult!.counts,
      findings: faulted ? [] : completedProviderResult!.findings,
      metrics: faulted ? [] : completedProviderResult!.metrics,
      reports: normalizedReports,
      evidence,
      outputs: faulted ? [] : producedOutputs,
      resources,
      exitCode: workerResult?.exitCode ?? null,
      signal: workerResult?.signal ?? null,
      providerDetails: faulted
        ? null
        : completedProviderResult!.providerDetails,
    };
    const resultDigest = digest(unsigned);
    const result: AttemptResultV1 = {
      ...unsigned,
      resultDigest,
      receipt: receipt(this.#authorityId, this.#id(), resultDigest),
    };
    validatePipelineTestGateContract("attemptResult", result);
    const cleanupFailed =
      workerResult?.cleanup.state === "failed" ||
      retainedFaultCleanupFailed ||
      workerResult?.error?.code === "WORKER_TERMINATION_FAILED";
    if (cleanupFailed)
      this.#cleanupErrors.push({
        nodeId: node.id,
        message: workerResult?.cleanup.summary ?? "Cleanup failed.",
      });
    if (!retainFixture) {
      await fs.promises.rm(attemptRepository, { recursive: true, force: true });
    }
    return { result: freeze(result), instance, invocation, cleanupFailed };
  }

  async #persistWorkerCompletion(
    envelope: WorkerAttemptEnvelopeV1,
    result: WorkerAttemptResultV1,
  ): Promise<WorkerAttemptResultV1> {
    if (
      result.attemptId !== envelope.attemptId ||
      result.claimId !== envelope.claim.claimId ||
      result.claimGeneration !== envelope.claim.generation ||
      result.workerId !== envelope.claim.workerId
    )
      throw new Error("OBSERVABILITY_WORKER_RESULT_IDENTITY_MISMATCH");
    const bootHash = crypto
      .createHash("sha256")
      .update(
        `${envelope.pipelineRunId}\0${envelope.attemptId}\0${envelope.claim.claimId}\0${envelope.claim.generation}`,
      )
      .digest("hex");
    const producer = {
      producerId: `attempt:${bootHash}`,
      bootId: `claim:${bootHash}`,
      producerType: "buster-attempt",
    };
    const durableEvidence: WorkerAttemptResultV1["evidence"][number][] = [];
    let remainingEvidenceBytes = envelope.limits.evidenceBytes;
    for (const evidence of result.evidence) {
      const content = await this.#readManagedEvidence(
        evidence.artifact.storageUrl,
        remainingEvidenceBytes,
      );
      remainingEvidenceBytes -= content.byteLength;
      durableEvidence.push(
        await this.#durableAttemptStore.storeEvidence(
          {
            pipelineRunId: envelope.pipelineRunId,
            attemptId: envelope.attemptId,
            claimGeneration: envelope.claim.generation,
            producer,
            evidenceId: evidence.evidenceId,
            type: evidence.type,
            mediaType: evidence.artifact.mediaType,
          },
          content,
        ),
      );
    }
    const durableResult: WorkerAttemptResultV1 = {
      ...structuredClone(result),
      evidence: durableEvidence,
      resultDigest: "",
    };
    durableResult.resultDigest = workerAttemptResultDigest(durableResult);
    durableResult.receipt = receipt(
      this.#authorityId,
      bootHash,
      durableResult.resultDigest,
    );
    const occurredAt = this.#now().toISOString();
    const unsignedRecord = {
      schemaVersion: "producer-record.v1" as const,
      recordId: `record:${bootHash}`,
      producer,
      sequence: 1,
      recordType: "attempt.completed",
      occurredAt,
      correlation: {
        pipelineRunId: envelope.pipelineRunId,
        moduleId: envelope.moduleId,
        gateId: envelope.gateId,
        attemptId: envelope.attemptId,
        claimId: envelope.claim.claimId,
        claimGeneration: envelope.claim.generation,
        traceId: null,
        parentEventId: null,
      },
      payload: {
        state: durableResult.state,
        workerId: durableResult.workerId,
        resultDigest: durableResult.resultDigest,
        evidence: durableEvidence.map((item) => ({
          evidenceId: item.evidenceId,
          contentDigest: item.artifact.contentDigest,
        })),
      },
    };
    const record = {
      ...unsignedRecord,
      recordDigest: producerRecordDigest(unsignedRecord),
    };
    const closure = createProducerClosure({
      schemaVersion: "producer-closure.v1",
      closureId: `closure:${bootHash}`,
      producer,
      pipelineRunId: envelope.pipelineRunId,
      firstSequence: 1,
      finalSequence: 1,
      recordCount: 1,
      requiredEvidenceIds: durableEvidence.map((item) =>
        scopedEvidenceId(
          envelope.attemptId,
          envelope.claim.generation,
          item.evidenceId,
        ),
      ),
      closedAt: this.#now().toISOString(),
    });
    await this.#durableAttemptStore.storeResult(
      envelope.pipelineRunId,
      durableResult,
      { record, closure },
      { planId: envelope.planId, nodeId: envelope.nodeId },
    );
    try {
      await this.#durableAttemptStore.resumeCompletion(
        envelope.pipelineRunId,
        envelope.attemptId,
        envelope.claim.generation,
        this.#observabilityAdmissionStore,
      );
    } catch {
      // The result and completion intent are durable. Admission is retried by
      // Buster startup or Nova reconciliation without executing the provider again.
    }
    return Object.freeze(durableResult);
  }

  #context(
    signal: AbortSignal,
    log: TestProviderExecutionContext["log"],
    granted: ReadonlySet<string>,
    inputs: readonly ResolvedInputV1[],
  ): TestProviderExecutionContext {
    return Object.freeze({
      signal,
      workspaceRoot: this.#workspaceRoot,
      log,
      invoke: async (
        capability: string,
        request: TestProviderCapabilityRequest,
        invocationSignal?: AbortSignal,
      ) => {
        if (!granted.has(capability))
          throw new Error(`TEST_PROVIDER_CAPABILITY_DENIED:${capability}`);
        if (!this.#options.capabilityInvoker)
          throw new Error(`TEST_PROVIDER_CAPABILITY_UNAVAILABLE:${capability}`);
        return this.#options.capabilityInvoker.invoke(
          capability,
          request,
          invocationSignal ? AbortSignal.any([signal, invocationSignal]) : signal,
          inputs,
        );
      },
    });
  }

  async #collectEvidence(
    entry: TestProviderRegistryEntry,
    attemptId: string,
    evidenceDirectory: string,
    declarations: readonly DeclaredEvidenceV1[],
    maximumFiles: number,
    maximumBytes: number,
    signal: AbortSignal,
  ): Promise<EvidenceRefV1[]> {
    signal.throwIfAborted();
    if (declarations.length > maximumFiles)
      throw new Error("TEST_PROVIDER_ARTIFACT_FILE_LIMIT");
    const ids = new Set<string>();
    const files = new Set<string>();
    const evidence: EvidenceRefV1[] = [];
    let total = 0;
    for (const declaration of declarations) {
      signal.throwIfAborted();
      if (ids.has(declaration.evidenceId) || files.has(declaration.file))
        throw new Error(
          `TEST_PROVIDER_EVIDENCE_DUPLICATE:${declaration.evidenceId}`,
        );
      ids.add(declaration.evidenceId);
      files.add(declaration.file);
      if (!entry.registration.evidenceTypes.includes(declaration.type))
        throw new Error(
          `TEST_PROVIDER_EVIDENCE_TYPE_INVALID:${declaration.type}`,
        );
      const stored = await this.#store.store(
        attemptId,
        evidenceDirectory,
        declaration,
        maximumBytes - total,
        signal,
      );
      signal.throwIfAborted();
      total += stored.artifact.sizeBytes;
      if (total > maximumBytes)
        throw new Error("TEST_PROVIDER_ARTIFACT_BYTE_LIMIT");
      evidence.push(
        Object.freeze({
          evidenceId: declaration.evidenceId,
          type: declaration.type,
          artifact: stored.artifact,
        }),
      );
    }
    return evidence;
  }

  async #cleanupInstance(
    node: ResolvedPlanNodeV1,
    execution: AttemptExecution,
  ): Promise<boolean> {
    if (!execution.instance?.cleanup) return true;
    return this.#cleanupProvider(
      node,
      execution.instance,
      execution.invocation,
      createLogCapture(execution.invocation.limits.logBytes).contextLog,
    );
  }

  async #cleanupProvider(
    node: ResolvedPlanNodeV1,
    instance: LoadedTestProvider,
    invocation: ProviderInvocationV1,
    log: TestProviderExecutionContext["log"],
  ): Promise<boolean> {
    if (!instance.cleanup) return true;
    const controller = new AbortController();
    const timeoutMs = this.#options.cleanupTimeoutMs ?? 30_000;
    let timer: NodeJS.Timeout | undefined;
    const context = this.#context(
      controller.signal,
      log,
      new Set(invocation.grantedCapabilities),
      invocation.inputs,
    );
    try {
      await Promise.race([
        instance.cleanup(invocation, context),
        new Promise<never>((_resolve, reject) => {
          timer = setTimeout(() => {
            controller.abort(new Error("TEST_PROVIDER_CLEANUP_TIMEOUT"));
            reject(new Error("TEST_PROVIDER_CLEANUP_TIMEOUT"));
          }, timeoutMs);
        }),
      ]);
      return true;
    } catch (error) {
      this.#cleanupErrors.push({ nodeId: node.id, message: detail(error) });
      await instance.terminate();
      return false;
    } finally {
      if (timer) clearTimeout(timer);
      controller.abort(new Error("TEST_PROVIDER_CLEANUP_COMPLETE"));
    }
  }

  async #cleanupFixtures(): Promise<void> {
    for (const retained of [...this.#retainedFixtures].reverse()) {
      if (!await this.#cleanupInstance(retained.node, retained.execution)) continue;
      await retained.execution.instance?.terminate();
      {
        const repository = path.resolve(this.#workspaceRoot, retained.execution.invocation.workspace.repository);
        const attemptsRoot = path.join(path.resolve(this.#workspaceRoot), 'test-attempts');
        const attemptRoot = path.dirname(repository);
        const relative = path.relative(attemptsRoot, attemptRoot);
        if (!relative || relative === '..' || relative.startsWith(`..${path.sep}`)) {
          throw new Error('TEST_PROVIDER_ATTEMPT_PATH_INVALID');
        }
        fs.rmSync(repository, { recursive: true, force: true });
      }
    }
  }
}

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { assertStableDatabases, databasePolicy, inspectTrivyDatabases, type TrivyDatabasePolicy } from './trivy-database.ts';
import type { TestProviderCapabilityInvoker } from './runner.ts';

type JsonObject = Record<string, unknown>;

export interface SecurityScanCapabilityInvokerOptions {
  readonly workspaceRoot: string;
  readonly trivyExecutable: string;
  readonly allowedRegistryPrefixes: readonly string[];
  readonly maximumExecutionMs: number;
  readonly maximumOutputBytes: number;
  readonly cacheDirectory: string;
  readonly databasePolicy?: TrivyDatabasePolicy;
  readonly unsupportedHttpRegistry?: string;
  readonly registryAccess?: {readonly registryReference:string;readonly username:string;readonly password:string;readonly caFile?:string};
}

const DIGEST = /^sha256:[a-f0-9]{64}$/u;
const IMAGE = /^([A-Za-z0-9.-]+(?::[0-9]{1,5})?\/[a-z0-9]+(?:[._/-][a-z0-9]+)*)@(sha256:[a-f0-9]{64})$/u;

function object(value: unknown, label: string): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`SECURITY_SCAN_REQUEST_INVALID:${label}`);
  return value as JsonObject;
}

function text(value: unknown, label: string, maximum: number): string {
  if (typeof value !== 'string' || value.length < 1 || value.length > maximum) throw new Error(`SECURITY_SCAN_REQUEST_INVALID:${label}`);
  return value;
}

function contained(root: string, value: unknown, label: string): string {
  const requested = text(value, label, 4096);
  const resolved = fs.realpathSync(path.isAbsolute(requested) ? requested : path.resolve(root, requested));
  if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) throw new Error('SECURITY_SCAN_PATH_DENIED');
  return resolved;
}

function severity(value: unknown): 'critical' | 'high' | 'medium' | 'low' | 'info' {
  const normalized = String(value ?? 'UNKNOWN').toLowerCase();
  return ['critical', 'high', 'medium', 'low'].includes(normalized)
    ? normalized as 'critical' | 'high' | 'medium' | 'low' : 'info';
}

function relative(root: string, value: unknown): string | null {
  if (typeof value !== 'string' || value.length === 0) return null;
  const resolved = path.resolve(root, value);
  return resolved === root || resolved.startsWith(`${root}${path.sep}`) ? path.relative(root, resolved) || '.' : path.basename(value);
}

async function execute(executable: string, args: readonly string[], cwd: string, cache: {directory:string;registryEnvironment:Record<string,string>},
  timeoutMs: number, maximumBytes: number, signal: AbortSignal): Promise<Buffer> {
  const {directory:cacheDirectory,registryEnvironment}=cache;
  return await new Promise<Buffer>((resolve, reject) => {
    const controller = new AbortController();
    const combined = AbortSignal.any([signal, controller.signal]);
    const child = spawn(executable, [...args], {
      cwd, signal: combined, stdio: ['ignore', 'pipe', 'pipe'],
      env: { ...registryEnvironment, PATH: '/usr/local/bin:/usr/bin:/bin', HOME: cacheDirectory, TRIVY_CACHE_DIR: cacheDirectory,
        NO_COLOR: '1', LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' },
    });
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    let bytes = 0;
    let settled = false;
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const finish = (error?: Error, output?: Buffer): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (error) reject(error); else resolve(output!);
    };
    const collect = (target: Buffer[]) => (chunk: Buffer): void => {
      bytes += chunk.byteLength;
      if (bytes > maximumBytes) {
        controller.abort();
        finish(new Error('SECURITY_SCAN_OUTPUT_LIMIT_EXCEEDED'));
      } else target.push(Buffer.from(chunk));
    };
    child.stdout.on('data', collect(stdout));
    child.stderr.on('data', collect(stderr));
    child.on('error', (error) => {
      if (signal.aborted) finish(new Error('SECURITY_SCAN_CANCELLED'));
      else if (controller.signal.aborted) finish(new Error('SECURITY_SCAN_TIMEOUT'));
      else finish(new Error('SECURITY_SCANNER_EXECUTION_FAILED', { cause: error }));
    });
    child.on('close', (code, childSignal) => {
      if (settled) return;
      if (signal.aborted) return finish(new Error('SECURITY_SCAN_CANCELLED'));
      if (controller.signal.aborted) return finish(new Error('SECURITY_SCAN_TIMEOUT'));
      if (code !== 0 || childSignal) return finish(new Error(`SECURITY_SCANNER_EXECUTION_FAILED:${code ?? childSignal}`));
      finish(undefined, Buffer.concat(stdout));
    });
  });
}

function trivyResults(bytes: Buffer): JsonObject[] {
  let parsed: JsonObject;
  try { parsed = object(JSON.parse(bytes.toString('utf8')), 'trivy-result'); }
  catch (error) { throw new Error('SECURITY_SCANNER_RESULT_INVALID', { cause: error }); }
  if (parsed.SchemaVersion !== 2 || (parsed.Results !== null && parsed.Results !== undefined && !Array.isArray(parsed.Results))) {
    throw new Error('SECURITY_SCANNER_RESULT_INVALID');
  }
  return (Array.isArray(parsed.Results) ? parsed.Results : []).map((item) => object(item, 'trivy-result-item'));
}

function dependencyFindings(root: string, results: JsonObject[]): JsonObject[] {
  const findings: JsonObject[] = [];
  for (const result of results) {
    const sourceFile = relative(root, result.Target);
    for (const raw of Array.isArray(result.Vulnerabilities) ? result.Vulnerabilities : []) {
      const item = object(raw, 'trivy-vulnerability');
      findings.push({
        id: text(item.VulnerabilityID, 'vulnerability-id', 256), severity: severity(item.Severity),
        package: text(item.PkgName, 'package', 512), installedVersion: String(item.InstalledVersion ?? ''),
        fixedVersion: String(item.FixedVersion ?? ''), sourceFile, reachability: null,
        title: String(item.Title ?? item.VulnerabilityID).slice(0, 2048), status: String(item.Status ?? 'unknown'),
      });
    }
  }
  return findings;
}

function policyFindings(root: string, results: JsonObject[]): JsonObject[] {
  const findings: JsonObject[] = [];
  for (const result of results) {
    const sourceFile = relative(root, result.Target);
    for (const raw of Array.isArray(result.Misconfigurations) ? result.Misconfigurations : []) {
      const item = object(raw, 'trivy-misconfiguration');
      const cause = item.CauseMetadata && typeof item.CauseMetadata === 'object' && !Array.isArray(item.CauseMetadata)
        ? item.CauseMetadata as JsonObject : {};
      findings.push({ id: text(item.ID, 'misconfiguration-id', 256), severity: severity(item.Severity),
        sourceFile, line: Number.isSafeInteger(cause.StartLine) ? cause.StartLine : null,
        title: String(item.Title ?? item.Message ?? item.ID).slice(0, 2048),
        message: String(item.Message ?? item.Description ?? item.Title ?? item.ID).slice(0, 4096),
        resolution: String(item.Resolution ?? '').slice(0, 4096), status: String(item.Status ?? 'unknown') });
    }
  }
  return findings;
}

function scanTarget(operation: string, root: string, target: string): string {
  return operation === 'image' ? target : path.relative(root, target) || '.';
}

export class SecurityScanCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #root: string;
  readonly #trivy: string;
  readonly #unsupportedHttpRegistry: string|undefined;
  readonly #registryAccess: SecurityScanCapabilityInvokerOptions['registryAccess'];
  readonly #registryPrefixes: readonly string[];
  readonly #maximumExecutionMs: number;
  readonly #maximumOutputBytes: number;
  readonly #cache: string;
  readonly #databasePolicy: TrivyDatabasePolicy;

  constructor(options: SecurityScanCapabilityInvokerOptions) {
    this.#root = fs.realpathSync(options.workspaceRoot);
    this.#trivy = fs.realpathSync(options.trivyExecutable);
    fs.accessSync(this.#trivy, fs.constants.X_OK);
    if (!Number.isSafeInteger(options.maximumExecutionMs) || options.maximumExecutionMs < 1 || options.maximumExecutionMs > 2147483647
      || !Number.isSafeInteger(options.maximumOutputBytes) || options.maximumOutputBytes < 1024) {
      throw new Error('SECURITY_SCAN_LIMIT_INVALID');
    }
    if (options.allowedRegistryPrefixes.length < 1) throw new Error('SECURITY_SCAN_REGISTRY_POLICY_INVALID');
    this.#unsupportedHttpRegistry=options.unsupportedHttpRegistry;
    this.#registryAccess=options.registryAccess;
    if(options.registryAccess){
      if(!/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/u.test(options.registryAccess.registryReference) || !options.registryAccess.username || !options.registryAccess.password)throw new Error('SECURITY_SCAN_REGISTRY_AUTH_INVALID');
      if(options.registryAccess.caFile)fs.accessSync(options.registryAccess.caFile,fs.constants.R_OK);
    }
    this.#registryPrefixes = [...options.allowedRegistryPrefixes];
    this.#maximumExecutionMs = options.maximumExecutionMs;
    this.#maximumOutputBytes = options.maximumOutputBytes;
    this.#cache = fs.realpathSync(options.cacheDirectory);
    this.#databasePolicy = databasePolicy(options.databasePolicy);
  }

  async invoke(capability: string, request: unknown, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    if (capability !== 'security.scan') throw new Error('SECURITY_SCAN_CAPABILITY_DENIED');
    const value = object(request, 'request');
    const payload = object(value.payload, 'payload');
    const operation = text(value.operation, 'operation', 32);
    const timeoutMs = Math.min(this.#maximumExecutionMs,
      Number.isSafeInteger(payload.timeoutMs) && Number(payload.timeoutMs) > 0 ? Number(payload.timeoutMs) : this.#maximumExecutionMs);
    let args: string[];
    let target: string;
    if (operation === 'dependency') {
      target = contained(this.#root, payload.projectDirectory, 'projectDirectory');
      args = ['fs', '--scanners', 'vuln', '--format', 'json', '--quiet', '--skip-db-update', '--skip-java-db-update', '--offline-scan',
        '--skip-version-check', '--disable-telemetry', '--timeout', `${Math.ceil(timeoutMs / 1000)}s`, target];
    } else if (operation === 'image') {
      const image = text(payload.image, 'image', 2048);
      const parsed = IMAGE.exec(image);
      if (!parsed || payload.digest !== parsed[2] || !DIGEST.test(String(payload.digest))
        || !this.#registryPrefixes.some((prefix) => parsed[1] === prefix || parsed[1]!.startsWith(`${prefix}/`))) {
        throw new Error('SECURITY_SCAN_IMAGE_DENIED');
      }
      if(image.split('/')[0]===this.#unsupportedHttpRegistry)throw new Error('SECURITY_SCAN_HTTP_LAB_UNSUPPORTED: pinned scanner transport cannot be restricted to plaintext without relaxing TLS verification; configure an authenticated HTTPS registry');
      target = image;
      args = ['image', '--image-src', 'remote', '--scanners', 'vuln', '--format', 'json', '--quiet', '--skip-db-update', '--skip-java-db-update', '--offline-scan',
        '--skip-version-check', '--disable-telemetry', '--timeout', `${Math.ceil(timeoutMs / 1000)}s`, image];
    } else if (operation === 'kubernetes-policy') {
      target = contained(this.#root, payload.manifestPath, 'manifestPath');
      if (!fs.statSync(target).isFile()) throw new Error('SECURITY_SCAN_PATH_DENIED');
      const expected = text(payload.manifestDigest, 'manifestDigest', 71);
      const actual = `sha256:${crypto.createHash('sha256').update(fs.readFileSync(target)).digest('hex')}`;
      if (!DIGEST.test(expected) || actual !== expected) throw new Error('SECURITY_SCAN_MANIFEST_DIGEST_MISMATCH');
      // Trivy config has no offline-scan flag. Disabling check updates,
      // version checks, and telemetry removes each config-scan network path.
      args = ['config', '--format', 'json', '--quiet', '--skip-check-update', '--skip-version-check', '--disable-telemetry',
        '--misconfig-scanners', 'kubernetes', '--timeout', `${Math.ceil(timeoutMs / 1000)}s`, target];
    } else throw new Error('SECURITY_SCAN_OPERATION_DENIED');
    return this.#scan(operation, target, args, timeoutMs, signal);
  }

  #registryConfiguration(operation:string,target:string,args:string[]){
    let credentialDirectory:string|undefined;
      const registryEnvironment:Record<string,string>={};
      const access=this.#registryAccess;
      if(operation==='image' && access && target.split('/')[0]===access.registryReference){
        credentialDirectory=fs.mkdtempSync(path.join(this.#cache,'.registry-auth-'));fs.chmodSync(credentialDirectory,0o700);
        fs.writeFileSync(path.join(credentialDirectory,'config.json'),JSON.stringify({auths:{[access.registryReference]:{auth:Buffer.from(`${access.username}:${access.password}`).toString('base64')}}}),{mode:0o600});
        registryEnvironment.DOCKER_CONFIG=credentialDirectory;
        if(access.caFile)args.splice(args.length-1,0,'--cacert',access.caFile);
      }
    return {directory:credentialDirectory,environment:registryEnvironment};
  }

  async #scan(operation: string, target: string, args: string[], timeoutMs: number, signal: AbortSignal) {
    const deadline = Date.now() + timeoutMs;
    const bounded = AbortSignal.any([signal, AbortSignal.timeout(timeoutMs)]);
    let credentialDirectory:string|undefined;
    try {
      const registryConfig=this.#registryConfiguration(operation,target,args);
      credentialDirectory=registryConfig.directory;
      const before = operation === 'kubernetes-policy' ? undefined
        : await inspectTrivyDatabases(this.#cache, this.#databasePolicy, bounded);
      const remaining = deadline - Date.now();
      if (remaining <= 0) throw new Error('SECURITY_SCAN_TIMEOUT');
      const output = trivyResults(await execute(this.#trivy, args, this.#root, {directory:this.#cache,registryEnvironment:registryConfig.environment},
        remaining, this.#maximumOutputBytes, bounded));
      const findings = operation === 'kubernetes-policy' ? policyFindings(this.#root, output) : dependencyFindings(this.#root, output);
      const databaseEvidence = before ? await inspectTrivyDatabases(this.#cache, this.#databasePolicy, bounded) : undefined;
      if (before && databaseEvidence) assertStableDatabases(before, databaseEvidence);
      const reportedTarget = scanTarget(operation, this.#root, target);
      const result = Object.freeze({ scanner: 'trivy', operation, target: reportedTarget,
        resultDigest: `sha256:${crypto.createHash('sha256').update(JSON.stringify(databaseEvidence ? { findings, databaseEvidence } : findings)).digest('hex')}`,
        findings, ...(databaseEvidence ? { databaseEvidence } : {}) });
      bounded.throwIfAborted();
      if (Date.now() >= deadline) throw new Error('SECURITY_SCAN_TIMEOUT');
      return result;
    } catch (error) {
      if (signal.aborted) throw new Error('SECURITY_SCAN_CANCELLED', { cause: error });
      if (bounded.aborted || Date.now() >= deadline) throw new Error('SECURITY_SCAN_TIMEOUT', { cause: error });
      throw error;
    } finally {
      if(credentialDirectory)fs.rmSync(credentialDirectory,{recursive:true,force:true});
    }
  }
}

import { runProcessInput } from './process-input.ts';
import { assertHandoffSourceRequest,existingExposureHandoff,exposureHandoffPatch,observedExposureHandoff } from './exposure-handoff.ts';
import { EXPOSURE_OWNER_ANNOTATION, EXPOSURE_REQUEST_ANNOTATION, EXPOSURE_PREDECESSORS_ANNOTATION, exposurePredecessors, exposureIdentity, generationObserved, assertExposureRequest, assertRequestedExposure, ownedReleaseAction } from './exposure-generation.ts';
import fs from 'node:fs';
import type { TestProviderCapabilityRequest } from '@kubeclaw/plugin-sdk';
import type { TestProviderCapabilityInvoker } from './runner.ts';

const DNS_LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/u;
const MAX_TIMER_MS = 2_147_483_647;
type JsonObject = Record<string, unknown>;
type Execute = (command: string, args: readonly string[], options: Readonly<Record<string, unknown>>)
  => Promise<{ stdout?: string; stderr?: string }>;

async function executeProcess(command: string, args: readonly string[], options: Readonly<Record<string, unknown>>): Promise<{ stdout: string; stderr: string }> {
  const result = await runProcessInput(command, args, {
    ...(options.env ? { env: options.env as NodeJS.ProcessEnv } : {}),
    ...(options.signal ? { signal: options.signal as AbortSignal } : {}),
    input: options.input as string | Buffer | null ?? null,
    timeoutMs: Number(options.timeout ?? 30_000), maximumOutputBytes: Number(options.maxBuffer ?? 1024 * 1024),
    prefix: 'TAILSCALE_EXPOSURE_KUBECTL',
  });
  const stdout = result.stdout.toString('utf8'); const stderr = result.stderr.toString('utf8');
  if (result.code !== 0) throw Object.assign(new Error(`TAILSCALE_EXPOSURE_KUBECTL_FAILED:${String(result.code)}:${String(result.signal)}`), { stdout, stderr });
  return { stdout, stderr };
}

export interface TailscaleExposureCapabilityInvokerOptions {
  readonly kubectlExecutable: string;
  readonly controllerNamespace: string;
  readonly leaseApiGroup: string;
  readonly leaseApiVersion: string;
  readonly allowedNamespacePrefixes: readonly string[];
  readonly allowedHostSuffixes: readonly string[];
  readonly maximumExecutionMs: number;
  readonly pollIntervalMs?: number;
  readonly execute?: Execute;
  readonly now?: () => Date;
}

function object(value: unknown, label: string): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`TAILSCALE_EXPOSURE_REQUEST_INVALID:${label}`);
  return value as JsonObject;
}
function text(value: unknown, label: string, maximum = 1024): string {
  if (typeof value !== 'string' || value.length < 1 || value.length > maximum || value.includes('\0')) {
    throw new Error(`TAILSCALE_EXPOSURE_REQUEST_INVALID:${label}`);
  }
  return value;
}
function integer(value: unknown, label: string, minimum: number, maximum: number): number {
  if (!Number.isSafeInteger(value) || Number(value) < minimum || Number(value) > maximum) {
    throw new Error(`TAILSCALE_EXPOSURE_REQUEST_INVALID:${label}`);
  }
  return Number(value);
}
function suffix(value: string): string {
  const normalized = value.toLowerCase();
  if (!/^\.[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?$/u.test(normalized) || normalized.includes('..')) {
    throw new Error('TAILSCALE_EXPOSURE_HOST_SUFFIX_INVALID');
  }
  return normalized;
}

export class TailscaleExposureCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #kubectl: string;
  readonly #controllerNamespace: string;
  readonly #apiGroup: string;
  readonly #apiVersion: string;
  readonly #prefixes: readonly string[];
  readonly #suffixes: readonly string[];
  readonly #maximumExecutionMs: number;
  readonly #pollIntervalMs: number;
  readonly #execute: Execute;
  readonly #now: () => Date;
  readonly #environment: NodeJS.ProcessEnv;

  constructor(options: TailscaleExposureCapabilityInvokerOptions) {
    this.#kubectl = fs.realpathSync(options.kubectlExecutable);
    if (!fs.statSync(this.#kubectl).isFile()) throw new Error('TAILSCALE_EXPOSURE_KUBECTL_INVALID');
    if (!DNS_LABEL.test(options.controllerNamespace)) throw new Error('TAILSCALE_EXPOSURE_CONTROLLER_NAMESPACE_INVALID');
    if (!/^[a-z0-9.-]+$/u.test(options.leaseApiGroup) || !/^v[0-9]+(?:[a-z]+[0-9]+)?$/u.test(options.leaseApiVersion)) {
      throw new Error('TAILSCALE_EXPOSURE_API_INVALID');
    }
    if (!Array.isArray(options.allowedNamespacePrefixes) || options.allowedNamespacePrefixes.length < 1
      || options.allowedNamespacePrefixes.some((item) => !DNS_LABEL.test(item) || item.length > 42)) {
      throw new Error('TAILSCALE_EXPOSURE_NAMESPACE_POLICY_INVALID');
    }
    if (!Array.isArray(options.allowedHostSuffixes) || options.allowedHostSuffixes.length < 1) {
      throw new Error('TAILSCALE_EXPOSURE_HOST_POLICY_INVALID');
    }
    this.#controllerNamespace = options.controllerNamespace; this.#apiGroup = options.leaseApiGroup;
    this.#apiVersion = options.leaseApiVersion; this.#prefixes = [...new Set(options.allowedNamespacePrefixes)];
    this.#suffixes = [...new Set(options.allowedHostSuffixes.map(suffix))];
    this.#maximumExecutionMs = integer(options.maximumExecutionMs, 'maximumExecutionMs', 1, MAX_TIMER_MS);
    this.#pollIntervalMs = integer(options.pollIntervalMs ?? 1000, 'pollIntervalMs', 10, this.#maximumExecutionMs);
    this.#execute = options.execute ?? executeProcess; this.#now = options.now ?? (() => new Date());
    this.#environment = { PATH: process.env.PATH, KUBECONFIG: process.env.KUBECONFIG,
      KUBERNETES_SERVICE_HOST: process.env.KUBERNETES_SERVICE_HOST,
      KUBERNETES_SERVICE_PORT: process.env.KUBERNETES_SERVICE_PORT };
  }

  #namespace(value: unknown): string {
    const namespace = text(value, 'namespace', 63);
    if (!DNS_LABEL.test(namespace) || !this.#prefixes.some((prefix) => namespace === prefix || namespace.startsWith(`${prefix}-`))) {
      throw new Error('TAILSCALE_EXPOSURE_NAMESPACE_DENIED');
    }
    return namespace;
  }
  async #run(args: readonly string[], input: string | null, signal: AbortSignal, timeout = this.#maximumExecutionMs): Promise<string> {
    if (signal.aborted) throw new Error('TAILSCALE_EXPOSURE_CANCELLED');
    try {
      const result = await this.#execute(this.#kubectl, args, { input, signal, timeout: Math.min(timeout, this.#maximumExecutionMs),
        maxBuffer: 1024 * 1024, env: this.#environment });
      return String(result.stdout ?? '');
    } catch (error) {
      if (signal.aborted) throw new Error('TAILSCALE_EXPOSURE_CANCELLED');
      throw error;
    }
  }
  async #lease(name: string, signal: AbortSignal, timeout = this.#maximumExecutionMs): Promise<JsonObject> {
    return object(JSON.parse(await this.#run(['get', 'busternamespacelease', name, '-n', this.#controllerNamespace, '-o', 'json'], null, signal, timeout)), 'lease');
  }
  async #wait(name: string, expected: 'Ready' | 'Off', owner: string, signal: AbortSignal, timeoutMs: number): Promise<JsonObject> {
    const deadline = Date.now() + timeoutMs;
    for (;;) {
      if (signal.aborted) throw new Error('TAILSCALE_EXPOSURE_CANCELLED');
      const remaining = deadline - Date.now();
      if (remaining <= 0) throw new Error('TAILSCALE_EXPOSURE_READINESS_TIMEOUT');
      const lease = await this.#lease(name, signal, remaining); const status = object(lease.status ?? {}, 'lease.status');
      const annotations = object(object(lease.metadata, 'lease.metadata').annotations ?? {}, 'lease.annotations');
      if (annotations[EXPOSURE_OWNER_ANNOTATION] !== owner) throw new Error('TAILSCALE_EXPOSURE_LEASE_CHANGED');
      if (Date.now() >= deadline) throw new Error('TAILSCALE_EXPOSURE_READINESS_TIMEOUT');
      if (generationObserved(lease, owner, expected)) return lease;
      if (status.phase === 'Failed' || status.exposurePhase === 'Failed') throw new Error(`TAILSCALE_EXPOSURE_CONTROLLER_FAILED:${String(status.message ?? 'unknown')}`);
      if (Date.now() >= deadline) throw new Error('TAILSCALE_EXPOSURE_READINESS_TIMEOUT');
      await new Promise<void>((resolve, reject) => {
        const finish = () => { signal.removeEventListener('abort', cancel); resolve(); };
        const timer = setTimeout(finish, Math.min(this.#pollIntervalMs, Math.max(1, deadline - Date.now())));
        const cancel = () => { clearTimeout(timer); reject(new Error('TAILSCALE_EXPOSURE_CANCELLED')); };
        signal.addEventListener('abort', cancel, { once: true });
      });
    }
  }
  #verifyLease(lease: JsonObject, payload: JsonObject, namespace: string): { serviceName: string; servicePort: number; expiresAt: string } {
    const metadata = object(lease.metadata, 'lease.metadata'); const spec = object(lease.spec, 'lease.spec');
    const status = object(lease.status, 'lease.status');
    if (metadata.name !== payload.leaseName || spec.namespaceName !== namespace || status.namespaceName !== namespace
      || spec.serviceName !== payload.serviceName || Number(spec.servicePort) !== Number(payload.servicePort) || status.phase !== 'Ready') {
      throw new Error('TAILSCALE_EXPOSURE_LEASE_MISMATCH');
    }
    const expiresAt = text(status.expiresAt, 'expiresAt', 64);
    const declaredExpiresAt = text(payload.expiresAt, 'payload.expiresAt', 64);
    if (expiresAt !== declaredExpiresAt) throw new Error('TAILSCALE_EXPOSURE_LEASE_MISMATCH');
    if (!Number.isFinite(Date.parse(expiresAt)) || Date.parse(expiresAt) <= this.#now().getTime()) throw new Error('TAILSCALE_EXPOSURE_LEASE_EXPIRED');
    return { serviceName: text(spec.serviceName, 'serviceName', 63),
      servicePort: integer(spec.servicePort, 'servicePort', 1, 65535), expiresAt };
  }
  async #rollbackFailedPrepare(leaseName: string, owner: string, originalError: unknown): Promise<void> {
    const timeoutMs = Math.min(15_000, this.#maximumExecutionMs);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const lease = await this.#lease(leaseName, controller.signal);
      const metadata = object(lease.metadata, 'lease.metadata');
      const annotations = object(metadata.annotations ?? {}, 'lease.metadata.annotations');
      if (annotations[EXPOSURE_OWNER_ANNOTATION] !== owner) return;
      const resourceVersion = text(metadata.resourceVersion, 'lease.metadata.resourceVersion', 64);
      const patch = JSON.stringify({
        metadata: { resourceVersion },
        spec: { purpose: 'gate', exposure: { provider: 'off' } },
      });
      await this.#run(['patch', 'busternamespacelease', leaseName, '-n', this.#controllerNamespace,
        '--type=merge', '-p', patch], null, controller.signal, timeoutMs);
    } catch (rollbackError) {
      throw new AggregateError([originalError, rollbackError], 'TAILSCALE_EXPOSURE_ROLLBACK_FAILED');
    } finally {
      clearTimeout(timer);
    }
  }
  #prepareInput(payload:JsonObject) {
    if(payload.retentionMode!==undefined&&payload.retentionMode!=='await-readiness')throw new Error('EXPOSURE_RETENTION_MODE_INVALID');
    const leaseName = text(payload.leaseName, 'leaseName', 63); if (!DNS_LABEL.test(leaseName)) throw new Error('TAILSCALE_EXPOSURE_LEASE_NAME_INVALID');
    const namespace = this.#namespace(payload.namespace); const timeoutMs = integer(payload.readinessTimeoutMs, 'readinessTimeoutMs', 1, this.#maximumExecutionMs);
    const path = text(payload.path, 'path', 1024);
    if (!path.startsWith('/') || path.startsWith('//') || /[\r\n?#]/u.test(path)) throw new Error('TAILSCALE_EXPOSURE_PATH_INVALID');
    const hostname = payload.hostname === undefined ? undefined : text(payload.hostname, 'hostname', 63);
    if (hostname !== undefined && !DNS_LABEL.test(hostname)) throw new Error('TAILSCALE_EXPOSURE_HOSTNAME_INVALID');
    return {leaseName,namespace,timeoutMs,path,hostname};
  }
  async #prepare(payload: JsonObject, resourceId: string, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    const {leaseName,namespace,timeoutMs,path,hostname}=this.#prepareInput(payload);
    const resource = `busternamespaceleases.${this.#apiGroup}`;
    for (const verb of ['get', 'patch']) {
      const allowed = (await this.#run(['auth', 'can-i', verb, resource, '-n', this.#controllerNamespace], null, signal, 15_000)).trim();
      if (allowed !== 'yes') throw new Error(`TAILSCALE_EXPOSURE_RBAC_DENIED:${verb}`);
    }
    const before = await this.#lease(leaseName, signal); const verified = this.#verifyLease(before, payload, namespace);
    const identity = exposureIdentity(resourceId, payload); const { owner } = identity;
    assertHandoffSourceRequest(before,identity);
    const pending = payload.retentionMode === 'await-readiness' ? existingExposureHandoff(before,identity) : undefined;
    if(pending){
      assertRequestedExposure(before,payload);
      const ready=await this.#wait(leaseName,'Ready',pending.owner,signal,timeoutMs);
      this.#verifyLease(ready,payload,namespace);
      const {urlText,publicHost}=this.#publicURL(object(ready.status,'lease.status'),path,hostname);
      return {ok:true,leaseName,namespace,url:urlText,hostname:publicHost,createdAt:object(ready.status,'lease.status').createdAt,expiresAt:verified.expiresAt,
        releaseAction:ownedReleaseAction(leaseName,this.#controllerNamespace,pending.owner),handoff:observedExposureHandoff(ready,identity)};
    }
    assertExposureRequest(before, identity);
    const metadata = object(before.metadata, 'lease.metadata');
    const resourceVersion = text(metadata.resourceVersion, 'lease.resourceVersion', 64);
    const alreadyOwned = object(metadata.annotations ?? {}, 'lease.annotations')[EXPOSURE_OWNER_ANNOTATION] === owner;
    if (alreadyOwned) assertRequestedExposure(before, payload);
    const patch = { metadata: { resourceVersion, annotations: { [EXPOSURE_OWNER_ANNOTATION]: owner,
      [EXPOSURE_REQUEST_ANNOTATION]: identity.request, [EXPOSURE_PREDECESSORS_ANNOTATION]: exposurePredecessors(before) } },
      spec: { purpose: 'final-preview', exposure: { provider: 'tailscale-ingress',
        serviceName: verified.serviceName, servicePort: verified.servicePort, path, hostname: hostname ?? null } } };
    try {
      if (!alreadyOwned) await this.#run(['patch', 'busternamespacelease', leaseName, '-n', this.#controllerNamespace,
        '--type=merge', '-p', JSON.stringify(patch)], null, signal, 15_000);
      const ready = await this.#wait(leaseName, 'Ready', owner, signal, timeoutMs);
      assertRequestedExposure(ready, payload);
      this.#verifyLease(ready, payload, namespace);
      const status = object(ready.status, 'lease.status');
      const { urlText, publicHost } = this.#publicURL(status, path, hostname);
      let handoff;
      if(payload.retentionMode==='await-readiness'){
        const transfer=exposureHandoffPatch(ready,identity);
        await this.#run(['patch','busternamespacelease',leaseName,'-n',this.#controllerNamespace,'--type=merge','-p',JSON.stringify(transfer.patch)],null,signal,15_000);
        const transferred=await this.#wait(leaseName,'Ready',transfer.handoff.owner,signal,timeoutMs);
        this.#verifyLease(transferred,payload,namespace);assertRequestedExposure(transferred,payload);
        handoff=observedExposureHandoff(transferred,identity);
      }
      return Object.freeze({ ok: true, leaseName, namespace, url: urlText, hostname: publicHost,
        createdAt: text(status.createdAt, 'createdAt', 64), expiresAt: verified.expiresAt,
        releaseAction: ownedReleaseAction(leaseName, this.#controllerNamespace, handoff?.owner ?? owner),...(handoff?{handoff}:{}) });
    } catch (error) {
      await this.#rollbackFailedPrepare(leaseName, owner, error);
      throw error;
    }
  }
  #publicURL(status: JsonObject, path: string, hostname: string | undefined): { urlText: string; publicHost: string } {
    const urlText = text(status.previewUrl, 'previewUrl', 2048); const url = new URL(urlText);
    if (url.protocol !== 'https:' || url.username || url.password || url.hash || url.origin + url.pathname !== urlText) {
      throw new Error('TAILSCALE_EXPOSURE_URL_INVALID');
    }
    const publicHost = url.hostname.toLowerCase();
    if (!this.#suffixes.some((item) => publicHost.endsWith(item) && publicHost.length > item.length)) throw new Error('TAILSCALE_EXPOSURE_HOST_DENIED');
    if (status.exposureHostname !== publicHost || url.pathname !== path
      || (hostname !== undefined && publicHost !== hostname && !publicHost.startsWith(`${hostname}.`))) throw new Error('TAILSCALE_EXPOSURE_HOST_MISMATCH');
    return { urlText, publicHost };
  }
  async #release(payload: JsonObject, resourceId: string, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    const leaseName = text(payload.leaseName, 'leaseName', 63); if (!DNS_LABEL.test(leaseName)) throw new Error('TAILSCALE_EXPOSURE_LEASE_NAME_INVALID');
    const namespace = this.#namespace(payload.namespace);
    const before = await this.#lease(leaseName, signal);
    const identity = exposureIdentity(resourceId, payload);
    const metadata = object(before.metadata, 'lease.metadata');
    const annotations = object(metadata.annotations ?? {}, 'lease.annotations');
    if (annotations[EXPOSURE_OWNER_ANNOTATION] !== identity.owner) return Object.freeze({ ok: true, leaseName, released: false, superseded: true });
    assertExposureRequest(before, identity);
    const verified = this.#verifyLease(before, payload, namespace);
    const resourceVersion = text(metadata.resourceVersion, 'lease.resourceVersion', 64);
    const patch = JSON.stringify({ metadata: { resourceVersion }, spec: { purpose: 'gate', exposure: { provider: 'off' } } });
    await this.#run(['patch', 'busternamespacelease', leaseName, '-n', this.#controllerNamespace, '--type=merge', '-p', patch], null, signal, 15_000);
    const released = await this.#wait(leaseName, 'Off', identity.owner, signal, this.#maximumExecutionMs);
    const status = object(released.status, 'lease.status');
    if (status.namespaceName !== namespace || status.expiresAt !== verified.expiresAt) throw new Error('TAILSCALE_EXPOSURE_LEASE_CHANGED');
    return Object.freeze({ ok: true, leaseName, released: true });
  }
  async invoke(capability: string, request: TestProviderCapabilityRequest, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    if (capability !== 'kubernetes.exposure' || request.resource.type !== 'kubernetes.exposure'
      || !/^kubernetes-exposure:attempt:[A-Za-z0-9._:-]+$/u.test(request.resource.canonicalId)) {
      throw new Error('TAILSCALE_EXPOSURE_CAPABILITY_REQUEST_INVALID');
    }
    const payload = object(request.payload, 'payload');
    if (request.operation === 'prepare') return this.#prepare(payload, request.resource.canonicalId, signal);
    if (request.operation === 'release') return this.#release(payload, request.resource.canonicalId, signal);
    throw new Error('TAILSCALE_EXPOSURE_OPERATION_INVALID');
  }
}

