  if (profile === undefined) return request;
  const selected = parseRuntimeDispatchProfile(profile);
  portableJson(request);
  if (Object.hasOwn(request, 'runtimeDispatchProfile')) throw new Error('RUNTIME_DISPATCH_PROFILE_ALREADY_BOUND');
  return Object.freeze({ ...request, runtimeDispatchProfile: selected });
}

/** Only closed invocation metadata is control. An identically named model key is ordinary data. */
export function runtimeDispatchProfileFields(request: object, capability?: string): Readonly<{ runtimeDispatchProfile?: RuntimeDispatchProfile }> {
  portableJson(request);
  if (!Object.hasOwn(request, 'runtimeDispatchProfile')) return {};
  if (capability !== undefined && capability !== 'runtime.dispatch') throw new Error('RUNTIME_DISPATCH_PROFILE_CAPABILITY_INVALID');
  return { runtimeDispatchProfile: parseRuntimeDispatchProfile((request as CapabilityInvocation).runtimeDispatchProfile) };
}

import type { AttemptIdentity } from './generated/contracts.ts';
import { canonicalJson, sha256Text } from './values.ts';

/** Issued by the Git adapter; the runtime verifies the protected owner record. */
export interface RuntimeWorkspaceReference {
  readonly schemaVersion: 'runtime-workspace.v1';
  readonly repositoryRoot: string;
  readonly workspaceRoot: string;
  readonly workspacePath: string;
  readonly branch: string;
  readonly sourceRevision: string;
  readonly owner: AttemptIdentity;
}

export function runtimeWorkspaceGeneration(owner: AttemptIdentity, scope: Readonly<{ repositoryRoot: string; branch: string }>): string {
  return sha256Text(canonicalJson({ owner, repositoryRoot: scope.repositoryRoot, branch: scope.branch })).slice(7);
}

export function runtimeWorkspaceOwnerFile(workspacePath: string): string {
  return `.kubeclaw-workspace-owners/${sha256Text(workspacePath).slice(7)}.json`;
}

export function parseRuntimeWorkspace(value: unknown, owner: AttemptIdentity): RuntimeWorkspaceReference {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('RUNTIME_WORKSPACE_REFERENCE_INVALID');
  const ref = value as Record<string, unknown>;
  const keys = ['schemaVersion', 'repositoryRoot', 'workspaceRoot', 'workspacePath', 'branch', 'sourceRevision', 'owner'];
  if (Object.keys(ref).length !== keys.length || Object.keys(ref).some((key) => !keys.includes(key))) throw new Error('RUNTIME_WORKSPACE_REFERENCE_INVALID');
  if (ref.schemaVersion !== 'runtime-workspace.v1' || typeof ref.sourceRevision !== 'string' || !/^[a-f0-9]{40}(?:[a-f0-9]{24})?$/u.test(ref.sourceRevision)) throw new Error('RUNTIME_WORKSPACE_REFERENCE_INVALID');
  for (const key of ['repositoryRoot', 'workspaceRoot', 'workspacePath', 'branch']) {
    if (typeof ref[key] !== 'string' || !ref[key] || ref[key].length > 4096 || /[\u0000-\u001f\u007f]/u.test(ref[key])) throw new Error('RUNTIME_WORKSPACE_REFERENCE_INVALID');
  }
  if (canonicalJson(ref.owner) !== canonicalJson(owner)) throw new Error('RUNTIME_WORKSPACE_OWNER_MISMATCH');
  return value as RuntimeWorkspaceReference;
}

import {verifiedArtifactJsonText} from './artifact-json.ts';
import { sourcePreflight, type SourceBinding } from './source-preflight.ts';
import type { ArtifactRef } from './generated/contracts.ts';
import type { PluginInvocationContext } from './runtime.ts';
import { canonicalJson, sha256Text } from './values.ts';
import { parseReviewSubject, type ReviewSubject } from './review-subject.ts';

export async function readBoundArtifact(artifact: ArtifactRef, context: PluginInvocationContext): Promise<Record<string, unknown>> {
  if (artifact.producer.runId !== context.contract.lease.attempt.runId || artifact.mediaType !== 'application/json'
    || artifact.sizeBytes > 4_194_304) throw new Error('SOURCE_APPROVAL_ARTIFACT_INVALID');
  const read = await context.invoke('artifacts.read', { operation: 'get_json_bytes', resource: { type: 'artifact.object', canonicalId: artifact.artifactId },
    payload: { namespace: artifact.namespace, digest: artifact.digest, reference: artifact } });
  const serialized = verifiedArtifactJsonText(read, artifact);
  if (read.digest !== artifact.digest || read.sizeBytes !== artifact.sizeBytes
    || sha256Text(serialized) !== artifact.digest || Buffer.byteLength(serialized) !== artifact.sizeBytes) throw new Error('SOURCE_APPROVAL_ARTIFACT_CORRUPT');
  return read.value as Record<string, unknown>;
}
function latest(artifacts: readonly ArtifactRef[]): ArtifactRef | undefined {
  if (!artifacts.length) return undefined;
  if (new Set(artifacts.map(item => item.producer.stageId)).size !== 1) throw new Error('SOURCE_APPROVAL_AMBIGUOUS');
  const maximum = Math.max(...artifacts.map(item => item.producer.attemptNumber));
  const candidates = artifacts.filter(item => item.producer.attemptNumber === maximum);
  if (candidates.length !== 1) throw new Error('SOURCE_APPROVAL_AMBIGUOUS');
  return candidates[0];
}
/** Only report-bound approval artifacts from visible graph ancestors grant authority. */
export async function approvedSource(context: PluginInvocationContext, expected?: SourceBinding): Promise<{ subject: ReviewSubject; sourceRevision: string } | undefined> {
  const artifacts = context.contract.artifacts.filter(item => item.producer.runId === context.contract.lease.attempt.runId);
  if (expected) return requiredSource(expected, artifacts, context);
  const report = latest(artifacts.filter(item => item.namespace === 'kubeclaw.architecture-validator' && item.artifactId === 'architecture-validation'));
  const approval = latest(artifacts.filter(item => item.namespace === 'kubeclaw.human-approval' && item.artifactId === 'architecture-approval'));
  if (!report && !approval) return undefined;
  if (!report) throw new Error('SOURCE_APPROVAL_REQUIRED');
  const reviewed = await readBoundArtifact(report, context);
  if (reviewed.verdict !== 'passed' || !Array.isArray(reviewed.findings)) throw new Error('SOURCE_APPROVAL_BINDING_INVALID');
  if (reviewed.findings.length) {
    if (!approval) throw new Error('SOURCE_APPROVAL_REQUIRED');
    const accepted = await readBoundArtifact(approval, context);
    if (accepted.reportDigest !== report.digest || accepted.reportStageId !== report.producer.stageId || accepted.decision !== 'approved'
      || canonicalJson(accepted.subject) !== canonicalJson(reviewed.subject)) throw new Error('SOURCE_APPROVAL_BINDING_INVALID');
  }
  const subject = parseReviewSubject(reviewed.subject, context.contract.lease.attempt.runId);
  return { subject, sourceRevision: await approvedLineage(subject, artifacts, context) };
}

async function requiredSource(expected: SourceBinding, artifacts: readonly ArtifactRef[], context: PluginInvocationContext) {
  const {binding, subject} = await sourcePreflight(expected, context);
  if (binding.reviewStageId) {
    const report = latest(artifacts.filter(item => item.namespace === 'kubeclaw.architecture-validator'
      && item.artifactId === 'architecture-validation' && item.producer.stageId === binding.reviewStageId));
    if (!report) throw new Error('SOURCE_APPROVAL_REQUIRED');
    const reviewed = await readBoundArtifact(report, context);
    if (reviewed.verdict !== 'passed' || !Array.isArray(reviewed.findings)
      || canonicalJson(reviewed.subject) !== canonicalJson(subject)) throw new Error('SOURCE_APPROVAL_BINDING_INVALID');
    if (reviewed.findings.length) {
      const approval = latest(artifacts.filter(item => item.namespace === 'kubeclaw.human-approval' && item.artifactId === 'architecture-approval'));
      if (!approval) throw new Error('SOURCE_APPROVAL_REQUIRED');
      const accepted = await readBoundArtifact(approval, context);
      if (accepted.reportDigest !== report.digest || accepted.reportStageId !== report.producer.stageId
        || accepted.decision !== 'approved' || canonicalJson(accepted.subject) !== canonicalJson(subject)) throw new Error('SOURCE_APPROVAL_BINDING_INVALID');
    }
  }
  return {subject, sourceRevision: await approvedLineage(subject, artifacts, context)};
}

async function syncedRevision(subject: ReviewSubject, artifacts: readonly ArtifactRef[], context: PluginInvocationContext): Promise<string> {
  const sync = latest(artifacts.filter(item => item.namespace === 'kubeclaw.blueprint-sync' && item.artifactId.startsWith('blueprint-sync:')));
  let revision = subject.sourceRevision;
  if (sync) {
    const synced = await readBoundArtifact(sync, context);
    if (synced.subjectDigest !== subject.digest) return revision;
    if (synced.sourceBefore !== subject.sourceRevision || synced.repositoryRoot !== subject.repositoryRoot
      || synced.architectureRevision !== subject.architectureRevision || typeof synced.sourceRevision !== 'string'
      || !/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/u.test(synced.sourceRevision)) throw new Error('SOURCE_APPROVAL_SYNC_BINDING_INVALID');
    revision = synced.sourceRevision;
  }
  return revision;
}

async function approvedLineage(subject: ReviewSubject, artifacts: readonly ArtifactRef[], context: PluginInvocationContext): Promise<string> {
  let revision = await syncedRevision(subject, artifacts, context);
  const edges: { before: string; after: string }[] = [];
  for (const artifact of artifacts.filter(item => item.namespace === 'kubeclaw.implementation-agent' && item.artifactId.startsWith('implementation:'))) {
    const completed = await readBoundArtifact(artifact, context);
    if (completed.subjectDigest !== subject.digest) continue;
    if (completed.status !== 'ready_for_testing' || typeof completed.headBefore !== 'string' || typeof completed.sourceRevision !== 'string') throw new Error('SOURCE_APPROVAL_IMPLEMENTATION_INVALID');
    edges.push({ before: completed.headBefore, after: completed.sourceRevision });
  }
  const seen = new Set<string>();
  for (;;) {
    const next = edges.filter(edge => edge.before === revision);
    if (!next.length) return revision;
    if (next.length !== 1 || seen.has(revision)) throw new Error('SOURCE_APPROVAL_LINEAGE_AMBIGUOUS');
    seen.add(revision); revision = next[0]!.after;
  }
}

import {PORTABLE_JSON_ENCODING} from './values.ts';
import type { PluginInvocationContext } from './runtime.ts';
import { parseReviewSubject, reviewIdentityDigest } from './review-subject.ts';
import { readBoundArtifact } from './source-approval.ts';

export interface SourceBinding {
  readonly identityEncoding?: typeof PORTABLE_JSON_ENCODING;
  readonly stageId: string;
  readonly inputDigest: string;
  readonly reviewStageId?: string;
}

export function parseSourceBinding(value: unknown): SourceBinding {
  const binding = value as SourceBinding | undefined;
  if (!binding || Object.keys(binding).some(key => !['stageId', 'inputDigest', 'reviewStageId', 'identityEncoding'].includes(key))
    || (Object.hasOwn(binding, 'identityEncoding') && binding.identityEncoding !== PORTABLE_JSON_ENCODING)
    || typeof binding.stageId !== 'string' || !binding.stageId
    || typeof binding.inputDigest !== 'string' || !/^sha256:[a-f0-9]{64}$/u.test(binding.inputDigest)
    || (binding.reviewStageId !== undefined && (typeof binding.reviewStageId !== 'string' || !binding.reviewStageId))) {
    throw new Error('SOURCE_PREFLIGHT_BINDING_INVALID');
  }
  return binding;
}

/** Only the explicitly selected, immutable ancestor result establishes source admission. */
export async function sourcePreflight(value: unknown, context: PluginInvocationContext) {
  const binding = parseSourceBinding(value);
  const artifacts = context.contract.artifacts.filter(item => item.namespace === 'kubeclaw.preflight-contract'
    && item.artifactId === 'source-preflight' && item.producer.stageId === binding.stageId
    && item.producer.runId === context.contract.lease.attempt.runId);
  const attempt = Math.max(...artifacts.map(item => item.producer.attemptNumber));
  const candidates = artifacts.filter(item => item.producer.attemptNumber === attempt);
  if (candidates.length !== 1) throw new Error('SOURCE_PREFLIGHT_REQUIRED');
  const result = await readBoundArtifact(candidates[0]!, context);
  if (result.schemaVersion !== 'source-preflight.v1' || result.outcome !== 'passed') throw new Error('SOURCE_PREFLIGHT_FAILED');
  const subject = parseReviewSubject(result.subject, context.contract.lease.attempt.runId);
  if (subject.identityEncoding !== binding.identityEncoding || subject.inputDigest !== binding.inputDigest || reviewIdentityDigest(result.contract, binding) !== subject.inputDigest) throw new Error('SOURCE_PREFLIGHT_INPUT_MISMATCH');
  return { binding, subject, contract: result.contract as Readonly<Record<string, unknown>> };
}

import {verifiedArtifactJsonText} from './artifact-json.ts';
import { sha256Text } from './values.ts';
import type { ArtifactRef } from './generated/contracts.ts';
import type { PluginInvocationContext } from './runtime.ts';

function implementationArtifacts(sourceStageId: string, context: PluginInvocationContext): ArtifactRef[] {
  return context.contract.artifacts.filter(artifact => artifact.producer.runId === context.contract.lease.attempt.runId
    && artifact.producer.stageId === sourceStageId && artifact.namespace === 'kubeclaw.implementation-agent'
    && artifact.artifactId.startsWith('implementation:'));
}

function atAttempt(candidates: ArtifactRef[], attemptNumber: number): ArtifactRef {
  const selected = candidates.filter(artifact => artifact.producer.attemptNumber === attemptNumber);
  if (selected.length !== 1) throw new Error('SOURCE_IMPLEMENTATION_ARTIFACT_MISSING_OR_AMBIGUOUS');
  return selected[0]!;
}

async function readImplementation(artifact: ArtifactRef, context: PluginInvocationContext): Promise<{ sourceRevision: string; headBefore: unknown }> {
  const response = await context.invoke('artifacts.read', { operation: 'get_json_bytes', resource: { type: 'artifact.object', canonicalId: artifact.artifactId },
    payload: { namespace: artifact.namespace, digest: artifact.digest, reference: artifact } });
  const serialized = verifiedArtifactJsonText(response, artifact);
  if (response.digest !== artifact.digest || response.sizeBytes !== artifact.sizeBytes
    || sha256Text(serialized) !== artifact.digest || Buffer.byteLength(serialized) !== artifact.sizeBytes) throw new Error('SOURCE_IMPLEMENTATION_ARTIFACT_CORRUPT');
  const result = response.value as { sourceRevision?: unknown; headBefore?: unknown; status?: unknown } | null;
  if (!result || result.status !== 'ready_for_testing' || typeof result.sourceRevision !== 'string'
    || !/^(?:[a-f0-9]{40}|[a-f0-9]{64})(?![\s\S])/u.test(result.sourceRevision)) throw new Error('SOURCE_IMPLEMENTATION_REVISION_INVALID');
  return { sourceRevision: result.sourceRevision, headBefore: result.headBefore };
}

/** Resolve the actual trusted implementation result, never ambient repository HEAD. */
export async function resolveSourceRevision(input: { readonly revision?: string; readonly sourceStageId?: string }, context: PluginInvocationContext): Promise<string> {
  if ((input.revision !== undefined) === (input.sourceStageId !== undefined)) throw new Error('SOURCE_REVISION_SELECTION_INVALID');
  if (input.revision !== undefined) {
    if (!/^(?:[a-f0-9]{40}|[a-f0-9]{64})(?![\s\S])/u.test(input.revision)) throw new Error('SOURCE_REVISION_INVALID');
    return input.revision;
  }
  const candidates = implementationArtifacts(input.sourceStageId!, context);
  return (await readImplementation(atAttempt(candidates, Math.max(...candidates.map(artifact => artifact.producer.attemptNumber))), context)).sourceRevision;
}

/** Keep the original module baseline across repairs, with the latest committed candidate. */
export async function resolveImplementationRevisions(sourceStageId: string, context: PluginInvocationContext): Promise<{ base: string; head: string }> {
  const candidates = implementationArtifacts(sourceStageId, context);
  const initial = atAttempt(candidates, Math.min(...candidates.map(artifact => artifact.producer.attemptNumber)));
  const latest = atAttempt(candidates, Math.max(...candidates.map(artifact => artifact.producer.attemptNumber)));
  const first = await readImplementation(initial, context);
  const last = initial === latest ? first : await readImplementation(latest, context);
  if (typeof first.headBefore !== 'string' || !/^(?:[a-f0-9]{40}|[a-f0-9]{64})(?![\s\S])/u.test(first.headBefore)) throw new Error('SOURCE_IMPLEMENTATION_BASE_INVALID');
  return { base: first.headBefore, head: last.sourceRevision };
}

import { createHash } from 'node:crypto';
import { types } from 'node:util';

export type OptionalAbsenceReader<T> = () => T;
export type ValueRecord = Record<string, any>;

export function selectDefinedValue<T>(...readers: Array<OptionalAbsenceReader<T>>): T {
  let lastValue: T | undefined;
  for (const reader of readers) {
    const value = reader();
    lastValue = value;
    if (value !== undefined && value !== null) return value;
  }
  return lastValue as T;
}

export function selectTruthyValue<T>(...readers: Array<OptionalAbsenceReader<T>>): T {
  let lastValue: T | undefined;
  for (const reader of readers) {
    const value = reader();
    lastValue = value;
    if (value) return value;
  }
  return lastValue as T;
}

export function arrayValue<T = any>(value: unknown): T[] {
  return Array.isArray(value) ? value as T[] : [];
}

export function objectRecord(value: unknown): ValueRecord {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as ValueRecord : {};
}

export function textValue(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

export function selectPresentValue(...values: unknown[]): string {
  return values.find((value) => typeof value === 'string' && value.length > 0) as string | undefined ?? '';
}

// Preserve the existing ordering: these bytes already identify durable artifacts
// and effect payloads. A portable ordering requires a separately versioned cutover.
export function canonicalJson(value: unknown): string {
  return serializeJsonValue(value, new Set(), (left, right) => left.localeCompare(right));
}

function dataProperty(value: object, key: PropertyKey): unknown {
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor || !('value' in descriptor) || !descriptor.enumerable) {
    throw new Error('CANONICAL_JSON_PROPERTY_INVALID');
  }
  return descriptor.value;
}

type KeyOrder = (left: string, right: string) => number;

/** Named UTF-16 code-unit ordering; JSON scalar rules and validation match the legacy codec. */
export const PORTABLE_JSON_ENCODING = 'kubeclaw-json.utf16.v1' as const;
export function portableJson(value: unknown): string {
  return serializeJsonValue(value, new Set(), (left, right) => left < right ? -1 : left > right ? 1 : 0);
}

function serializeJsonValue(value: unknown, seen: Set<object>, order: KeyOrder): string {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return JSON.stringify(value);
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error('CANONICAL_JSON_NUMBER_INVALID');
    return JSON.stringify(value);
  }
  if (typeof value !== 'object') throw new Error('CANONICAL_JSON_VALUE_UNSUPPORTED');
  if (types.isProxy(value)) throw new Error('CANONICAL_JSON_PROXY_UNSUPPORTED');
  if (seen.has(value)) throw new Error('CANONICAL_JSON_CYCLE');
  seen.add(value);
  try {
    const keys = Reflect.ownKeys(value);
    if (Array.isArray(value)) return serializeJsonArray(value, keys, seen, order);
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) throw new Error('CANONICAL_JSON_PROTOTYPE_INVALID');
    if (keys.some((key) => typeof key !== 'string')) throw new Error('CANONICAL_JSON_PROPERTY_INVALID');
    return `{${(keys as string[]).sort(order)
      .map((key) => `${JSON.stringify(key)}:${serializeJsonValue(dataProperty(value, key), seen, order)}`)
      .join(',')}}`;
  } finally {
    seen.delete(value);
  }
}

function serializeJsonArray(value: unknown[], keys: PropertyKey[], seen: Set<object>, order: KeyOrder): string {
  if (Object.getPrototypeOf(value) !== Array.prototype) throw new Error('CANONICAL_JSON_PROTOTYPE_INVALID');
  if (keys.length !== value.length + 1) throw new Error('CANONICAL_JSON_ARRAY_INVALID');
  const entries: string[] = [];
  for (let index = 0; index < value.length; index++) {
    entries.push(serializeJsonValue(dataProperty(value, String(index)), seen, order));
  }
  return `[${entries.join(',')}]`;
}

export function sha256Text(value: string): `sha256:${string}` {
  return `sha256:${createHash('sha256').update(value).digest('hex')}`;
}

export function sha256Bytes(value: Uint8Array): `sha256:${string}` {
  return `sha256:${createHash('sha256').update(value).digest('hex')}`;
}

const DEFAULT_SENSITIVE_KEY = /(?:authorization|cookie|password|secret|token|api[_-]?key|credential)/i;

function redact(value: unknown, depth: number): unknown {
  if (depth > 16) return '[truncated]';
  if (Array.isArray(value)) {
    return value.slice(0, 1_000).map((entry) => redact(entry, depth + 1));
  }
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>)
      .slice(0, 1_000)
      .map(([key, entry]) => [
        key,
        DEFAULT_SENSITIVE_KEY.test(key) ? '[redacted]' : redact(entry, depth + 1),
      ]));
  }
  if (typeof value === 'string' && value.length > 65_536) return `${value.slice(0, 65_536)}[truncated]`;
  return value;
}

export function redactStructuredValue(value: unknown): unknown {
  return redact(value, 0);
}

