import fs from 'node:fs';
import type { CommandRunnerOptions } from './types.ts';

export function cgroupRoot(value: string): string {
  const root = fs.realpathSync(value);
  const controllers = fs.readFileSync(`${root}/cgroup.controllers`, 'utf8').trim().split(/\s+/u);
  if (!['pids', 'memory', 'cpu'].every((controller) => controllers.includes(controller))) {
    throw new Error('COMMAND_CGROUP_CONTROLLERS_UNAVAILABLE');
  }
  const subtreeControl = `${root}/cgroup.subtree_control`;
  try { fs.writeFileSync(subtreeControl, '+pids +memory +cpu'); }
  catch { throw new Error('COMMAND_CGROUP_CONTROLLERS_NOT_DELEGATED'); }
  const enabled = fs.readFileSync(subtreeControl, 'utf8').trim().split(/\s+/u);
  if (!['pids', 'memory', 'cpu'].every((controller) => enabled.includes(controller))) {
    throw new Error('COMMAND_CGROUP_CONTROLLERS_NOT_ENABLED');
  }
  return root;
}

export function createCgroup(options: CommandRunnerOptions, maximumProcesses: number, memoryBytes: number, cpuMillis: number,
  maximumExecutionMs: number): string | undefined {
  if (!options.cgroupRoot) return undefined;
  const root = cgroupRoot(options.cgroupRoot);
  const group = fs.mkdtempSync(`${root}/kubeclaw-command-`);
  try {
    fs.writeFileSync(`${group}/pids.max`, String(maximumProcesses + 1));
    fs.writeFileSync(`${group}/memory.max`, String(memoryBytes));
    if (fs.existsSync(`${group}/memory.swap.max`)) fs.writeFileSync(`${group}/memory.swap.max`, '0');
    const cpuPeriodMicroseconds = 100_000;
    const cpuQuotaMicroseconds = Math.max(1_000, Math.min(cpuPeriodMicroseconds,
      Math.floor((cpuMillis / maximumExecutionMs) * cpuPeriodMicroseconds)));
    fs.writeFileSync(`${group}/cpu.max`, `${cpuQuotaMicroseconds} ${cpuPeriodMicroseconds}`);
    return group;
  } catch (error) {
    try { fs.rmdirSync(group); } catch { /* INTENTIONAL_NONCRITICAL(cgroup_setup_cleanup_failed): Preserve the original setup error. */ }
    throw error;
  }
}

export function cleanupCgroup(group: string | undefined): void {
  if (!group) return;
  try { fs.writeFileSync(`${group}/cgroup.kill`, '1'); } catch { /* INTENTIONAL_NONCRITICAL(cgroup_already_empty): Preserve existing best-effort cgroup cleanup after process termination. */ }
  try { fs.rmdirSync(group); } catch { /* INTENTIONAL_NONCRITICAL(cgroup_removal_pending): The kernel can finish removal after the final process exits. */ }
}

import type { ChildProcessByStdio } from 'node:child_process';
import type { Readable } from 'node:stream';
import { CommandProcessGroup } from './process-group.ts';
import { cleanupCgroup } from './cgroup.ts';
import { processFacts } from './process-facts.ts';
import { CommandRunError, type CommandOutputRecord } from './types.ts';

type ManagedChild = ChildProcessByStdio<null, Readable, Readable>;
export interface ExecutionLimits {
  readonly maxOutputBytes: number;
  readonly maxExecutionMs: number;
  readonly maximumProcesses: number;
  readonly memoryBytes: number;
  readonly cpuMillis: number;
  readonly openFiles: number;
}
interface ExecutionOptions {
  readonly child: ManagedChild;
  readonly signal: AbortSignal;
  readonly limits: ExecutionLimits;
  readonly graceMs: number;
  readonly sandboxed: boolean;
  readonly cgroup: string | undefined;
}
const MAXIMUM_OUTPUT_RECORDS = 4096;

export class CommandExecution {
  readonly result: Promise<Readonly<Record<string, unknown>>>;
  readonly finished: Promise<void>;
  readonly #options: ExecutionOptions;
  readonly #group: CommandProcessGroup;
  readonly #output = { stdout: '', stderr: '', bytes: 0, sequence: 0, records: [] as CommandOutputRecord[] };
  readonly #resources = { cpuTimeMs: 0, maximumMemoryBytes: 0, maximumProcesses: 1 };
  readonly #timeout: NodeJS.Timeout;
  readonly #sampleTimer: NodeJS.Timeout;
  #pendingError: Error | undefined;
  #settled = false;
  #resolve!: (result: Readonly<Record<string, unknown>>) => void;
  #reject!: (error: Error) => void;
  #finishActive!: () => void;
  #failActive!: (error: Error) => void;
  readonly #abort = (): void => this.#fail(new Error('ADAPTER_CANCELLED', { cause: this.#options.signal.reason }));

  constructor(options: ExecutionOptions) {
    this.#options = options;
    this.#group = new CommandProcessGroup(options.child, options.graceMs, options.cgroup);
    this.result = new Promise((resolve, reject) => { this.#resolve = resolve; this.#reject = reject; });
    this.finished = new Promise((resolve, reject) => { this.#finishActive = resolve; this.#failActive = reject; });
    this.#timeout = setTimeout(() => this.#fail(new Error('COMMAND_TIMEOUT')), options.limits.maxExecutionMs);
    this.#timeout.unref();
    this.#sampleTimer = setInterval(() => this.#sample(), 25);
    this.#sampleTimer.unref();
    options.signal.addEventListener('abort', this.#abort, { once: true });
    options.child.stdout.on('data', (chunk: Buffer) => this.#append('stdout', chunk));
    options.child.stderr.on('data', (chunk: Buffer) => this.#append('stderr', chunk));
    options.child.once('error', (error) => this.#settle(error));
    options.child.once('close', (code, signal) => { void this.#close(code, signal); });
  }

  terminate(): void { this.#group.terminate(); }

  #fail(error: Error): void {
    this.#pendingError ??= error;
    this.terminate();
  }

  #stopMonitoring(): void {
    clearTimeout(this.#timeout);
    clearInterval(this.#sampleTimer);
    this.#options.signal.removeEventListener('abort', this.#abort);
  }

  #settle(error?: Error, code?: number | null, signal?: NodeJS.Signals | null): void {
    if (this.#settled) return;
    this.#settled = true;
    this.#stopMonitoring();
    const result = { exitCode: code ?? null, signal: signal ?? null, stdout: this.#output.stdout,
      stderr: this.#output.stderr, records: this.#output.records, resources: this.#resources };
    if (error) this.#reject(new CommandRunError(error.message, result, { cause: error }));
    else this.#resolve(result);
  }

  async #close(code: number | null, signal: NodeJS.Signals | null): Promise<void> {
    this.#stopMonitoring();
    this.#sample();
    try {
      await this.#group.cleanup();
      cleanupCgroup(this.#options.cgroup);
      this.#settle(this.#pendingError, code, signal);
    } catch (error) {
      const failure = error instanceof Error ? error : new Error(String(error));
      this.#settle(failure, code, signal);
      this.#failActive(failure);
    } finally { this.#finishActive(); }
  }

  #append(stream: 'stdout' | 'stderr', chunk: Buffer): void {
    if (this.#settled) return;
    this.#output.bytes += chunk.byteLength;
    if (this.#output.bytes > this.#options.limits.maxOutputBytes) {
      this.#fail(new Error('COMMAND_OUTPUT_LIMIT_EXCEEDED'));
      return;
    }
    const content = chunk.toString('utf8');
    this.#output[stream] += content;
    const last = this.#output.records.at(-1);
    if (last?.stream === stream) {
      this.#output.records[this.#output.records.length - 1] = { ...last, content: last.content + content };
    } else if (this.#output.records.length >= MAXIMUM_OUTPUT_RECORDS) {
      this.#fail(new Error('COMMAND_OUTPUT_RECORD_LIMIT_EXCEEDED'));
    } else {
      this.#output.sequence += 1;
      this.#output.records.push({ sequence: this.#output.sequence, stream, content });
    }
  }

  #sample(): void {
    const facts = processFacts(this.#options.child.pid ?? -1, this.#options.cgroup);
    if (!facts) {
      if (this.#options.cgroup) this.#fail(new Error('COMMAND_CGROUP_ACCOUNTING_UNAVAILABLE'));
      return;
    }
    const count = this.#options.sandboxed ? Math.max(0, facts.processes - 1) : facts.processes;
    this.#resources.cpuTimeMs = Math.max(this.#resources.cpuTimeMs, facts.cpuTimeMs);
    this.#resources.maximumMemoryBytes = Math.max(this.#resources.maximumMemoryBytes, facts.memoryBytes);
    this.#resources.maximumProcesses = Math.max(this.#resources.maximumProcesses, count);
    if (count > this.#options.limits.maximumProcesses) this.#fail(new Error('COMMAND_PROCESS_LIMIT_EXCEEDED'));
    else if (facts.memoryBytes > this.#options.limits.memoryBytes) this.#fail(new Error('COMMAND_MEMORY_LIMIT_EXCEEDED'));
    else if (facts.cpuTimeMs > this.#options.limits.cpuMillis) this.#fail(new Error('COMMAND_CPU_LIMIT_EXCEEDED'));
  }
}

import fs from 'node:fs';
import type { ProcessFacts } from './types.ts';

function cgroupFacts(group: string): ProcessFacts | null {
  try {
    const cpu = fs.readFileSync(`${group}/cpu.stat`, 'utf8');
    const usageMicroseconds = Number(cpu.match(/^usage_usec\s+(\d+)$/mu)?.[1] ?? NaN);
    const memoryBytes = Number(fs.readFileSync(`${group}/memory.current`, 'utf8').trim());
    const processes = Number(fs.readFileSync(`${group}/pids.current`, 'utf8').trim());
    if (![usageMicroseconds, memoryBytes, processes].every(Number.isFinite)) return null;
    return { cpuTimeMs: usageMicroseconds / 1000, memoryBytes, processes };
  } catch {
    // INTENTIONAL_NONCRITICAL(cgroup_sample_unavailable): Preserve the existing sampled-accounting fallback.
    return null;
  }
}

function processParents(): Map<number, number> {
  const parents = new Map<number, number>();
  for (const name of fs.readdirSync('/proc')) {
    if (!/^\d+$/u.test(name)) continue;
    try {
      const status = fs.readFileSync(`/proc/${name}/status`, 'utf8');
      parents.set(Number(name), Number(status.match(/^PPid:\s+(\d+)$/mu)?.[1] ?? -1));
    } catch { /* INTENTIONAL_NONCRITICAL(process_exited_during_sample): /proc entries can disappear while sampling. */ }
  }
  return parents;
}

function descendantIds(pid: number, parents: ReadonlyMap<number, number>): Set<number> {
  const descendants = new Set([pid]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [candidate, parent] of parents) {
      if (!descendants.has(parent) || descendants.has(candidate)) continue;
      descendants.add(candidate);
      changed = true;
    }
  }
  return descendants;
}

function sampledFacts(descendants: ReadonlySet<number>): ProcessFacts {
  let cpuTimeMs = 0;
  let memoryBytes = 0;
  for (const processId of descendants) {
    try {
      const stat = fs.readFileSync(`/proc/${processId}/stat`, 'utf8');
      const fields = stat.slice(stat.lastIndexOf(')') + 2).trim().split(/\s+/u);
      cpuTimeMs += ((Number(fields[11]) + Number(fields[12])) / 100) * 1000;
      const status = fs.readFileSync(`/proc/${processId}/status`, 'utf8');
      memoryBytes += Number(status.match(/^VmRSS:\s+(\d+)\s+kB$/mu)?.[1] ?? 0) * 1024;
    } catch { /* INTENTIONAL_NONCRITICAL(process_exited_during_sample): /proc entries can disappear while sampling. */ }
  }
  return { cpuTimeMs, memoryBytes, processes: descendants.size };
}

export function processFacts(pid: number, cgroup?: string): ProcessFacts | null {
  try {
    const sampled = sampledFacts(descendantIds(pid, processParents()));
    const group = cgroup ? cgroupFacts(cgroup) : null;
    return { cpuTimeMs: group?.cpuTimeMs ?? sampled.cpuTimeMs,
      memoryBytes: group?.memoryBytes ?? sampled.memoryBytes, processes: sampled.processes };
  } catch {
    // INTENTIONAL_NONCRITICAL(process_sample_unavailable): null explicitly reports an unavailable sample to execution.
    return null;
  }
}

import fs from 'node:fs';
import type { ChildProcess } from 'node:child_process';
import { captureLinuxProcessGroup, linuxProcessGroupRunning } from '@kubeclaw/plugin-foundation/processes/linux-process-group';

// The leader's exit and the group's lifetime are separate: descendants may
// still own stdout/stderr, even when child.exitCode is already set.
export class CommandProcessGroup {
  readonly #child: ChildProcess;
  readonly #graceMs: number;
  readonly #cgroup: string | undefined;
  #deadline: number | undefined;
  #force: NodeJS.Timeout | undefined;
  readonly #linuxGroup: number | undefined;
  readonly #identityError: unknown;

  constructor(child: ChildProcess, graceMs: number, cgroup?: string) {
    this.#child = child;
    this.#graceMs = graceMs;
    this.#cgroup = cgroup;
    if (process.platform === 'linux' && child.pid) {
      try { this.#linuxGroup = captureLinuxProcessGroup(child.pid); }
      catch (error) { this.#identityError = error; }
    }
  }

  terminate(): void {
    if (this.#deadline !== undefined) return;
    this.#deadline = Date.now() + this.#graceMs;
    this.#signal('SIGTERM');
    this.#force = setTimeout(() => this.#signal('SIGKILL'), this.#graceMs);
    this.#force.unref();
  }

  async cleanup(): Promise<void> {
    if (this.#alive()) {
      this.terminate();
      // Reuse the original deadline; close must not restart the grace budget.
      while (this.#alive() && Date.now() < this.#deadline!) {
        await new Promise((resolve) => setTimeout(resolve, Math.min(10, this.#deadline! - Date.now())));
      }
      if (this.#alive()) this.#signal('SIGKILL');
    }
    clearTimeout(this.#force);
    await this.#acknowledgeExit();
  }

  async #acknowledgeExit(): Promise<void> {
    if (process.platform !== 'linux' || !this.#alive()) return;
    if (this.#linuxGroup === undefined) throw new Error('COMMAND_PROCESS_GROUP_IDENTITY_UNAVAILABLE', { cause: this.#identityError });
    const deadline = (this.#deadline ?? Date.now()) + 1_000;
    while (await linuxProcessGroupRunning(this.#linuxGroup, deadline)) {
      if (Date.now() >= deadline) throw new Error('COMMAND_PROCESS_GROUP_CLEANUP_TIMEOUT');
      this.#signal('SIGKILL');
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  }

  #signal(signal: NodeJS.Signals): void {
    if (signal === 'SIGKILL' && this.#cgroup) {
      try { fs.writeFileSync(`${this.#cgroup}/cgroup.kill`, '1'); }
      catch { /* INTENTIONAL_NONCRITICAL(cgroup_kill_failed): Still signal the process group; cgroup cleanup is retried after close. */ }
    }
    try {
      if (process.platform !== 'win32' && this.#child.pid) process.kill(-this.#child.pid, signal);
      else this.#child.kill(signal);
    } catch { /* INTENTIONAL_NONCRITICAL(group_already_stopped): The process group can stop before delivery. */ }
  }

  #alive(): boolean {
    if (process.platform === 'win32' || !this.#child.pid) return false;
    try { process.kill(-this.#child.pid, 0); return true; }
    catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ESRCH') return false;
      throw new Error('COMMAND_PROCESS_GROUP_STATUS_FAILED', { cause: error });
    }
  }
}

import { spawn } from 'node:child_process';
import { cgroupRoot, createCgroup } from './cgroup.ts';
import { CommandExecution, type ExecutionLimits } from './execution.ts';
import type { CommandRunRequest, CommandRunnerOptions } from './types.ts';
export { CommandRunError } from './types.ts';
export type { CommandOutputRecord, CommandRunLimits, CommandRunRequest, CommandRunnerOptions } from './types.ts';

function positive(value: number | undefined, fallback: number): number {
  return Number.isSafeInteger(value) && Number(value) > 0 ? Number(value) : fallback;
}

function executionLimits(options: CommandRunnerOptions, request: CommandRunRequest): ExecutionLimits {
  const limits = request.limits ?? {};
  const maxExecutionMs = Math.min(options.maxExecutionMs, positive(limits.maxExecutionMs, options.maxExecutionMs));
  return {
    maxOutputBytes: Math.min(options.maxOutputBytes, positive(limits.maxOutputBytes, options.maxOutputBytes)),
    maxExecutionMs,
    maximumProcesses: Math.min(positive(options.maximumProcesses, 1024), positive(limits.maximumProcesses, positive(options.maximumProcesses, 1024))),
    memoryBytes: Math.min(positive(options.sandboxMemoryBytes, 1024 * 1024 * 1024), positive(limits.memoryBytes, positive(options.sandboxMemoryBytes, 1024 * 1024 * 1024))),
    cpuMillis: Math.min(positive(options.sandboxCpuMillis, maxExecutionMs), positive(limits.cpuMillis, positive(options.sandboxCpuMillis, maxExecutionMs))),
    openFiles: Math.min(positive(options.sandboxOpenFiles, 256), positive(limits.openFiles, positive(options.sandboxOpenFiles, 256))),
  };
}

function spawnArguments(options: CommandRunnerOptions, request: CommandRunRequest, limits: ExecutionLimits, cgroup: string | undefined): string[] {
  if (!options.sandboxExecutable) return [...request.args];
  return [String(limits.memoryBytes), String(Math.max(1, Math.ceil(limits.cpuMillis / 1000))), String(Math.max(8, limits.openFiles)),
    ...(cgroup ? ['--cgroup', cgroup] : []),
    ...(request.readOnlyRoots ?? []).flatMap((root) => ['--read-root', root]),
    ...(request.writableRoot ? ['--write-root', request.writableRoot] : []), request.executable, ...request.args];
}

export class CommandRunner {
  readonly #active = new Set<CommandExecution>();
  readonly #options: CommandRunnerOptions;
  #stopping = false;

  constructor(options: CommandRunnerOptions) {
    if (options.cgroupRoot) cgroupRoot(options.cgroupRoot);
    this.#options = options;
  }
  get stopping(): boolean { return this.#stopping; }

  async run(executable: string, args: readonly string[], cwd: string, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>>;
  async run(request: CommandRunRequest, signal: AbortSignal): Promise<Readonly<Record<string, unknown>>>;
  async run(executableOrRequest: string | CommandRunRequest, argsOrSignal: readonly string[] | AbortSignal,
    cwd?: string, legacySignal?: AbortSignal): Promise<Readonly<Record<string, unknown>>> {
    const request: CommandRunRequest = typeof executableOrRequest === 'string'
      ? { executable: executableOrRequest, args: argsOrSignal as readonly string[], cwd: cwd!, environment: {} }
      : executableOrRequest;
    const signal = (typeof executableOrRequest === 'string' ? legacySignal : argsOrSignal) as AbortSignal;
    if (this.#stopping) throw new Error('ADAPTER_SHUTTING_DOWN');
    if (signal.aborted) throw new Error('ADAPTER_CANCELLED', { cause: signal.reason });
    if (!this.#options.sandboxExecutable && (request.writableRoot !== undefined || request.readOnlyRoots !== undefined)) {
      throw new Error('COMMAND_SANDBOX_REQUIRED');
    }
    const limits = executionLimits(this.#options, request);
    const cgroup = this.#options.sandboxExecutable
      ? createCgroup(this.#options, limits.maximumProcesses, limits.memoryBytes, limits.cpuMillis, limits.maxExecutionMs) : undefined;
    if (this.#options.sandboxExecutable && !cgroup && !this.#options.allowSampledProcessLimit) throw new Error('COMMAND_CGROUP_REQUIRED');
    const program = this.#options.sandboxExecutable ?? request.executable;
    const programArgs = spawnArguments(this.#options, request, limits, cgroup);
    const child = spawn(program, programArgs, { cwd: request.cwd, detached: process.platform !== 'win32',
      shell: false, stdio: ['ignore', 'pipe', 'pipe'], env: { ...(request.environment ?? {}) } });
    const graceMs = this.#options.sandboxExecutable ? Math.max(250, this.#options.terminationGraceMs) : this.#options.terminationGraceMs;
    const execution = new CommandExecution({ child, signal, limits, graceMs, cgroup, sandboxed: Boolean(this.#options.sandboxExecutable) });
    this.#active.add(execution);
    void execution.finished.then(() => this.#active.delete(execution), () => this.#active.delete(execution));
    return execution.result;
  }

  async shutdown(): Promise<void> {
    this.#stopping = true;
    const active = [...this.#active];
    active.forEach((execution) => execution.terminate());
    await Promise.all(active.map((execution) => execution.finished));
  }
}

export interface CommandOutputRecord {
  readonly sequence: number;
  readonly stream: 'stdout' | 'stderr';
  readonly content: string;
}

export interface CommandRunLimits {
  readonly maxOutputBytes?: number;
  readonly maxExecutionMs?: number;
  readonly maximumProcesses?: number;
  readonly memoryBytes?: number;
  readonly cpuMillis?: number;
  readonly openFiles?: number;
}

export interface CommandRunRequest {
  readonly executable: string;
  readonly args: readonly string[];
  readonly cwd: string;
  readonly environment?: Readonly<Record<string, string>>;
  readonly writableRoot?: string;
  readonly readOnlyRoots?: readonly string[];
  readonly limits?: CommandRunLimits;
}

export interface CommandRunnerOptions {
  readonly maxOutputBytes: number;
  readonly maxExecutionMs: number;
  readonly terminationGraceMs: number;
  readonly maximumProcesses?: number;
  readonly sandboxExecutable?: string;
  readonly sandboxMemoryBytes?: number;
  readonly sandboxCpuMillis?: number;
  readonly sandboxOpenFiles?: number;
  readonly cgroupRoot?: string;
  readonly allowSampledProcessLimit?: boolean;
}

export interface ProcessFacts {
  readonly cpuTimeMs: number;
  readonly memoryBytes: number;
  readonly processes: number;
}

export class CommandRunError extends Error {
  readonly output: Readonly<Record<string, unknown>>;
  constructor(code: string, output: Readonly<Record<string, unknown>>, options?: ErrorOptions) {
    super(code, options);
    this.name = 'CommandRunError';
    this.output = output;
  }
}

